/// Maximum slot age (record.slot vs health.snapshot_slot).  Records older than
/// this many slots behind the chain head are dropped as stale.
/// 4 slots ≈ 1.6s at 400ms/slot — generous enough for network jitter, tight
/// enough to prevent acting on information the chain has already moved past.
const MAX_SLOT_AGE: u64 = 4;
const SIGNER_TOKEN_INVENTORY_CAP: usize = 128;
const EMPTY_SIGNER_TOKEN_ACCOUNT: SignerTokenAccountEntry = SignerTokenAccountEntry {
    token_account_pubkey: [0u8; 32],
    mint_pubkey: [0u8; 32],
    token_program_id: [0u8; 32],
    amount_raw: 0,
    initialized: false,
};
static EMPTY_SIGNER_TOKEN_INVENTORY: SignerTokenInventory = SignerTokenInventory::empty();

/// How often (in Jito attribution decisions) to emit tactic telemetry per worker.
const TACTIC_TELEMETRY_INTERVAL: u64 = 10_000;

#[derive(Debug, Clone, Copy, serde::Deserialize)]
pub struct SignerTokenAccountEntry {
    pub token_account_pubkey: [u8; 32],
    pub mint_pubkey: [u8; 32],
    pub token_program_id: [u8; 32],
    pub amount_raw: u64,
    pub initialized: bool,
}

#[derive(Debug, Clone)]
pub struct SignerTokenInventory {
    pub entries: [SignerTokenAccountEntry; SIGNER_TOKEN_INVENTORY_CAP],
    pub len: u16,
}

impl SignerTokenInventory {
    pub const fn empty() -> Self {
        Self {
            entries: [EMPTY_SIGNER_TOKEN_ACCOUNT; SIGNER_TOKEN_INVENTORY_CAP],
            len: 0,
        }
    }

    #[inline(always)]
    pub fn find_by_token_account(
        &self,
        token_account_pubkey: &[u8; 32],
    ) -> Option<&SignerTokenAccountEntry> {
        let len = self.len.min(SIGNER_TOKEN_INVENTORY_CAP as u16) as usize;
        let mut idx = 0usize;
        while idx < len {
            let entry = &self.entries[idx];
            if &entry.token_account_pubkey == token_account_pubkey {
                return Some(entry);
            }
            idx += 1;
        }
        None
    }

    #[inline(always)]
    pub fn find_unique_by_mint(&self, mint_pubkey: &[u8; 32]) -> Option<&SignerTokenAccountEntry> {
        let len = self.len.min(SIGNER_TOKEN_INVENTORY_CAP as u16) as usize;
        let mut idx = 0usize;
        let mut found: Option<&SignerTokenAccountEntry> = None;
        while idx < len {
            let entry = &self.entries[idx];
            if &entry.mint_pubkey == mint_pubkey {
                if found.is_some() {
                    return None;
                }
                found = Some(entry);
            }
            idx += 1;
        }
        found
    }
}

impl Default for SignerTokenInventory {
    fn default() -> Self {
        Self::empty()
    }
}

