#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum PoolStateMissReason {
    TagMapAbsent,
    ArenaIndexOob,
    ArenaTorn,
    PubkeyMismatch,
}

impl PoolStateMissReason {
    fn code(self) -> u8 {
        match self {
            Self::TagMapAbsent => DPDK_POOL_STATE_MISS_REASON_TAG_MAP_ABSENT,
            Self::ArenaIndexOob => DPDK_POOL_STATE_MISS_REASON_ARENA_INDEX_OOB,
            Self::ArenaTorn => DPDK_POOL_STATE_MISS_REASON_ARENA_TORN,
            Self::PubkeyMismatch => DPDK_POOL_STATE_MISS_REASON_PUBKEY_MISMATCH,
        }
    }
}

