#[inline(always)]
fn is_dpdk_signal(signal_source: u8) -> bool {
    signal_source == SIGNAL_SOURCE_DPDK
}

#[inline(always)]
fn is_private_packet_signal(signal_source: u8) -> bool {
    matches!(signal_source, SIGNAL_SOURCE_AFXDP | SIGNAL_SOURCE_DPDK)
}

#[inline(always)]
fn record_dpdk_worker_counter(signal_source: u8, counter: &AtomicU64) {
    if is_dpdk_signal(signal_source) {
        counter.fetch_add(1, Ordering::Relaxed);
    }
}

