fn encode_route_reason(reason: RouteReason) -> &'static str {
    match reason {
        RouteReason::PublicTarget => "public_target",
        RouteReason::PublicRpcScoutDirect => "public_rpc_scout_direct",
        RouteReason::OverCap => "over_cap",
        RouteReason::AtbaNoJito => "atba_no_jito",
        RouteReason::ApexPartialNoJito => "apex_partial_no_jito",
        RouteReason::JitoAtba => "jito_atba",
        RouteReason::JitoApexPartial => "jito_apex_partial",
        RouteReason::HarmonicFreshPlain => "harmonic_fresh_plain",
        RouteReason::JitoStaleHarmonicReroute => "jito_stale_harmonic_reroute",
        RouteReason::StaleHarmonicNoJito => "stale_harmonic_no_jito",
        RouteReason::JitoQuarantinedFallback => "jito_quarantined_fallback",
        RouteReason::QuarantinedHarmonicNoJito => "quarantined_harmonic_no_jito",
        RouteReason::JitoTacticMaskFallback => "jito_tactic_mask_fallback",
        RouteReason::TacticMaskNoJito => "tactic_mask_no_jito",
        RouteReason::JitoEgressGateFallback => "jito_egress_gate_fallback",
        RouteReason::HarmonicEgressGateNoJito => "harmonic_egress_gate_no_jito",
        RouteReason::JitoDirect => "jito_direct",
        RouteReason::NoViableRoute => "no_viable_route",
    }
}

fn encode_route_decision(decision: RouteDecision) -> &'static str {
    match decision {
        RouteDecision::JitoBundle => "jito_bundle",
        RouteDecision::PublicRpcScout => "public_rpc_scout",
        RouteDecision::TpuQuicPublic => "tpu_quic_public",
        RouteDecision::HarmonicBundle => "harmonic_bundle",
        RouteDecision::Drop => "drop",
        #[cfg(feature = "public_lane")]
        RouteDecision::StakedBlast => "staked_blast",
    }
}

fn encode_r1_drop_reason(reason: R1DropReason) -> &'static str {
    match reason {
        R1DropReason::Source => "source",
        R1DropReason::NonPrivateGrade => "non_private_grade",
        R1DropReason::ShadowGuard => "shadow_guard",
        R1DropReason::MicroMarket => "micro_market",
        R1DropReason::RetainedEvFloor => "retained_ev_floor",
        R1DropReason::NetAfterFeeFloor => "net_after_fee_floor",
        R1DropReason::Egress => "egress",
        R1DropReason::Inventory => "inventory",
        R1DropReason::Cap => "cap",
        R1DropReason::Stale => "stale",
        R1DropReason::Health => "health",
        R1DropReason::PublicRoute => "public_route",
        R1DropReason::ManualAllowlistSelected => "manual_allowlist_selected",
        R1DropReason::PassAllForbidden => "pass_all_forbidden",
    }
}

fn r1_auto_admission_reject_reason_from_drop(reason: R1DropReason) -> R1AutoAdmissionRejectReason {
    match reason {
        R1DropReason::Source => R1AutoAdmissionRejectReason::Source,
        R1DropReason::NonPrivateGrade => R1AutoAdmissionRejectReason::NonPrivateGrade,
        R1DropReason::ShadowGuard => R1AutoAdmissionRejectReason::ShadowGuard,
        R1DropReason::MicroMarket
        | R1DropReason::RetainedEvFloor
        | R1DropReason::NetAfterFeeFloor => R1AutoAdmissionRejectReason::MicroMarket,
        R1DropReason::Egress => R1AutoAdmissionRejectReason::Egress,
        R1DropReason::Inventory => R1AutoAdmissionRejectReason::Inventory,
        R1DropReason::Cap => R1AutoAdmissionRejectReason::Cap,
        R1DropReason::Stale | R1DropReason::Health => R1AutoAdmissionRejectReason::Stale,
        R1DropReason::PublicRoute
        | R1DropReason::ManualAllowlistSelected
        | R1DropReason::PassAllForbidden => R1AutoAdmissionRejectReason::PublicRoute,
    }
}

