fn format_segment_magic(magic: [u8; 8]) -> String {
    let ascii = String::from_utf8_lossy(&magic);
    let hex = magic
        .iter()
        .map(|byte| format!("{byte:02X}"))
        .collect::<Vec<_>>()
        .join("");
    format!("ascii={ascii:?} hex={hex}")
}

fn log_clmm_exact_quote_sidecar_failure(
    path: &Path,
    err: &ClmmExactQuoteArenaError,
    diagnostics: Option<ClmmExactQuoteArenaOpenDiagnostics>,
) {
    let expected_header_size = core::mem::size_of::<shadow_ipc::segment::SegmentHeader64B>() as u16;
    let expected_payload_align = 256u16;
    let expected_payload_offset = shadow_ipc::segment::align_up(
        expected_header_size as usize,
        expected_payload_align as usize,
    ) as u32;
    let expected_payload_element_size =
        core::mem::size_of::<shadow_ipc::clmm_exact_quote_sidecar::ClmmExactQuoteArenaElement>();
    let found = diagnostics.unwrap_or_default();
    eprintln!("WARN  CLMM exact quote sidecar unavailable:");
    eprintln!("  path={}", path.display());
    eprintln!("  reason={}", err.reason_str());
    eprintln!("  magic={}", format_segment_magic(found.magic));
    eprintln!("  expected_segment_id={CLMM_EXACT_QUOTE_SEGMENT_ID}");
    eprintln!("  found_segment_id={}", found.segment_id);
    eprintln!("  expected_version={CLMM_EXACT_QUOTE_VERSION}");
    eprintln!("  found_version={}", found.version);
    eprintln!("  expected_header_size={expected_header_size}");
    eprintln!("  found_header_size={}", found.header_size);
    eprintln!("  expected_payload_align={expected_payload_align}");
    eprintln!("  found_payload_align={}", found.payload_align);
    eprintln!("  expected_payload_offset={expected_payload_offset}");
    eprintln!("  found_payload_offset={}", found.payload_offset);
    eprintln!("  payload_element_size={expected_payload_element_size}");
    eprintln!("  payload_size={}", found.payload_size);
    eprintln!("  total_size={}", found.total_size);
    eprintln!(
        "  capacity_derived={}",
        found
            .derived_capacity
            .map(|value| value.to_string())
            .unwrap_or_default()
    );
    eprintln!("  file_size={}", found.file_size);
    if found.inode != 0 {
        eprintln!("  inode={}", found.inode);
    }
    if let Some(mtime_unix_ns) = found.mtime_unix_ns {
        eprintln!("  mtime_unix_ns={mtime_unix_ns}");
    }
}

