fn reset_public_scout_attempt_latch_state() {
    PUBLIC_SCOUT_ATTEMPT_COUNT.store(0, Ordering::Relaxed);
    WORKER_PUBLIC_SCOUT_ATTEMPT_LATCH_SET.store(0, Ordering::Relaxed);
    WORKER_PUBLIC_SCOUT_ATTEMPT_LATCH_DROP_COUNT.store(0, Ordering::Relaxed);
    *public_scout_attempt_latch_first_signature_slot()
        .lock()
        .expect("public scout attempt latch first signature mutex poisoned") = [0u8; 64];
}

fn parse_public_scout_filter_venue(value: &str) -> Option<u8> {
    let normalized = value.trim().to_ascii_lowercase();
    if normalized.is_empty() {
        return None;
    }
    match normalized.as_str() {
        "raydium_clmm" => Some(ingest_venue::RAYDIUM_CLMM),
        "meteora_damm_v2" => Some(ingest_venue::METEORA_DAMM_V2),
        "raydium_cpmm" => Some(ingest_venue::RAYDIUM_CPMM),
        "pumpfun_amm" => Some(ingest_venue::PUMPFUN_AMM),
        "raydium_v4" => Some(ingest_venue::RAYDIUM_V4),
        _ => normalized.parse::<u8>().ok(),
    }
}

fn parse_public_scout_filter_pool(value: &str) -> Option<[u8; 32]> {
    let normalized = value.trim();
    if normalized.is_empty() {
        return None;
    }
    let decoded = bs58::decode(normalized).into_vec().ok()?;
    decoded.try_into().ok()
}

fn parse_public_scout_filter_signature(value: &str) -> Option<[u8; 64]> {
    let normalized = value.trim();
    if normalized.is_empty() {
        return None;
    }
    let decoded = bs58::decode(normalized).into_vec().ok()?;
    decoded.try_into().ok()
}

fn parse_public_scout_filter_pubkeys(value: &str) -> Vec<[u8; 32]> {
    let mut pubkeys = Vec::new();
    for item in value
        .split(',')
        .map(str::trim)
        .filter(|item| !item.is_empty())
    {
        let Some(pubkey) = parse_public_scout_filter_pool(item) else {
            continue;
        };
        if !pubkeys.iter().any(|existing| existing == &pubkey) {
            pubkeys.push(pubkey);
        }
    }
    pubkeys
}

fn load_public_scout_proof_filter() -> PublicScoutProofFilter {
    let allow_only_venue_id = std::env::var("SHADOW_RUN42_ALLOW_ONLY_VENUE_ID")
        .ok()
        .and_then(|value| parse_public_scout_filter_venue(&value));
    let allow_only_pool_pubkey = std::env::var("SHADOW_RUN42_ALLOW_ONLY_POOL")
        .ok()
        .and_then(|value| parse_public_scout_filter_pool(&value));
    let allow_only_mint_in_pubkey = std::env::var("SHADOW_RUN42_ALLOW_ONLY_MINT_IN")
        .ok()
        .and_then(|value| parse_public_scout_filter_pool(&value));
    let allow_only_mint_out_pubkey = std::env::var("SHADOW_RUN42_ALLOW_ONLY_MINT_OUT")
        .ok()
        .and_then(|value| parse_public_scout_filter_pool(&value));
    PublicScoutProofFilter {
        allow_only_venue_id,
        allow_only_pool_pubkey,
        allow_only_mint_in_pubkey,
        allow_only_mint_out_pubkey,
    }
}

