fn load_run40_scorecard_replay_source_override() -> Run40ScorecardReplaySourceOverride {
    let source_relaxed_dev_proof = std::env::var("SHADOW_RUN40_SOURCE_RELAXED_DEV_PROOF")
        .map(|value| {
            matches!(
                value.to_ascii_lowercase().as_str(),
                "1" | "true" | "yes" | "on"
            )
        })
        .unwrap_or(false);
    let scorecard_replay_dev_proof = std::env::var("SHADOW_RUN40_SCORECARD_REPLAY_DEV_PROOF")
        .map(|value| {
            matches!(
                value.to_ascii_lowercase().as_str(),
                "1" | "true" | "yes" | "on"
            )
        })
        .unwrap_or(false);
    let live_market_recurrence_required =
        std::env::var("SHADOW_RUN40_LIVE_MARKET_RECURRENCE_REQUIRED")
            .map(|value| {
                matches!(
                    value.to_ascii_lowercase().as_str(),
                    "1" | "true" | "yes" | "on"
                )
            })
            .unwrap_or(true);
    let selected_signature = std::env::var("SHADOW_RUN40_SELECTED_SIGNATURE")
        .ok()
        .and_then(|value| parse_public_scout_filter_signature(&value));
    let selected_pool_pubkey = std::env::var("SHADOW_RUN40_SELECTED_POOL")
        .ok()
        .and_then(|value| parse_public_scout_filter_pool(&value));
    let selected_source_matches = std::env::var("SHADOW_RUN40_SELECTED_SOURCE")
        .map(|value| value.trim().eq_ignore_ascii_case("external_geyser"))
        .unwrap_or(false);
    let selected_target_route_family_matches =
        std::env::var("SHADOW_RUN40_SELECTED_TARGET_ROUTE_FAMILY")
            .map(|value| value.trim().eq_ignore_ascii_case("tpu_quic_public"))
            .unwrap_or(false);

    match (
        source_relaxed_dev_proof,
        scorecard_replay_dev_proof,
        live_market_recurrence_required,
        selected_signature,
        selected_pool_pubkey,
        selected_source_matches,
        selected_target_route_family_matches,
    ) {
        (true, true, false, Some(selected_signature), Some(selected_pool_pubkey), true, true) => {
            Run40ScorecardReplaySourceOverride {
                enabled: true,
                selected_signature,
                selected_pool_pubkey,
            }
        }
        _ => Run40ScorecardReplaySourceOverride::default(),
    }
}

fn load_run38_held_input_mint_filter() -> Run38HeldInputMintFilter {
    let Some(raw_value) = std::env::var("SHADOW_RUN42_HELD_INPUT_MINTS")
        .or_else(|_| std::env::var("SHADOW_RUN29C_HELD_INPUT_MINTS"))
        .ok()
    else {
        return Run38HeldInputMintFilter::default();
    };

    Run38HeldInputMintFilter {
        active: true,
        mint_in_pubkeys: parse_public_scout_filter_pubkeys(&raw_value),
    }
}

