#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
struct Run40ScorecardReplayTargetMatch {
    signature_match: bool,
    pool_match: bool,
    replay_marker_match: bool,
}

impl Run40ScorecardReplayTargetMatch {
    fn exact_match(self) -> bool {
        self.pool_match && (self.signature_match || self.replay_marker_match)
    }
}

fn match_run40_scorecard_replay_target(
    record: &IngressRecord,
    config: Run40ScorecardReplaySourceOverride,
) -> Run40ScorecardReplayTargetMatch {
    Run40ScorecardReplayTargetMatch {
        signature_match: record.signature == config.selected_signature,
        pool_match: record.pool_pubkey == config.selected_pool_pubkey,
        replay_marker_match: record.is_scorecard_replay_dev_proof(),
    }
}

fn is_run40_scorecard_replay_exact_target(record: &IngressRecord) -> bool {
    let config = current_run40_scorecard_replay_source_override();
    config.enabled
        && record.signal_source == SIGNAL_SOURCE_EXTERNAL_GEYSER
        && match_run40_scorecard_replay_target(record, config).exact_match()
}

fn clmm_exact_quote_request_wait_ms(record: &IngressRecord) -> u64 {
    if is_run40_scorecard_replay_exact_target(record) {
        CLMM_EXACT_QUOTE_REQUEST_WAIT_MS_SCORECARD_REPLAY
    } else {
        CLMM_EXACT_QUOTE_REQUEST_WAIT_MS
    }
}

fn scorecard_replay_target_no_send_quote_neutralization_enabled(
    record: &IngressRecord,
    route_decision: RouteDecision,
    rollout_no_send_backend: bool,
) -> bool {
    rollout_no_send_backend
        && route_decision == RouteDecision::TpuQuicPublic
        && is_run40_scorecard_replay_exact_target(record)
}

fn trace_run40_scorecard_replay_gate(record: &IngressRecord, stage: &str, detail: &str) {
    if !is_run40_scorecard_replay_exact_target(record) {
        return;
    }
    println!(
        "TRACE scorecard_replay_gate stage={} signature={} pool={} mint_in={} mint_out={} slot={} signal_source={} detail={}",
        stage,
        bs58::encode(record.signature).into_string(),
        bs58::encode(record.pool_pubkey).into_string(),
        bs58::encode(record.mint_in).into_string(),
        bs58::encode(record.mint_out).into_string(),
        record.slot,
        record.signal_source,
        detail,
    );
}

fn trace_run40_scorecard_replay_quote_result(
    record: &IngressRecord,
    intent: &WorkerIntent,
    result: ClmmExactQuotePrimeResult,
    wait_budget_ms: u64,
) {
    if !is_run40_scorecard_replay_exact_target(record) {
        return;
    }
    let diag = result
        .timeout_diag
        .unwrap_or_else(ClmmExactQuotePrimeTimeoutDiag::no_snapshot);
    println!(
        "TRACE scorecard_replay_quote outcome={} request_id={} publish_ok_unix_ns={} request_unix_ns={} wait_budget_ms={} pool_index={} amount_in={} mismatch_reason={} snapshot_sequence={} snapshot_slot0_sequence={} snapshot_slot1_sequence={} snapshot_request_id={} snapshot_amount_in={} snapshot_last_update_unix_ns={} snapshot_validity_flags={} snapshot_status={} signature={} pool={}",
        encode_clmm_exact_quote_prime_outcome(result.outcome),
        result.request_id,
        result.publish_ok_unix_ns,
        intent.ingress_unix_ns,
        wait_budget_ms,
        intent.pool_index,
        result.request_amount_in,
        encode_clmm_exact_quote_prime_mismatch_reason(diag.reason),
        diag.snapshot_sequence,
        diag.snapshot_slot0_sequence,
        diag.snapshot_slot1_sequence,
        diag.snapshot_request_id,
        diag.snapshot_amount_in,
        diag.snapshot_last_update_unix_ns,
        diag.snapshot_validity_flags,
        clmm_exact_quote_status_str(diag.snapshot_status),
        bs58::encode(record.signature).into_string(),
        bs58::encode(intent.expected_pool_pubkey).into_string(),
    );
}

#[cfg(test)]
pub(crate) fn set_run40_scorecard_replay_source_override_for_test(
    value: Option<Run40ScorecardReplaySourceOverride>,
) {
    *RUN40_SCORECARD_REPLAY_SOURCE_OVERRIDE_OVERRIDE
        .get_or_init(|| Mutex::new(None))
        .lock()
        .expect("run40 scorecard replay source override mutex poisoned") = value;
}

fn apply_run40_scorecard_replay_source_override(
    shared: &SharedRefs<'_>,
    record: &IngressRecord,
    route: &HydratedRoute,
    candidate: &mut R1CandidateContext,
) -> bool {
    let config = current_run40_scorecard_replay_source_override();
    if !config.enabled
        || record.signal_source != SIGNAL_SOURCE_EXTERNAL_GEYSER
        || route.outcome.decision != RouteDecision::TpuQuicPublic
    {
        return false;
    }

    WORKER_SCORECARD_REPLAY_SOURCE_OVERRIDE_SEEN.fetch_add(1, Ordering::Relaxed);
    let target_match = match_run40_scorecard_replay_target(record, config);
    let signature_match = target_match.signature_match;
    let pool_match = target_match.pool_match;
    if signature_match {
        WORKER_SCORECARD_REPLAY_SOURCE_OVERRIDE_SIGNATURE_MATCH.fetch_add(1, Ordering::Relaxed);
    }
    if pool_match {
        WORKER_SCORECARD_REPLAY_SOURCE_OVERRIDE_POOL_MATCH.fetch_add(1, Ordering::Relaxed);
    }
    if target_match.exact_match() {
        trace_run40_scorecard_replay_gate(
            record,
            "source_override_seen",
            &format!(
                "route_decision={} route_reason={} rollout_no_send_backend={}",
                encode_route_decision(route.outcome.decision),
                encode_route_reason(route.outcome.reason),
                shared.rollout_no_send_backend
            ),
        );
    }
    if shared.rollout_no_send_backend {
        WORKER_SCORECARD_REPLAY_SOURCE_OVERRIDE_LIVE_SEND_BLOCKED.fetch_add(1, Ordering::Relaxed);
    }
    if !shared.rollout_no_send_backend || !target_match.exact_match() {
        return false;
    }

    trace_run40_scorecard_replay_gate(
        record,
        "source_override_applied",
        &format!(
            "route_decision={} route_reason={}",
            encode_route_decision(route.outcome.decision),
            encode_route_reason(route.outcome.reason)
        ),
    );
    // This is a gate-local dev override for the exact replay-selected row only.
    // The record metadata remains external_geyser/non-private-grade everywhere else.
    candidate.signal_source = SIGNAL_SOURCE_AFXDP;
    candidate.private_grade = true;
    WORKER_SCORECARD_REPLAY_SOURCE_OVERRIDE_APPLIED.fetch_add(1, Ordering::Relaxed);
    true
}

fn apply_run40_scorecard_replay_stale_slot_bypass(
    shared: &SharedRefs<'_>,
    record: &IngressRecord,
    snapshot_slot: u64,
) -> bool {
    let config = current_run40_scorecard_replay_source_override();
    if !config.enabled || record.signal_source != SIGNAL_SOURCE_EXTERNAL_GEYSER {
        return false;
    }

    WORKER_SCORECARD_REPLAY_STALE_SLOT_BYPASS_SEEN.fetch_add(1, Ordering::Relaxed);
    WORKER_SCORECARD_REPLAY_ORIGINAL_SLOT.store(record.slot, Ordering::Relaxed);
    WORKER_SCORECARD_REPLAY_CURRENT_SLOT.store(snapshot_slot, Ordering::Relaxed);
    WORKER_SCORECARD_REPLAY_SLOT_GAP
        .store(snapshot_slot.saturating_sub(record.slot), Ordering::Relaxed);

    let target_match = match_run40_scorecard_replay_target(record, config);
    let signature_match = target_match.signature_match;
    let pool_match = target_match.pool_match;
    if signature_match {
        WORKER_SCORECARD_REPLAY_STALE_SLOT_BYPASS_SIGNATURE_MATCH.fetch_add(1, Ordering::Relaxed);
    }
    if pool_match {
        WORKER_SCORECARD_REPLAY_STALE_SLOT_BYPASS_POOL_MATCH.fetch_add(1, Ordering::Relaxed);
    }
    if !shared.rollout_no_send_backend || !target_match.exact_match() {
        return false;
    }

    trace_run40_scorecard_replay_gate(
        record,
        "stale_slot_bypass_applied",
        &format!(
            "snapshot_slot={} slot_gap={} rollout_no_send_backend={}",
            snapshot_slot,
            snapshot_slot.saturating_sub(record.slot),
            shared.rollout_no_send_backend
        ),
    );
    WORKER_SCORECARD_REPLAY_STALE_SLOT_BYPASS_APPLIED.fetch_add(1, Ordering::Relaxed);
    true
}

fn apply_run40_scorecard_replay_route_override(
    shared: &SharedRefs<'_>,
    record: &IngressRecord,
    route: &mut HydratedRoute,
) -> bool {
    let config = current_run40_scorecard_replay_source_override();
    if !config.enabled || record.signal_source != SIGNAL_SOURCE_EXTERNAL_GEYSER {
        return false;
    }

    WORKER_SCORECARD_REPLAY_ROUTE_OVERRIDE_SEEN.fetch_add(1, Ordering::Relaxed);
    let target_match = match_run40_scorecard_replay_target(record, config);
    let signature_match = target_match.signature_match;
    let pool_match = target_match.pool_match;
    if signature_match {
        WORKER_SCORECARD_REPLAY_ROUTE_OVERRIDE_SIGNATURE_MATCH.fetch_add(1, Ordering::Relaxed);
    }
    if pool_match {
        WORKER_SCORECARD_REPLAY_ROUTE_OVERRIDE_POOL_MATCH.fetch_add(1, Ordering::Relaxed);
    }
    if target_match.exact_match() {
        trace_run40_scorecard_replay_gate(
            record,
            "route_override_seen",
            &format!(
                "route_decision={} route_reason={} rollout_no_send_backend={}",
                encode_route_decision(route.outcome.decision),
                encode_route_reason(route.outcome.reason),
                shared.rollout_no_send_backend
            ),
        );
    }
    let from_public_target = route.outcome.decision == RouteDecision::Drop
        && route.outcome.reason == RouteReason::PublicTarget;
    if from_public_target {
        WORKER_SCORECARD_REPLAY_ROUTE_OVERRIDE_FROM_PUBLIC_TARGET.fetch_add(1, Ordering::Relaxed);
    }
    if !shared.rollout_no_send_backend || !target_match.exact_match() || !from_public_target {
        return false;
    }

    route.outcome.decision = RouteDecision::TpuQuicPublic;
    route.outcome.reason = RouteReason::PublicRpcScoutDirect;
    trace_run40_scorecard_replay_gate(
        record,
        "route_override_applied",
        &format!(
            "route_decision={} route_reason={}",
            encode_route_decision(route.outcome.decision),
            encode_route_reason(route.outcome.reason)
        ),
    );
    WORKER_SCORECARD_REPLAY_ROUTE_OVERRIDE_APPLIED.fetch_add(1, Ordering::Relaxed);
    WORKER_SCORECARD_REPLAY_ROUTE_OVERRIDE_TO_TPU_QUIC_PUBLIC.fetch_add(1, Ordering::Relaxed);
    true
}

