fn trace_public_scout_filter_drop(
    record: &IngressRecord,
    filter: PublicScoutProofFilter,
    reason: &str,
) {
    if !trace_public_rpc_scout_emit_enabled() {
        return;
    }

    println!(
        "TRACE public_rpc_scout_filter_drop reason={} venue_id={} pool={} mint_in={} mint_out={} allow_only_venue_id={} allow_only_pool={} allow_only_mint_in={} allow_only_mint_out={}",
        reason,
        record.venue_id,
        bs58::encode(record.pool_pubkey).into_string(),
        bs58::encode(record.mint_in).into_string(),
        bs58::encode(record.mint_out).into_string(),
        filter
            .allow_only_venue_id
            .map(|value| value.to_string())
            .unwrap_or_default(),
        filter
            .allow_only_pool_pubkey
            .map(|value| bs58::encode(value).into_string())
            .unwrap_or_default(),
        filter
            .allow_only_mint_in_pubkey
            .map(|value| bs58::encode(value).into_string())
            .unwrap_or_default(),
        filter
            .allow_only_mint_out_pubkey
            .map(|value| bs58::encode(value).into_string())
            .unwrap_or_default(),
    );
}

fn public_scout_proof_filter_allows(record: &IngressRecord) -> bool {
    public_scout_proof_filter_reject_reason(record).is_none()
}

fn public_scout_proof_filter_reject_reason(
    record: &IngressRecord,
) -> Option<R1ProofFilterRejectReason> {
    let filter = current_public_scout_proof_filter();
    if let Some(venue_id) = filter.allow_only_venue_id {
        if record.venue_id != venue_id {
            trace_public_scout_filter_drop(record, filter, "venue_mismatch");
            return Some(R1ProofFilterRejectReason::PublicScoutShape);
        }
    }
    if let Some(pool_pubkey) = filter.allow_only_pool_pubkey {
        if record.pool_pubkey != pool_pubkey {
            trace_public_scout_filter_drop(record, filter, "pool_mismatch");
            return Some(R1ProofFilterRejectReason::PublicScoutShape);
        }
    }
    if let Some(mint_in_pubkey) = filter.allow_only_mint_in_pubkey {
        if record.mint_in != mint_in_pubkey {
            trace_public_scout_filter_drop(record, filter, "mint_in_mismatch");
            return Some(R1ProofFilterRejectReason::PublicScoutShape);
        }
    }
    if let Some(mint_out_pubkey) = filter.allow_only_mint_out_pubkey {
        if record.mint_out != mint_out_pubkey {
            trace_public_scout_filter_drop(record, filter, "mint_out_mismatch");
            return Some(R1ProofFilterRejectReason::PublicScoutShape);
        }
    }
    None
}

fn public_scout_shape_source_ok(signal_source: u8) -> bool {
    matches!(
        signal_source_from_u8(signal_source),
        Some(SignalSource::PrivateMempool | SignalSource::PublicGeyser)
    )
}

fn classify_public_scout_shape_reject_from_filter(
    record: &IngressRecord,
    route: &HydratedRoute,
) -> PublicScoutShapeRejectReason {
    if route.outcome.decision != RouteDecision::PublicRpcScout {
        return PublicScoutShapeRejectReason::RouteNotPublicScout;
    }
    if !public_scout_shape_source_ok(record.signal_source) {
        return PublicScoutShapeRejectReason::WrongSource;
    }
    let filter = current_public_scout_proof_filter();
    if let Some(venue_id) = filter.allow_only_venue_id {
        if record.venue_id != venue_id {
            return PublicScoutShapeRejectReason::WrongVenue;
        }
    }
    PublicScoutShapeRejectReason::Other
}

fn classify_public_scout_shape_reject_from_template_drop(
    record: &IngressRecord,
    route: &HydratedRoute,
    template_drop_reason: TemplateDropReason,
) -> PublicScoutShapeRejectReason {
    if route.outcome.decision != RouteDecision::PublicRpcScout {
        return PublicScoutShapeRejectReason::RouteNotPublicScout;
    }
    if !public_scout_shape_source_ok(record.signal_source) {
        return PublicScoutShapeRejectReason::WrongSource;
    }
    if record.venue_id != ingest_venue::RAYDIUM_CLMM {
        return PublicScoutShapeRejectReason::WrongVenue;
    }
    match template_drop_reason {
        TemplateDropReason::NoTemplate | TemplateDropReason::MissingClmmAccounts => {
            PublicScoutShapeRejectReason::MissingTemplateFamily
        }
        TemplateDropReason::WrongRouteFamily
        | TemplateDropReason::InvalidSwapProgram
        | TemplateDropReason::InvalidGuardTemplate
        | TemplateDropReason::UnsupportedTokenProgram => {
            PublicScoutShapeRejectReason::RouteTemplateMismatch
        }
        TemplateDropReason::MissingInputAta
        | TemplateDropReason::MissingOutputAta
        | TemplateDropReason::Other
        | TemplateDropReason::None => PublicScoutShapeRejectReason::Other,
    }
}

fn target_public_scout_filter_match(record: &IngressRecord) -> TargetPublicScoutFilterMatch {
    let filter = current_public_scout_proof_filter();
    if require_any_public_scout_enabled() {
        let venue_id = filter
            .allow_only_venue_id
            .unwrap_or(ingest_venue::RAYDIUM_CLMM);
        if record.venue_id != venue_id {
            return TargetPublicScoutFilterMatch::TargetFilterMismatch;
        }
        return TargetPublicScoutFilterMatch::AnyCandidate;
    }
    let Some(pool_pubkey) = filter.allow_only_pool_pubkey else {
        return TargetPublicScoutFilterMatch::NotConfigured;
    };
    let Some(mint_in_pubkey) = filter.allow_only_mint_in_pubkey else {
        return TargetPublicScoutFilterMatch::NotConfigured;
    };
    let Some(mint_out_pubkey) = filter.allow_only_mint_out_pubkey else {
        return TargetPublicScoutFilterMatch::NotConfigured;
    };
    if let Some(venue_id) = filter.allow_only_venue_id {
        if record.venue_id != venue_id {
            return TargetPublicScoutFilterMatch::TargetFilterMismatch;
        }
    }
    if record.pool_pubkey != pool_pubkey
        || record.mint_in != mint_in_pubkey
        || record.mint_out != mint_out_pubkey
    {
        return TargetPublicScoutFilterMatch::TargetFilterMismatch;
    }
    TargetPublicScoutFilterMatch::Exact
}

fn exact_target_public_scout_record(record: &IngressRecord) -> bool {
    matches!(
        target_public_scout_filter_match(record),
        TargetPublicScoutFilterMatch::Exact
    )
}

fn run40_tpu_quic_filter_match(record: &IngressRecord) -> bool {
    let filter = current_tpu_quic_proof_filter();
    let mut configured = false;
    let replay_override = current_run40_scorecard_replay_source_override();
    if let Some(venue_id) = filter.allow_only_venue_id {
        configured = true;
        if record.venue_id != venue_id {
            return false;
        }
    }
    if let Some(pool_pubkey) = filter.allow_only_pool_pubkey {
        configured = true;
        if record.pool_pubkey != pool_pubkey {
            return false;
        }
    }
    if let Some(mint_in_pubkey) = filter.allow_only_mint_in_pubkey {
        configured = true;
        if record.mint_in != mint_in_pubkey {
            return false;
        }
    }
    if let Some(mint_out_pubkey) = filter.allow_only_mint_out_pubkey {
        configured = true;
        if record.mint_out != mint_out_pubkey {
            return false;
        }
    }
    if replay_override.enabled {
        configured = true;
        if !match_run40_scorecard_replay_target(record, replay_override).exact_match() {
            return false;
        }
    }
    configured
}

fn run40_replay_force_live_inventory_reservation(
    record: &IngressRecord,
    route: &HydratedRoute,
    rollout_no_send_backend: bool,
) -> bool {
    if !rollout_no_send_backend || route.outcome.decision != RouteDecision::TpuQuicPublic {
        return false;
    }
    let replay_override = current_run40_scorecard_replay_source_override();
    replay_override.enabled && match_run40_scorecard_replay_target(record, replay_override).exact_match()
}

fn apply_run40_tpu_quic_route_override(
    record: &IngressRecord,
    route: &mut HydratedRoute,
    rollout_no_send_backend: bool,
) -> bool {
    if !rollout_no_send_backend || !run40_tpu_quic_no_send_enabled() {
        return false;
    }
    if !run40_tpu_quic_filter_match(record) {
        return false;
    }
    if route.outcome.decision == RouteDecision::Drop
        || !route.ctx.timing_margin_ok
        || !route.ctx.jito_lane_admissible
    {
        return false;
    }
    route.outcome.decision = RouteDecision::TpuQuicPublic;
    route.outcome.reason = RouteReason::PublicRpcScoutDirect;
    true
}

fn apply_private_bundle_route_override(
    route: &mut HydratedRoute,
    cfg: &GuerrilaRoutingConfig,
) -> bool {
    if !cfg.block_private_bundle_routes {
        return false;
    }

    match route.outcome.decision {
        RouteDecision::JitoBundle | RouteDecision::HarmonicBundle => {
            route.outcome.decision = RouteDecision::TpuQuicPublic;
            true
        }
        _ => false,
    }
}

#[inline(always)]
fn is_run38_target_public_scout_clmm(
    record: &IngressRecord,
    route_decision: RouteDecision,
) -> bool {
    record.signal_source == SIGNAL_SOURCE_AFXDP
        && record.venue_id == ingest_venue::RAYDIUM_CLMM
        && route_decision == RouteDecision::PublicRpcScout
        && run38_held_input_mint_allowed(record)
}

fn set_last_run38_target(
    record: &IngressRecord,
    route_decision: RouteDecision,
    stage: Run38TargetStage,
    reject_reason: R1AutoAdmissionRejectReason,
) {
    let mut slot = run38_target_slot()
        .lock()
        .expect("run38 target mutex poisoned");
    *slot = Run38TargetIdentity {
        stage,
        reject_reason,
        pool_pubkey: record.pool_pubkey,
        mint_in_pubkey: record.mint_in,
        mint_out_pubkey: record.mint_out,
        route_decision,
        signal_source: record.signal_source,
        venue_id: record.venue_id,
    };
}

