#[inline(always)]
fn record_run38_target_r1_reject(
    record: &IngressRecord,
    route_decision: RouteDecision,
    reason: R1AutoAdmissionRejectReason,
) {
    if !is_run38_target_public_scout_clmm(record, route_decision) {
        return;
    }
    match reason {
        R1AutoAdmissionRejectReason::ProofFilter => {
            RUN38_TARGET_PUBLIC_SCOUT_CLMM_REJECT_PROOF_FILTER.fetch_add(1, Ordering::Relaxed);
        }
        R1AutoAdmissionRejectReason::MicroMarket => {
            RUN38_TARGET_PUBLIC_SCOUT_CLMM_REJECT_MICRO_MARKET.fetch_add(1, Ordering::Relaxed);
        }
        R1AutoAdmissionRejectReason::Inventory => {
            RUN38_TARGET_PUBLIC_SCOUT_CLMM_REJECT_INVENTORY.fetch_add(1, Ordering::Relaxed);
        }
        R1AutoAdmissionRejectReason::TemplateExecutability => {
            RUN38_TARGET_PUBLIC_SCOUT_CLMM_REJECT_TEMPLATE_EXECUTABILITY
                .fetch_add(1, Ordering::Relaxed);
        }
        R1AutoAdmissionRejectReason::AttemptLatch => {
            RUN38_TARGET_PUBLIC_SCOUT_CLMM_REJECT_ATTEMPT_LATCH.fetch_add(1, Ordering::Relaxed);
        }
        _ => {}
    }
    set_last_run38_target(record, route_decision, Run38TargetStage::R1Reject, reason);
}

