#[inline(always)]
fn record_run38_target_pipeline_probe(
    record: &IngressRecord,
    route_decision: RouteDecision,
    probe: &NoSendPipelineProbe,
) {
    if !is_run38_target_public_scout_clmm(record, route_decision) {
        return;
    }
    if probe.pm_reservation_created {
        RUN38_TARGET_PUBLIC_SCOUT_CLMM_PM_CREATED.fetch_add(1, Ordering::Relaxed);
        set_last_run38_target(
            record,
            route_decision,
            Run38TargetStage::PmCreated,
            R1AutoAdmissionRejectReason::None,
        );
    }
    if probe.emit_attempted {
        RUN38_TARGET_PUBLIC_SCOUT_CLMM_EMIT_ATTEMPT.fetch_add(1, Ordering::Relaxed);
        set_last_run38_target(
            record,
            route_decision,
            Run38TargetStage::EmitAttempt,
            R1AutoAdmissionRejectReason::None,
        );
    }
    if probe.emit_ok {
        RUN38_TARGET_PUBLIC_SCOUT_CLMM_TRANSPORT_ATTEMPT.fetch_add(1, Ordering::Relaxed);
        set_last_run38_target(
            record,
            route_decision,
            Run38TargetStage::TransportAttempt,
            R1AutoAdmissionRejectReason::None,
        );
    }
}

fn encode_target_public_scout_blocked_reason(
    reason: TargetPublicScoutBlockedReason,
) -> &'static str {
    match reason {
        TargetPublicScoutBlockedReason::RoutePolicyPrivateOnly => "route_policy_private_only",
        TargetPublicScoutBlockedReason::PublicScoutDisabled => "public_scout_disabled",
        TargetPublicScoutBlockedReason::TargetFilterMismatch => "target_filter_mismatch",
        TargetPublicScoutBlockedReason::EgressUnavailable => "egress_unavailable",
        TargetPublicScoutBlockedReason::TemplateInvalid => "template_invalid",
        TargetPublicScoutBlockedReason::GuardFailed => "guard_failed",
    }
}

fn trace_target_public_scout_route_override(
    record: &IngressRecord,
    previous_decision: RouteDecision,
    previous_reason: RouteReason,
) {
    if !trace_public_rpc_scout_emit_enabled() || record.venue_id != ingest_venue::RAYDIUM_CLMM {
        return;
    }

    println!(
        "TRACE target_public_scout_route_override reason=route_policy_private_only previous_decision={} previous_reason={} pool={} mint_in={} mint_out={} signature={}",
        encode_route_decision(previous_decision),
        encode_route_reason(previous_reason),
        bs58::encode(record.pool_pubkey).into_string(),
        bs58::encode(record.mint_in).into_string(),
        bs58::encode(record.mint_out).into_string(),
        bs58::encode(record.signature).into_string(),
    );
}

fn trace_target_public_scout_blocked(
    record: &IngressRecord,
    route: &HydratedRoute,
    stage: &str,
    reason: TargetPublicScoutBlockedReason,
    detail: &str,
) {
    if !trace_public_rpc_scout_emit_enabled() || record.venue_id != ingest_venue::RAYDIUM_CLMM {
        return;
    }

    println!(
        "TRACE target_public_scout_blocked stage={} reason={} detail={} decision={} route_reason={} pool={} mint_in={} mint_out={} signature={}",
        stage,
        encode_target_public_scout_blocked_reason(reason),
        detail,
        encode_route_decision(route.outcome.decision),
        encode_route_reason(route.outcome.reason),
        bs58::encode(record.pool_pubkey).into_string(),
        bs58::encode(record.mint_in).into_string(),
        bs58::encode(record.mint_out).into_string(),
        bs58::encode(record.signature).into_string(),
    );
}

fn apply_target_public_scout_route_override(
    record: &IngressRecord,
    route: &mut HydratedRoute,
) -> TargetPublicScoutRouteAction {
    if !require_target_public_scout_enabled() && !require_any_public_scout_enabled() {
        return TargetPublicScoutRouteAction::NotApplicable;
    }

    match target_public_scout_filter_match(record) {
        TargetPublicScoutFilterMatch::TargetFilterMismatch => {
            return TargetPublicScoutRouteAction::NotApplicable;
        }
        TargetPublicScoutFilterMatch::NotConfigured => {
            return TargetPublicScoutRouteAction::Blocked(
                TargetPublicScoutBlockedReason::TargetFilterMismatch,
            );
        }
        TargetPublicScoutFilterMatch::Exact | TargetPublicScoutFilterMatch::AnyCandidate => {}
    }

    if route.outcome.decision == RouteDecision::PublicRpcScout {
        return TargetPublicScoutRouteAction::NotApplicable;
    }
    if !route.ctx.public_rpc_scout_route_enabled {
        return TargetPublicScoutRouteAction::Blocked(
            TargetPublicScoutBlockedReason::PublicScoutDisabled,
        );
    }
    if route.outcome.decision == RouteDecision::Drop
        || !route.ctx.timing_margin_ok
        || !route.ctx.jito_lane_admissible
    {
        return TargetPublicScoutRouteAction::Blocked(
            TargetPublicScoutBlockedReason::EgressUnavailable,
        );
    }

    let previous_decision = route.outcome.decision;
    let previous_reason = route.outcome.reason;
    route.outcome.decision = RouteDecision::PublicRpcScout;
    route.outcome.reason = RouteReason::PublicRpcScoutDirect;
    TargetPublicScoutRouteAction::Forced {
        previous_decision,
        previous_reason,
    }
}

fn reserve_public_scout_attempt(signature: [u8; 64]) -> bool {
    let max_attempts = PUBLIC_SCOUT_MAX_ATTEMPTS_PER_WINDOW.load(Ordering::Relaxed);
    if max_attempts == u64::MAX {
        return true;
    }
    loop {
        let current = PUBLIC_SCOUT_ATTEMPT_COUNT.load(Ordering::Relaxed);
        if current >= max_attempts {
            WORKER_PUBLIC_SCOUT_ATTEMPT_LATCH_DROP_COUNT.fetch_add(1, Ordering::Relaxed);
            return false;
        }
        if PUBLIC_SCOUT_ATTEMPT_COUNT
            .compare_exchange(current, current + 1, Ordering::Relaxed, Ordering::Relaxed)
            .is_ok()
        {
            if current == 0 {
                WORKER_PUBLIC_SCOUT_ATTEMPT_LATCH_SET.fetch_add(1, Ordering::Relaxed);
                set_public_scout_attempt_latch_first_signature(signature);
            }
            return true;
        }
    }
}

