fn record_template_drop(identity: TemplateDropIdentity) {
    match identity.reason {
        TemplateDropReason::None => {}
        TemplateDropReason::NoTemplate => {
            WORKER_TEMPLATE_DROP_NO_TEMPLATE.fetch_add(1, Ordering::Relaxed);
        }
        TemplateDropReason::WrongRouteFamily => {
            WORKER_TEMPLATE_DROP_WRONG_ROUTE_FAMILY.fetch_add(1, Ordering::Relaxed);
        }
        TemplateDropReason::MissingClmmAccounts => {
            WORKER_TEMPLATE_DROP_MISSING_CLMM_ACCOUNTS.fetch_add(1, Ordering::Relaxed);
        }
        TemplateDropReason::MissingInputAta => {
            WORKER_TEMPLATE_DROP_MISSING_INPUT_ATA.fetch_add(1, Ordering::Relaxed);
        }
        TemplateDropReason::MissingOutputAta => {
            WORKER_TEMPLATE_DROP_MISSING_OUTPUT_ATA.fetch_add(1, Ordering::Relaxed);
        }
        TemplateDropReason::InvalidSwapProgram => {
            WORKER_TEMPLATE_DROP_INVALID_SWAP_PROGRAM.fetch_add(1, Ordering::Relaxed);
        }
        TemplateDropReason::InvalidGuardTemplate => {
            WORKER_TEMPLATE_DROP_INVALID_GUARD_TEMPLATE.fetch_add(1, Ordering::Relaxed);
        }
        TemplateDropReason::UnsupportedTokenProgram => {
            WORKER_TEMPLATE_DROP_UNSUPPORTED_TOKEN_PROGRAM.fetch_add(1, Ordering::Relaxed);
        }
        TemplateDropReason::Other => {
            WORKER_TEMPLATE_DROP_OTHER.fetch_add(1, Ordering::Relaxed);
        }
    }
    set_last_template_drop(identity);
}

