fn capture_clmm_invalid_snapshot_diag(
    reason: ClmmExactQuoteFailureReason,
    intent: Option<&WorkerIntent>,
    clmm_exact_quote_arena: Option<&MappedClmmExactQuoteArena>,
) {
    if !clmm_exact_quote_failure_is_invalid_snapshot(reason) {
        return;
    }
    let Some(intent) = intent else {
        return;
    };
    let Some(arena) = clmm_exact_quote_arena else {
        return;
    };
    let Some(snapshot) = arena.read_active_at(intent.pool_index) else {
        return;
    };
    set_last_clmm_invalid_snapshot(snapshot);
}

#[inline(always)]
fn record_pipeline_error_diag(
    error: &PipelineError,
    intent: Option<&WorkerIntent>,
    clmm_exact_quote_arena: Option<&MappedClmmExactQuoteArena>,
) {
    set_last_process_intent_error(error);
    match error {
        PipelineError::BlockhashMissing => {
            WORKER_PIPELINE_ERR_BLOCKHASH_MISSING.fetch_add(1, Ordering::Relaxed);
        }
        PipelineError::RoutingHydrationFailed | PipelineError::RoutingDropped(_) => {
            WORKER_PIPELINE_ERR_ROUTING_HYDRATION.fetch_add(1, Ordering::Relaxed);
        }
        PipelineError::LookupFailed(failure) => {
            WORKER_PIPELINE_ERR_LOOKUP.fetch_add(1, Ordering::Relaxed);
            record_lookup_failure_reason(failure.reason);
            if let Some(intent) = intent {
                set_last_lookup_fail_fields(
                    intent.expected_pool_pubkey,
                    intent.expected_mint_in_pubkey,
                    intent.expected_mint_out_pubkey,
                    intent.venue_id,
                    failure.reason,
                    failure.diagnostics,
                );
            }
        }
        PipelineError::ClmmExactQuoteUnavailable(reason) => {
            WORKER_PIPELINE_ERR_QUOTE.fetch_add(1, Ordering::Relaxed);
            record_clmm_exact_quote_failure_reason(*reason);
            capture_clmm_invalid_snapshot_diag(*reason, intent, clmm_exact_quote_arena);
        }
        PipelineError::QuoteFailed => {
            WORKER_PIPELINE_ERR_QUOTE.fetch_add(1, Ordering::Relaxed);
        }
        PipelineError::InvalidDirection => {
            WORKER_PIPELINE_ERR_INVALID_DIRECTION.fetch_add(1, Ordering::Relaxed);
        }
        PipelineError::OverlayOverflow => {
            WORKER_PIPELINE_ERR_OVERLAY_OVERFLOW.fetch_add(1, Ordering::Relaxed);
        }
        PipelineError::RolloutNoSendSinkMissing => {
            WORKER_PIPELINE_ERR_NO_SEND_SINK_MISSING.fetch_add(1, Ordering::Relaxed);
        }
        PipelineError::PolicyRejected(policy_reason) => {
            WORKER_PIPELINE_ERR_POLICY.fetch_add(1, Ordering::Relaxed);
            match policy_reason {
                PolicyDropReason::ApexPartialNotPositive => {
                    WORKER_PIPELINE_ERR_POLICY_APEX_NOT_POSITIVE.fetch_add(1, Ordering::Relaxed);
                }
                PolicyDropReason::AtbaMissingOrStaleDistToTick => {
                    WORKER_PIPELINE_ERR_POLICY_ATBA_MISSING_DIST.fetch_add(1, Ordering::Relaxed);
                }
                PolicyDropReason::DominanceGateLiveSuppressed => {
                    WORKER_PIPELINE_ERR_POLICY_DOMINANCE_LIVE.fetch_add(1, Ordering::Relaxed);
                }
                PolicyDropReason::NoUsableLutBank => {
                    WORKER_PIPELINE_ERR_POLICY_NO_USABLE_LUT.fetch_add(1, Ordering::Relaxed);
                }
                PolicyDropReason::NetAfterFeeFloor => {
                    WORKER_PIPELINE_ERR_POLICY_NET_AFTER_FEE_FLOOR.fetch_add(1, Ordering::Relaxed);
                }
                PolicyDropReason::Over15SolLiveInput => {
                    WORKER_PIPELINE_ERR_POLICY_OVER_15_SOL_LIVE_INPUT
                        .fetch_add(1, Ordering::Relaxed);
                }
                PolicyDropReason::FeeClampZeroOrInvalid => {
                    WORKER_PIPELINE_ERR_POLICY_FEE_CLAMP_INVALID.fetch_add(1, Ordering::Relaxed);
                }
                PolicyDropReason::InventoryBreach => {
                    WORKER_PIPELINE_ERR_POLICY_INVENTORY_BREACH.fetch_add(1, Ordering::Relaxed);
                }
            }
        }
        PipelineError::EmitFailed(EmitError::BuildFailed(BuildError::InvalidTemplateForRoute)) => {
            WORKER_PIPELINE_ERR_EMIT.fetch_add(1, Ordering::Relaxed);
            WORKER_PIPELINE_ERR_EMIT_INVALID_TEMPLATE_FOR_ROUTE.fetch_add(1, Ordering::Relaxed);
        }
        PipelineError::EmitFailed(EmitError::BuildFailed(BuildError::TacticNotAllowedOnRoute)) => {
            WORKER_PIPELINE_ERR_EMIT.fetch_add(1, Ordering::Relaxed);
            WORKER_PIPELINE_ERR_EMIT_TACTIC_NOT_ALLOWED_ON_ROUTE.fetch_add(1, Ordering::Relaxed);
        }
        PipelineError::EmitFailed(EmitError::BuildFailed(BuildError::OversizedPayload)) => {
            WORKER_PIPELINE_ERR_EMIT.fetch_add(1, Ordering::Relaxed);
            WORKER_PIPELINE_ERR_EMIT_OVERSIZED_PAYLOAD.fetch_add(1, Ordering::Relaxed);
        }
        PipelineError::EmitFailed(EmitError::BuildFailed(
            BuildError::UnsupportedAdditionalSigner,
        )) => {
            WORKER_PIPELINE_ERR_EMIT.fetch_add(1, Ordering::Relaxed);
            WORKER_PIPELINE_ERR_EMIT_UNSUPPORTED_ADDITIONAL_SIGNER.fetch_add(1, Ordering::Relaxed);
        }
        PipelineError::EmitFailed(EmitError::BuildFailed(BuildError::InvalidGuardPubkey)) => {
            WORKER_PIPELINE_ERR_EMIT.fetch_add(1, Ordering::Relaxed);
            WORKER_PIPELINE_ERR_EMIT_INVALID_GUARD_PUBKEY.fetch_add(1, Ordering::Relaxed);
        }
        PipelineError::EmitFailed(EmitError::SignFailed(_)) => {
            WORKER_PIPELINE_ERR_EMIT.fetch_add(1, Ordering::Relaxed);
            WORKER_PIPELINE_ERR_EMIT_SIGN.fetch_add(1, Ordering::Relaxed);
        }
        PipelineError::EmitFailed(EmitError::EnqueueFailedRingFull) => {
            WORKER_PIPELINE_ERR_EMIT.fetch_add(1, Ordering::Relaxed);
            WORKER_PIPELINE_ERR_EMIT_ENQUEUE_FULL.fetch_add(1, Ordering::Relaxed);
        }
        PipelineError::EmitFailed(EmitError::DeadlineExceeded) => {
            WORKER_PIPELINE_ERR_EMIT.fetch_add(1, Ordering::Relaxed);
            WORKER_PIPELINE_ERR_EMIT_DEADLINE_EXCEEDED.fetch_add(1, Ordering::Relaxed);
        }
        PipelineError::EmitFailed(EmitError::NoSendSinkFull) => {
            WORKER_PIPELINE_ERR_EMIT.fetch_add(1, Ordering::Relaxed);
            WORKER_PIPELINE_ERR_EMIT_NO_SEND_SINK_FULL.fetch_add(1, Ordering::Relaxed);
        }
        PipelineError::EmitFailed(EmitError::BuildFailed(_)) => {
            WORKER_PIPELINE_ERR_EMIT.fetch_add(1, Ordering::Relaxed);
            WORKER_PIPELINE_ERR_EMIT_BUILD_OTHER.fetch_add(1, Ordering::Relaxed);
        }
    }
}

#[inline(always)]
fn record_pipeline_probe_diag(probe: &NoSendPipelineProbe) {
    if probe.lookup_ok {
        WORKER_LOOKUP_OK.fetch_add(1, Ordering::Relaxed);
    }
    if probe.policy_ok {
        WORKER_POLICY_OK.fetch_add(1, Ordering::Relaxed);
    }
    if probe.assembly_ready {
        WORKER_ASSEMBLY_READY.fetch_add(1, Ordering::Relaxed);
    }
    if probe.pm_reservation_created {
        WORKER_PM_RESERVATION_CREATED.fetch_add(1, Ordering::Relaxed);
    }
    if probe.public_rpc_scout_route && probe.emit_attempted {
        WORKER_PUBLIC_RPC_SCOUT_EMIT_ATTEMPT.fetch_add(1, Ordering::Relaxed);
    }
    if probe.public_rpc_scout_route && probe.emit_ok {
        WORKER_PUBLIC_RPC_SCOUT_EMIT_OK.fetch_add(1, Ordering::Relaxed);
    }
    if probe.tpu_quic_route && probe.emit_attempted {
        WORKER_TPU_QUIC_WOULD_ENQUEUE.fetch_add(1, Ordering::Relaxed);
        WORKER_TPU_QUIC_PM_RESERVE_SIMULATED.fetch_add(
            u64::from(probe.reserved_notional_lamports != 0),
            Ordering::Relaxed,
        );
    }
    if probe.tpu_quic_route && probe.emit_ok {
        WORKER_TPU_QUIC_RING_ENQUEUE_OK.fetch_add(1, Ordering::Relaxed);
    }
}

fn set_tpu_quic_last_signature(signature: [u8; 64]) {
    *WORKER_TPU_QUIC_LAST_SIGNATURE
        .get_or_init(|| Mutex::new([0u8; 64]))
        .lock()
        .expect("tpu quic last signature mutex poisoned") = signature;
}

fn pm_reserve_amount_lamports(intent: &WorkerIntent, probe: &NoSendPipelineProbe) -> u64 {
    if probe.prepared_trade_size_lamports != 0 {
        probe.prepared_trade_size_lamports
    } else {
        preview_trade_size_for_intent(intent).unwrap_or(intent.amount)
    }
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
struct PmReserveOutcome {
    attempted: bool,
    ok: bool,
    reject_reason: PmReserveRejectReason,
}

fn classify_pm_reserve_outcome(
    route_decision: RouteDecision,
    rollout_no_send_backend: bool,
    observe_only_shadow_no_send: bool,
    probe: &NoSendPipelineProbe,
    error: Option<&PipelineError>,
) -> PmReserveOutcome {
    let attempted = probe.policy_ok
        || matches!(
            error,
            Some(PipelineError::PolicyRejected(
                PolicyDropReason::InventoryBreach
            ))
        );
    if !attempted {
        return PmReserveOutcome::default();
    }
    if probe.pm_reservation_created {
        return PmReserveOutcome {
            attempted: true,
            ok: true,
            reject_reason: PmReserveRejectReason::None,
        };
    }

    let reject_reason = if rollout_no_send_backend {
        PmReserveRejectReason::NoSendMode
    } else if observe_only_shadow_no_send {
        PmReserveRejectReason::NoLiveMode
    } else if !matches!(
        route_decision,
        RouteDecision::JitoBundle | RouteDecision::PublicRpcScout | RouteDecision::HarmonicBundle
    ) {
        PmReserveRejectReason::RouteNotLive
    } else if matches!(
        error,
        Some(PipelineError::PolicyRejected(
            PolicyDropReason::InventoryBreach
        ))
    ) {
        PmReserveRejectReason::Cap
    } else if matches!(
        error,
        Some(PipelineError::EmitFailed(EmitError::SignFailed(_)))
    ) {
        PmReserveRejectReason::MissingSignature
    } else {
        PmReserveRejectReason::Other
    };
    PmReserveOutcome {
        attempted: true,
        ok: false,
        reject_reason,
    }
}

fn record_pm_reserve_diag(
    record: &IngressRecord,
    route: &HydratedRoute,
    intent: &WorkerIntent,
    inputs: &PipelineInputs<'_>,
    probe: &NoSendPipelineProbe,
    error: Option<&PipelineError>,
) {
    let outcome = classify_pm_reserve_outcome(
        route.outcome.decision,
        inputs.rollout_no_send_backend,
        inputs.intent.observe_only && inputs.rollout_shadow_sink.is_some(),
        probe,
        error,
    );
    if !outcome.attempted {
        return;
    }

    WORKER_PM_RESERVE_ATTEMPT.fetch_add(1, Ordering::Relaxed);
    if outcome.ok {
        WORKER_PM_RESERVE_OK.fetch_add(1, Ordering::Relaxed);
        return;
    }

    match outcome.reject_reason {
        PmReserveRejectReason::None => {}
        PmReserveRejectReason::NoLiveMode => {
            WORKER_PM_RESERVE_REJECT_NO_LIVE_MODE.fetch_add(1, Ordering::Relaxed);
        }
        PmReserveRejectReason::NoSendMode => {
            WORKER_PM_RESERVE_REJECT_NO_SEND_MODE.fetch_add(1, Ordering::Relaxed);
        }
        PmReserveRejectReason::RouteNotLive => {
            WORKER_PM_RESERVE_REJECT_ROUTE_NOT_LIVE.fetch_add(1, Ordering::Relaxed);
        }
        PmReserveRejectReason::Cap => {
            WORKER_PM_RESERVE_REJECT_CAP.fetch_add(1, Ordering::Relaxed);
        }
        PmReserveRejectReason::Inventory => {
            WORKER_PM_RESERVE_REJECT_INVENTORY.fetch_add(1, Ordering::Relaxed);
        }
        PmReserveRejectReason::MissingSignature => {
            WORKER_PM_RESERVE_REJECT_MISSING_SIGNATURE.fetch_add(1, Ordering::Relaxed);
        }
        PmReserveRejectReason::Other => {
            WORKER_PM_RESERVE_REJECT_OTHER.fetch_add(1, Ordering::Relaxed);
        }
    }
    set_last_pm_reserve_reject(
        record,
        route.outcome.decision,
        outcome.reject_reason,
        pm_reserve_amount_lamports(intent, probe),
    );
}

#[inline(always)]
fn pipeline_error_after_quote(error: &PipelineError) -> bool {
    match error {
        PipelineError::InvalidDirection | PipelineError::OverlayOverflow => true,
        PipelineError::PolicyRejected(reason) => !matches!(
            reason,
            PolicyDropReason::ApexPartialNotPositive
                | PolicyDropReason::AtbaMissingOrStaleDistToTick
                | PolicyDropReason::Over15SolLiveInput
                | PolicyDropReason::NetAfterFeeFloor
        ),
        PipelineError::EmitFailed(_) => true,
        _ => false,
    }
}

#[inline(always)]
fn record_terminal_pipeline_diag(error: Option<&PipelineError>, attempted_no_send_backend: bool) {
    match error {
        None => {
            WORKER_PROCESS_INTENT_OK.fetch_add(1, Ordering::Relaxed);
            WORKER_QUOTE_OK.fetch_add(1, Ordering::Relaxed);
            WORKER_TEMPLATE_BUILD_OK.fetch_add(1, Ordering::Relaxed);
            if attempted_no_send_backend {
                WORKER_NO_SEND_BACKEND_CALLED.fetch_add(1, Ordering::Relaxed);
                WORKER_NO_SEND_BACKEND_OK.fetch_add(1, Ordering::Relaxed);
            }
        }
        Some(error) => {
            WORKER_PROCESS_INTENT_ERR.fetch_add(1, Ordering::Relaxed);
            match error {
                PipelineError::ClmmExactQuoteUnavailable(_) | PipelineError::QuoteFailed => {
                    WORKER_QUOTE_ERR.fetch_add(1, Ordering::Relaxed);
                }
                PipelineError::RoutingDropped(reason) => {
                    WORKER_ROUTE_RESOLVED_DROP.fetch_add(1, Ordering::Relaxed);
                    if *reason == RouteReason::HarmonicEgressGateNoJito {
                        WORKER_PRESIGN_GATE_REJECT.fetch_add(1, Ordering::Relaxed);
                    }
                }
                PipelineError::EmitFailed(EmitError::BuildFailed(_)) => {
                    WORKER_QUOTE_OK.fetch_add(1, Ordering::Relaxed);
                    WORKER_TEMPLATE_BUILD_ERR.fetch_add(1, Ordering::Relaxed);
                    if attempted_no_send_backend {
                        WORKER_NO_SEND_BACKEND_CALLED.fetch_add(1, Ordering::Relaxed);
                        WORKER_NO_SEND_BACKEND_ERR.fetch_add(1, Ordering::Relaxed);
                    }
                }
                PipelineError::EmitFailed(_) => {
                    WORKER_QUOTE_OK.fetch_add(1, Ordering::Relaxed);
                    WORKER_TEMPLATE_BUILD_OK.fetch_add(1, Ordering::Relaxed);
                    if attempted_no_send_backend {
                        WORKER_NO_SEND_BACKEND_CALLED.fetch_add(1, Ordering::Relaxed);
                        WORKER_NO_SEND_BACKEND_ERR.fetch_add(1, Ordering::Relaxed);
                    }
                }
                _ if pipeline_error_after_quote(error) => {
                    WORKER_QUOTE_OK.fetch_add(1, Ordering::Relaxed);
                }
                _ => {}
            }
        }
    }
}

#[inline(always)]
fn clmm_guard_vaults_from_record(record: &IngressRecord) -> Option<([u8; 32], [u8; 32])> {
    if record.venue_id != ingest_venue::RAYDIUM_CLMM {
        return None;
    }

    let input_idx = record.pattern_acct_indices[0];
    let output_idx = record.pattern_acct_indices[1];
    if input_idx == ACCT_INDEX_ABSENT || output_idx == ACCT_INDEX_ABSENT {
        return None;
    }

    let flat_len = record.flat_accounts_len as usize;
    let input_idx = input_idx as usize;
    let output_idx = output_idx as usize;
    if input_idx >= flat_len || output_idx >= flat_len {
        return None;
    }

    let guard_vault_in = record.flat_accounts[input_idx];
    let guard_vault_out = record.flat_accounts[output_idx];
    if guard_vault_in == [0u8; 32] || guard_vault_out == [0u8; 32] {
        return None;
    }

    Some((guard_vault_in, guard_vault_out))
}

#[inline(always)]
fn guard_vaults_for_live_intent(
    shared: &SharedRefs<'_>,
    record: &IngressRecord,
) -> ([u8; 32], [u8; 32]) {
    match record.venue_id {
        ingest_venue::RAYDIUM_CLMM => {
            clmm_guard_vaults_from_record(record).unwrap_or(([0u8; 32], [0u8; 32]))
        }
        _ => (shared.guard_vault_in_pubkey, shared.guard_vault_out_pubkey),
    }
}

#[inline(always)]
fn flat_account_is_writable(record: &IngressRecord, account_idx: usize) -> bool {
    let static_len = record.static_accounts_len as usize;
    let required_signatures = record.num_required_signatures as usize;
    let readonly_signed = record.num_readonly_signed as usize;
    let readonly_unsigned = record.num_readonly_unsigned as usize;
    let alt_writable_count = record.alt_writable_count as usize;

    if account_idx < static_len {
        if account_idx < required_signatures {
            account_idx < required_signatures.saturating_sub(readonly_signed)
        } else {
            account_idx < static_len.saturating_sub(readonly_unsigned)
        }
    } else {
        account_idx < static_len.saturating_add(alt_writable_count)
    }
}

#[inline(always)]
fn build_clmm_swap_ix_data(template_variant: u8) -> Option<FixedSwapIxData> {
    let discriminator = match template_variant {
        TEMPLATE_VARIANT_CLMM_V1 => SWAP_V1_DISCRIMINATOR,
        TEMPLATE_VARIANT_CLMM_V2 => SWAP_V2_DISCRIMINATOR,
        _ => return None,
    };

    let mut data = [0u8; 64];
    data[..8].copy_from_slice(&discriminator);
    data[40] = 1;
    Some(FixedSwapIxData {
        data,
        len: 41,
        amount_in_offset: 8,
        min_out_offset: 16,
    })
}

#[inline(always)]
fn read_mint_payload(
    shared: &SharedRefs<'_>,
    mint_index: u32,
    expected_mint_pubkey: &[u8; 32],
) -> Option<MintStatePayload56B> {
    if mint_index == OBSERVE_ONLY_ZERO_MINT_INDEX {
        return None;
    }
    let elements = shared.mint_arena.elements();
    let payload = elements.get(mint_index as usize)?.read_active()?;
    if &payload.mint_pubkey != expected_mint_pubkey {
        return None;
    }
    Some(payload)
}

#[inline(always)]
fn record_clmm_ata_failure(
    counter: &AtomicU64,
    record: &IngressRecord,
    input_token_account_pubkey: [u8; 32],
    output_token_account_pubkey: [u8; 32],
) {
    counter.fetch_add(1, Ordering::Relaxed);
    set_last_clmm_ata_failure_fields(
        record.mint_in,
        record.mint_out,
        input_token_account_pubkey,
        output_token_account_pubkey,
    );
}

#[inline(always)]
fn resolve_signer_token_account_for_mint<'a>(
    signer_pubkey: &[u8; 32],
    signer_token_inventory: &'a SignerTokenInventory,
    mint_pubkey: &[u8; 32],
    owner_program: u8,
) -> Option<([u8; 32], [u8; 32], &'a SignerTokenAccountEntry)> {
    if let Some(derived_token_program) =
        shadow_core::pda::token_program_id_for_owner_program(owner_program)
    {
        let derived_token_account = shadow_core::pda::derive_ata_for_token_program(
            signer_pubkey,
            &derived_token_program,
            mint_pubkey,
        )?;
        if let Some(entry) = signer_token_inventory.find_by_token_account(&derived_token_account) {
            return Some((derived_token_program, derived_token_account, entry));
        }
    }
    let entry = signer_token_inventory.find_unique_by_mint(mint_pubkey)?;
    Some((entry.token_program_id, entry.token_account_pubkey, entry))
}

#[inline(always)]
fn preview_signer_token_account_for_mint(
    signer_pubkey: &[u8; 32],
    signer_token_inventory: &SignerTokenInventory,
    mint_pubkey: &[u8; 32],
    owner_program: u8,
) -> Option<[u8; 32]> {
    if let Some(derived_token_program) =
        shadow_core::pda::token_program_id_for_owner_program(owner_program)
    {
        if let Some(derived_token_account) = shadow_core::pda::derive_ata_for_token_program(
            signer_pubkey,
            &derived_token_program,
            mint_pubkey,
        ) {
            return Some(derived_token_account);
        }
    }
    signer_token_inventory
        .find_unique_by_mint(mint_pubkey)
        .map(|entry| entry.token_account_pubkey)
}

#[derive(Debug, Clone, Copy)]
struct ClmmPublicScoutInputAccountCheck {
    input_token_account_pubkey: [u8; 32],
    output_preview: [u8; 32],
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ClmmPublicScoutInputAccountFailureKind {
    MintStateMissing,
    MissingInputAta,
    UnsupportedTokenProgram,
    UninitializedInputAta,
    InsufficientBalance,
}

#[derive(Debug, Clone, Copy)]
struct ClmmPublicScoutInputAccountFailure {
    kind: ClmmPublicScoutInputAccountFailureKind,
    input_token_account_pubkey: [u8; 32],
    output_token_account_pubkey: [u8; 32],
    input_balance_raw: u64,
    required_input_raw: u64,
    token_program_pubkey: [u8; 32],
}

impl ClmmPublicScoutInputAccountFailure {
    fn blocks_r1_inventory_gate(self) -> bool {
        !matches!(
            self.kind,
            ClmmPublicScoutInputAccountFailureKind::MintStateMissing
        )
    }

    fn input_status(self) -> &'static str {
        match self.kind {
            ClmmPublicScoutInputAccountFailureKind::MintStateMissing => "mint_state_missing",
            ClmmPublicScoutInputAccountFailureKind::MissingInputAta => "ata_missing",
            ClmmPublicScoutInputAccountFailureKind::UnsupportedTokenProgram => {
                "token_program_mismatch"
            }
            ClmmPublicScoutInputAccountFailureKind::UninitializedInputAta => "uninitialized",
            ClmmPublicScoutInputAccountFailureKind::InsufficientBalance => "balance_insufficient",
        }
    }

    fn target_inventory_reject_reason(self) -> Run38TargetInventoryRejectReason {
        match self.kind {
            ClmmPublicScoutInputAccountFailureKind::MissingInputAta => {
                Run38TargetInventoryRejectReason::MissingInputAta
            }
            ClmmPublicScoutInputAccountFailureKind::UnsupportedTokenProgram => {
                Run38TargetInventoryRejectReason::TokenProgramMismatch
            }
            ClmmPublicScoutInputAccountFailureKind::UninitializedInputAta => {
                Run38TargetInventoryRejectReason::InputAtaUninitialized
            }
            ClmmPublicScoutInputAccountFailureKind::InsufficientBalance => {
                Run38TargetInventoryRejectReason::InputBalanceInsufficient
            }
            ClmmPublicScoutInputAccountFailureKind::MintStateMissing => {
                Run38TargetInventoryRejectReason::Other
            }
        }
    }

    fn template_drop_reason(self) -> TemplateDropReason {
        match self.kind {
            ClmmPublicScoutInputAccountFailureKind::MintStateMissing => TemplateDropReason::Other,
            ClmmPublicScoutInputAccountFailureKind::MissingInputAta
            | ClmmPublicScoutInputAccountFailureKind::UninitializedInputAta => {
                TemplateDropReason::MissingInputAta
            }
            ClmmPublicScoutInputAccountFailureKind::UnsupportedTokenProgram => {
                TemplateDropReason::UnsupportedTokenProgram
            }
            ClmmPublicScoutInputAccountFailureKind::InsufficientBalance => {
                TemplateDropReason::Other
            }
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ClmmPublicScoutOutputAccountFailureKind {
    MintStateMissing,
    MissingOutputAta,
    UnsupportedTokenProgram,
    UninitializedOutputAta,
}

#[derive(Debug, Clone, Copy)]
struct ClmmPublicScoutOutputAccountFailure {
    kind: ClmmPublicScoutOutputAccountFailureKind,
    input_token_account_pubkey: [u8; 32],
    output_token_account_pubkey: [u8; 32],
}

impl ClmmPublicScoutOutputAccountFailure {
    fn blocks_r1_output_gate(self) -> bool {
        !matches!(
            self.kind,
            ClmmPublicScoutOutputAccountFailureKind::MintStateMissing
        )
    }

    fn output_status(self) -> &'static str {
        match self.kind {
            ClmmPublicScoutOutputAccountFailureKind::MintStateMissing => "mint_state_missing",
            ClmmPublicScoutOutputAccountFailureKind::MissingOutputAta => "ata_missing",
            ClmmPublicScoutOutputAccountFailureKind::UnsupportedTokenProgram => {
                "token_program_mismatch"
            }
            ClmmPublicScoutOutputAccountFailureKind::UninitializedOutputAta => "uninitialized",
        }
    }

    fn template_drop_reason(self) -> TemplateDropReason {
        match self.kind {
            ClmmPublicScoutOutputAccountFailureKind::MintStateMissing => TemplateDropReason::Other,
            ClmmPublicScoutOutputAccountFailureKind::MissingOutputAta
            | ClmmPublicScoutOutputAccountFailureKind::UninitializedOutputAta => {
                TemplateDropReason::MissingOutputAta
            }
            ClmmPublicScoutOutputAccountFailureKind::UnsupportedTokenProgram => {
                TemplateDropReason::UnsupportedTokenProgram
            }
        }
    }

    fn template_executability_reject_reason(self) -> Option<R1TemplateExecutabilityRejectReason> {
        match self.kind {
            ClmmPublicScoutOutputAccountFailureKind::MintStateMissing => None,
            ClmmPublicScoutOutputAccountFailureKind::MissingOutputAta => {
                Some(R1TemplateExecutabilityRejectReason::MissingOutputAta)
            }
            ClmmPublicScoutOutputAccountFailureKind::UnsupportedTokenProgram => {
                Some(R1TemplateExecutabilityRejectReason::OutputTokenProgramMismatch)
            }
            ClmmPublicScoutOutputAccountFailureKind::UninitializedOutputAta => {
                Some(R1TemplateExecutabilityRejectReason::UninitializedOutputAta)
            }
        }
    }
}

#[inline(always)]
fn record_flat_account_pubkey(record: &IngressRecord, flat_index: u8) -> [u8; 32] {
    if flat_index == ACCT_INDEX_ABSENT {
        return [0u8; 32];
    }
    let flat_index = flat_index as usize;
    let flat_len = record.flat_accounts_len as usize;
    if flat_index >= flat_len {
        return [0u8; 32];
    }
    record.flat_accounts[flat_index]
}

#[inline(always)]
fn clmm_public_scout_output_token_account_preview(
    shared: &SharedRefs<'_>,
    resolved: &ResolvedRecord,
    record: &IngressRecord,
) -> [u8; 32] {
    let Some(mint_out) = read_mint_payload(shared, resolved.mint_out_index, &record.mint_out)
    else {
        return [0u8; 32];
    };
    preview_signer_token_account_for_mint(
        &shared.signer.pubkey,
        shared.signer_token_inventory,
        &record.mint_out,
        mint_out.owner_program,
    )
    .unwrap_or([0u8; 32])
}

#[inline(always)]
fn clmm_public_scout_input_token_account(
    shared: &SharedRefs<'_>,
    record: &IngressRecord,
    resolved: &ResolvedRecord,
    intent: &WorkerIntent,
    output_status: &str,
) -> Result<ClmmPublicScoutInputAccountCheck, ClmmPublicScoutInputAccountFailure> {
    let output_preview = clmm_public_scout_output_token_account_preview(shared, resolved, record);
    let Some(mint_in) = read_mint_payload(shared, resolved.mint_in_index, &record.mint_in) else {
        let failure = ClmmPublicScoutInputAccountFailure {
            kind: ClmmPublicScoutInputAccountFailureKind::MintStateMissing,
            input_token_account_pubkey: [0u8; 32],
            output_token_account_pubkey: output_preview,
            input_balance_raw: 0,
            required_input_raw: intent.amount,
            token_program_pubkey: [0u8; 32],
        };
        trace_public_rpc_scout_clmm_signer_accounts(
            record,
            intent,
            failure.input_status(),
            output_status,
            failure.input_token_account_pubkey,
            failure.output_token_account_pubkey,
        );
        return Err(failure);
    };
    let expected_input_token_program =
        shadow_core::pda::token_program_id_for_owner_program(mint_in.owner_program)
            .unwrap_or([0u8; 32]);
    let input_preview = preview_signer_token_account_for_mint(
        &shared.signer.pubkey,
        shared.signer_token_inventory,
        &record.mint_in,
        mint_in.owner_program,
    )
    .unwrap_or([0u8; 32]);
    let Some((input_token_program, input_token_account_pubkey, input_entry)) =
        resolve_signer_token_account_for_mint(
            &shared.signer.pubkey,
            shared.signer_token_inventory,
            &record.mint_in,
            mint_in.owner_program,
        )
    else {
        record_clmm_ata_failure(
            &WORKER_CLMM_INPUT_ATA_MISSING,
            record,
            input_preview,
            output_preview,
        );
        let failure = ClmmPublicScoutInputAccountFailure {
            kind: ClmmPublicScoutInputAccountFailureKind::MissingInputAta,
            input_token_account_pubkey: input_preview,
            output_token_account_pubkey: output_preview,
            input_balance_raw: 0,
            required_input_raw: intent.amount,
            token_program_pubkey: expected_input_token_program,
        };
        trace_public_rpc_scout_clmm_signer_accounts(
            record,
            intent,
            failure.input_status(),
            output_status,
            failure.input_token_account_pubkey,
            failure.output_token_account_pubkey,
        );
        return Err(failure);
    };
    if input_entry.mint_pubkey != record.mint_in
        || input_entry.token_program_id != input_token_program
    {
        record_clmm_ata_failure(
            &WORKER_CLMM_TOKEN_PROGRAM_MISMATCH,
            record,
            input_token_account_pubkey,
            output_preview,
        );
        let failure = ClmmPublicScoutInputAccountFailure {
            kind: ClmmPublicScoutInputAccountFailureKind::UnsupportedTokenProgram,
            input_token_account_pubkey,
            output_token_account_pubkey: output_preview,
            input_balance_raw: input_entry.amount_raw,
            required_input_raw: intent.amount,
            token_program_pubkey: input_entry.token_program_id,
        };
        trace_public_rpc_scout_clmm_signer_accounts(
            record,
            intent,
            failure.input_status(),
            output_status,
            failure.input_token_account_pubkey,
            failure.output_token_account_pubkey,
        );
        return Err(failure);
    }
    if !input_entry.initialized {
        record_clmm_ata_failure(
            &WORKER_CLMM_INPUT_ATA_UNINITIALIZED,
            record,
            input_token_account_pubkey,
            output_preview,
        );
        let failure = ClmmPublicScoutInputAccountFailure {
            kind: ClmmPublicScoutInputAccountFailureKind::UninitializedInputAta,
            input_token_account_pubkey,
            output_token_account_pubkey: output_preview,
            input_balance_raw: input_entry.amount_raw,
            required_input_raw: intent.amount,
            token_program_pubkey: input_token_program,
        };
        trace_public_rpc_scout_clmm_signer_accounts(
            record,
            intent,
            failure.input_status(),
            output_status,
            failure.input_token_account_pubkey,
            failure.output_token_account_pubkey,
        );
        return Err(failure);
    }
    if input_entry.amount_raw < intent.amount {
        record_clmm_ata_failure(
            &WORKER_CLMM_INPUT_BALANCE_INSUFFICIENT,
            record,
            input_token_account_pubkey,
            output_preview,
        );
        let failure = ClmmPublicScoutInputAccountFailure {
            kind: ClmmPublicScoutInputAccountFailureKind::InsufficientBalance,
            input_token_account_pubkey,
            output_token_account_pubkey: output_preview,
            input_balance_raw: input_entry.amount_raw,
            required_input_raw: intent.amount,
            token_program_pubkey: input_token_program,
        };
        trace_public_rpc_scout_clmm_signer_accounts(
            record,
            intent,
            failure.input_status(),
            output_status,
            failure.input_token_account_pubkey,
            failure.output_token_account_pubkey,
        );
        return Err(failure);
    }

    Ok(ClmmPublicScoutInputAccountCheck {
        input_token_account_pubkey,
        output_preview,
    })
}

#[inline(always)]
fn clmm_public_scout_output_token_account(
    shared: &SharedRefs<'_>,
    record: &IngressRecord,
    resolved: &ResolvedRecord,
    intent: &WorkerIntent,
    input_token_account_pubkey: [u8; 32],
    input_status: &'static str,
) -> Result<[u8; 32], ClmmPublicScoutOutputAccountFailure> {
    let Some(mint_out) = read_mint_payload(shared, resolved.mint_out_index, &record.mint_out)
    else {
        let failure = ClmmPublicScoutOutputAccountFailure {
            kind: ClmmPublicScoutOutputAccountFailureKind::MintStateMissing,
            input_token_account_pubkey,
            output_token_account_pubkey: [0u8; 32],
        };
        trace_public_rpc_scout_clmm_signer_accounts(
            record,
            intent,
            input_status,
            failure.output_status(),
            failure.input_token_account_pubkey,
            failure.output_token_account_pubkey,
        );
        return Err(failure);
    };
    let output_preview = clmm_public_scout_output_token_account_preview(shared, resolved, record);
    let Some((output_token_program, output_token_account_pubkey, output_entry)) =
        resolve_signer_token_account_for_mint(
            &shared.signer.pubkey,
            shared.signer_token_inventory,
            &record.mint_out,
            mint_out.owner_program,
        )
    else {
        record_clmm_ata_failure(
            &WORKER_CLMM_OUTPUT_ATA_MISSING,
            record,
            input_token_account_pubkey,
            output_preview,
        );
        let failure = ClmmPublicScoutOutputAccountFailure {
            kind: ClmmPublicScoutOutputAccountFailureKind::MissingOutputAta,
            input_token_account_pubkey,
            output_token_account_pubkey: output_preview,
        };
        trace_public_rpc_scout_clmm_signer_accounts(
            record,
            intent,
            input_status,
            failure.output_status(),
            failure.input_token_account_pubkey,
            failure.output_token_account_pubkey,
        );
        return Err(failure);
    };
    if output_entry.mint_pubkey != record.mint_out
        || output_entry.token_program_id != output_token_program
    {
        record_clmm_ata_failure(
            &WORKER_CLMM_TOKEN_PROGRAM_MISMATCH,
            record,
            input_token_account_pubkey,
            output_token_account_pubkey,
        );
        let failure = ClmmPublicScoutOutputAccountFailure {
            kind: ClmmPublicScoutOutputAccountFailureKind::UnsupportedTokenProgram,
            input_token_account_pubkey,
            output_token_account_pubkey,
        };
        trace_public_rpc_scout_clmm_signer_accounts(
            record,
            intent,
            input_status,
            failure.output_status(),
            failure.input_token_account_pubkey,
            failure.output_token_account_pubkey,
        );
        return Err(failure);
    }
    if !output_entry.initialized {
        record_clmm_ata_failure(
            &WORKER_CLMM_OUTPUT_ATA_UNINITIALIZED,
            record,
            input_token_account_pubkey,
            output_token_account_pubkey,
        );
        let failure = ClmmPublicScoutOutputAccountFailure {
            kind: ClmmPublicScoutOutputAccountFailureKind::UninitializedOutputAta,
            input_token_account_pubkey,
            output_token_account_pubkey,
        };
        trace_public_rpc_scout_clmm_signer_accounts(
            record,
            intent,
            input_status,
            failure.output_status(),
            failure.input_token_account_pubkey,
            failure.output_token_account_pubkey,
        );
        return Err(failure);
    }

    Ok(output_token_account_pubkey)
}

#[inline(always)]
fn clmm_public_scout_signer_token_accounts(
    shared: &SharedRefs<'_>,
    record: &IngressRecord,
    resolved: &ResolvedRecord,
    intent: &WorkerIntent,
) -> Result<([u8; 32], [u8; 32]), TemplateDropIdentity> {
    let input_check =
        clmm_public_scout_input_token_account(shared, record, resolved, intent, "preview_only")
            .map_err(|failure| TemplateDropIdentity {
                reason: failure.template_drop_reason(),
                pool_pubkey: record.pool_pubkey,
                mint_in_pubkey: record.mint_in,
                mint_out_pubkey: record.mint_out,
                route_decision: RouteDecision::PublicRpcScout,
                template_program_pubkey: RAYDIUM_CLMM_PROGRAM_ID,
                input_token_account_pubkey: failure.input_token_account_pubkey,
                output_token_account_pubkey: failure.output_token_account_pubkey,
            })?;
    let input_token_account_pubkey = input_check.input_token_account_pubkey;
    let output_token_account_pubkey = clmm_public_scout_output_token_account(
        shared,
        record,
        resolved,
        intent,
        input_token_account_pubkey,
        "ok",
    )
    .map_err(|failure| TemplateDropIdentity {
        reason: failure.template_drop_reason(),
        pool_pubkey: record.pool_pubkey,
        mint_in_pubkey: record.mint_in,
        mint_out_pubkey: record.mint_out,
        route_decision: RouteDecision::PublicRpcScout,
        template_program_pubkey: RAYDIUM_CLMM_PROGRAM_ID,
        input_token_account_pubkey: failure.input_token_account_pubkey,
        output_token_account_pubkey: failure.output_token_account_pubkey,
    })?;

    trace_public_rpc_scout_clmm_signer_accounts(
        record,
        intent,
        "ok",
        "ok",
        input_token_account_pubkey,
        output_token_account_pubkey,
    );
    Ok((input_token_account_pubkey, output_token_account_pubkey))
}

#[inline(always)]
fn build_clmm_swap_accounts_from_record(
    record: &IngressRecord,
    signer_token_accounts: Option<([u8; 32], [u8; 32])>,
) -> Result<FixedSwapAccounts, TemplateDropReason> {
    let account_count = record.ix_account_count as usize;
    let flat_len = record.flat_accounts_len as usize;
    if account_count == 0 || flat_len == 0 {
        return Err(TemplateDropReason::NoTemplate);
    }
    if account_count > MAX_SWAP_ACCOUNTS {
        return Err(TemplateDropReason::MissingClmmAccounts);
    }

    let input_token_account_index = record.pattern_acct_indices[2];
    let output_token_account_index = record.pattern_acct_indices[3];
    let mut metas = [EMPTY_SWAP_ACCOUNT_META; MAX_SWAP_ACCOUNTS];
    for i in 0..account_count {
        let flat_idx = record.ix_account_indices[i];
        if flat_idx == ACCT_INDEX_ABSENT {
            return Err(TemplateDropReason::MissingClmmAccounts);
        }
        let flat_idx = flat_idx as usize;
        if flat_idx >= flat_len {
            return Err(TemplateDropReason::MissingClmmAccounts);
        }
        let pubkey = record.flat_accounts[flat_idx];
        if pubkey == [0u8; 32] {
            return Err(TemplateDropReason::MissingClmmAccounts);
        }
        let source = if flat_idx == 0 {
            SwapAccountSource::FeePayerSigner
        } else if flat_idx as u8 == input_token_account_index {
            match signer_token_accounts {
                Some((input_token_account_pubkey, _)) => {
                    SwapAccountSource::ExplicitPubkey(input_token_account_pubkey)
                }
                None => SwapAccountSource::ExplicitPubkey(pubkey),
            }
        } else if flat_idx as u8 == output_token_account_index {
            match signer_token_accounts {
                Some((_, output_token_account_pubkey)) => {
                    SwapAccountSource::ExplicitPubkey(output_token_account_pubkey)
                }
                None => SwapAccountSource::ExplicitPubkey(pubkey),
            }
        } else {
            SwapAccountSource::ExplicitPubkey(pubkey)
        };
        metas[i] = FixedSwapAccountMeta {
            source,
            is_writable: flat_account_is_writable(record, flat_idx),
        };
    }

    Ok(FixedSwapAccounts {
        program_id: RAYDIUM_CLMM_PROGRAM_ID,
        metas,
        num_accounts: account_count as u8,
    })
}

#[inline(always)]
fn runtime_swap_template_for_record(
    shared: &SharedRefs<'_>,
    record: &IngressRecord,
    resolved: &ResolvedRecord,
    intent: &WorkerIntent,
    route_decision: RouteDecision,
) -> Result<(FixedSwapAccounts, FixedSwapIxData), TemplateDropIdentity> {
    if record.venue_id != ingest_venue::RAYDIUM_CLMM {
        return Ok((shared.swap_accounts.clone(), shared.swap_ix_data.clone()));
    }

    let signer_token_accounts = if route_decision == RouteDecision::PublicRpcScout {
        Some(clmm_public_scout_signer_token_accounts(
            shared, record, resolved, intent,
        )?)
    } else {
        None
    };
    let fallback_input_token_account_pubkey = signer_token_accounts
        .map(|accounts| accounts.0)
        .unwrap_or_else(|| record_flat_account_pubkey(record, record.pattern_acct_indices[2]));
    let fallback_output_token_account_pubkey = signer_token_accounts
        .map(|accounts| accounts.1)
        .unwrap_or_else(|| record_flat_account_pubkey(record, record.pattern_acct_indices[3]));
    let swap_accounts = build_clmm_swap_accounts_from_record(record, signer_token_accounts)
        .map_err(|reason| TemplateDropIdentity {
            reason,
            pool_pubkey: record.pool_pubkey,
            mint_in_pubkey: record.mint_in,
            mint_out_pubkey: record.mint_out,
            route_decision,
            template_program_pubkey: RAYDIUM_CLMM_PROGRAM_ID,
            input_token_account_pubkey: fallback_input_token_account_pubkey,
            output_token_account_pubkey: fallback_output_token_account_pubkey,
        })?;
    let swap_ix_data =
        build_clmm_swap_ix_data(record.template_variant).ok_or(TemplateDropIdentity {
            reason: TemplateDropReason::InvalidSwapProgram,
            pool_pubkey: record.pool_pubkey,
            mint_in_pubkey: record.mint_in,
            mint_out_pubkey: record.mint_out,
            route_decision,
            template_program_pubkey: RAYDIUM_CLMM_PROGRAM_ID,
            input_token_account_pubkey: fallback_input_token_account_pubkey,
            output_token_account_pubkey: fallback_output_token_account_pubkey,
        })?;
    Ok((swap_accounts, swap_ix_data))
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ClmmExactQuotePrimeOutcome {
    NotClmm,
    RequestArenaMissing,
    AmountPreviewFailed,
    PublishFailed,
    QuoteArenaMissing,
    OutstandingSamePool,
    QuoteMatched,
    QuoteWaitTimeout,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ClmmExactQuotePrimeMismatchReason {
    NoSnapshot,
    InvalidFlags,
    PoolMismatch,
    MintInMismatch,
    MintOutMismatch,
    AmountMismatch,
    DirectionMismatch,
    RequestIdMismatch,
    LastUpdateBeforeRequest,
    StaleForIntent,
    InvalidValidQuoteShape,
    WouldMatch,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ClmmExactQuoteInvalidFlagsDetail {
    Zero,
    NoValidBit,
    NoQuoteBit,
    UnknownStatus,
}

#[derive(Debug, Clone, Copy)]
struct ClmmExactQuotePrimeTimeoutDiag {
    reason: ClmmExactQuotePrimeMismatchReason,
    pool_index: u32,
    snapshot_sequence: u32,
    snapshot_slot0_sequence: u32,
    snapshot_slot1_sequence: u32,
    expected_pool_pubkey: [u8; 32],
    expected_mint_in_pubkey: [u8; 32],
    expected_mint_out_pubkey: [u8; 32],
    expected_amount_in: u64,
    expected_request_id: u32,
    snapshot_pool_pubkey: [u8; 32],
    snapshot_mint_in_pubkey: [u8; 32],
    snapshot_mint_out_pubkey: [u8; 32],
    snapshot_amount_in: u64,
    snapshot_direction: u8,
    snapshot_request_id: u32,
    snapshot_quote_epoch: u64,
    snapshot_last_update_unix_ns: u64,
    snapshot_validity_flags: u8,
    snapshot_status: u8,
}

impl ClmmExactQuotePrimeTimeoutDiag {
    fn no_snapshot() -> Self {
        Self {
            reason: ClmmExactQuotePrimeMismatchReason::NoSnapshot,
            pool_index: 0,
            snapshot_sequence: 0,
            snapshot_slot0_sequence: 0,
            snapshot_slot1_sequence: 0,
            expected_pool_pubkey: [0; 32],
            expected_mint_in_pubkey: [0; 32],
            expected_mint_out_pubkey: [0; 32],
            expected_amount_in: 0,
            expected_request_id: 0,
            snapshot_pool_pubkey: [0; 32],
            snapshot_mint_in_pubkey: [0; 32],
            snapshot_mint_out_pubkey: [0; 32],
            snapshot_amount_in: 0,
            snapshot_direction: 0,
            snapshot_request_id: 0,
            snapshot_quote_epoch: 0,
            snapshot_last_update_unix_ns: 0,
            snapshot_validity_flags: 0,
            snapshot_status: 0,
        }
    }
}

#[derive(Debug, Clone, Copy)]
struct ClmmExactQuotePrimeResult {
    outcome: ClmmExactQuotePrimeOutcome,
    request_amount_in: u64,
    request_id: u32,
    publish_ok_unix_ns: u64,
    timeout_diag: Option<ClmmExactQuotePrimeTimeoutDiag>,
}

fn encode_clmm_exact_quote_prime_outcome(outcome: ClmmExactQuotePrimeOutcome) -> &'static str {
    match outcome {
        ClmmExactQuotePrimeOutcome::NotClmm => "not_clmm",
        ClmmExactQuotePrimeOutcome::RequestArenaMissing => "request_arena_missing",
        ClmmExactQuotePrimeOutcome::AmountPreviewFailed => "amount_preview_failed",
        ClmmExactQuotePrimeOutcome::PublishFailed => "publish_failed",
        ClmmExactQuotePrimeOutcome::QuoteArenaMissing => "quote_arena_missing",
        ClmmExactQuotePrimeOutcome::OutstandingSamePool => "outstanding_same_pool",
        ClmmExactQuotePrimeOutcome::QuoteMatched => "quote_matched",
        ClmmExactQuotePrimeOutcome::QuoteWaitTimeout => "quote_wait_timeout",
    }
}

fn encode_clmm_exact_quote_prime_mismatch_reason(
    reason: ClmmExactQuotePrimeMismatchReason,
) -> &'static str {
    match reason {
        ClmmExactQuotePrimeMismatchReason::NoSnapshot => "no_snapshot",
        ClmmExactQuotePrimeMismatchReason::InvalidFlags => "invalid_flags",
        ClmmExactQuotePrimeMismatchReason::PoolMismatch => "pool_mismatch",
        ClmmExactQuotePrimeMismatchReason::MintInMismatch => "mint_in_mismatch",
        ClmmExactQuotePrimeMismatchReason::MintOutMismatch => "mint_out_mismatch",
        ClmmExactQuotePrimeMismatchReason::AmountMismatch => "amount_mismatch",
        ClmmExactQuotePrimeMismatchReason::DirectionMismatch => "direction_mismatch",
        ClmmExactQuotePrimeMismatchReason::RequestIdMismatch => "request_id_mismatch",
        ClmmExactQuotePrimeMismatchReason::LastUpdateBeforeRequest => "last_update_before_request",
        ClmmExactQuotePrimeMismatchReason::StaleForIntent => "stale_for_intent",
        ClmmExactQuotePrimeMismatchReason::InvalidValidQuoteShape => "invalid_valid_quote_shape",
        ClmmExactQuotePrimeMismatchReason::WouldMatch => "would_match",
    }
}

fn unix_timestamp_now_ns_u64() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .ok()
        .and_then(|duration| u64::try_from(duration.as_nanos()).ok())
        .unwrap_or_default()
}

fn explain_clmm_exact_quote_snapshot_mismatch(
    snapshot: ClmmExactQuotePayload192B,
    request: &ClmmExactQuoteRequestPayload128B,
    intent: &WorkerIntent,
) -> ClmmExactQuotePrimeMismatchReason {
    let is_valid = snapshot.validity_flags & CLMM_EXACT_QUOTE_FLAG_VALID != 0;
    let is_no_quote = snapshot.validity_flags & CLMM_EXACT_QUOTE_FLAG_NO_QUOTE != 0;
    if !is_valid && !is_no_quote {
        return ClmmExactQuotePrimeMismatchReason::InvalidFlags;
    }
    if snapshot.pool_pubkey != request.pool_pubkey {
        return ClmmExactQuotePrimeMismatchReason::PoolMismatch;
    }
    if snapshot.mint_in_pubkey != request.mint_in_pubkey {
        return ClmmExactQuotePrimeMismatchReason::MintInMismatch;
    }
    if snapshot.mint_out_pubkey != request.mint_out_pubkey {
        return ClmmExactQuotePrimeMismatchReason::MintOutMismatch;
    }
    if snapshot.amount_in != request.amount_in {
        return ClmmExactQuotePrimeMismatchReason::AmountMismatch;
    }
    if snapshot.direction != request.direction {
        return ClmmExactQuotePrimeMismatchReason::DirectionMismatch;
    }
    if snapshot.request_id() != request.request_id() {
        return ClmmExactQuotePrimeMismatchReason::RequestIdMismatch;
    }
    if snapshot.last_update_unix_ns < request.request_unix_ns {
        return ClmmExactQuotePrimeMismatchReason::LastUpdateBeforeRequest;
    }
    if intent
        .ingress_unix_ns
        .saturating_sub(snapshot.last_update_unix_ns)
        > intent.max_pool_staleness_ns
    {
        return ClmmExactQuotePrimeMismatchReason::StaleForIntent;
    }
    if is_valid
        && (snapshot.expected_out == 0
            || snapshot.min_out == 0
            || snapshot.min_out > snapshot.expected_out)
    {
        return ClmmExactQuotePrimeMismatchReason::InvalidValidQuoteShape;
    }
    ClmmExactQuotePrimeMismatchReason::WouldMatch
}

fn clmm_exact_quote_status_is_known_no_quote(status: u8) -> bool {
    matches!(
        status,
        CLMM_EXACT_QUOTE_STATUS_NO_CURRENT_ARRAY_UPSTREAM
            | CLMM_EXACT_QUOTE_STATUS_NO_LIQUIDITY_BOUNDARY
            | CLMM_EXACT_QUOTE_STATUS_OUT_OF_RANGE
            | CLMM_EXACT_QUOTE_STATUS_MISSING_TICK_ARRAY_LOCAL
            | CLMM_EXACT_QUOTE_STATUS_POOL_MISSING
            | CLMM_EXACT_QUOTE_STATUS_POOL_INDEX_MISMATCH
            | CLMM_EXACT_QUOTE_STATUS_MISSING_POOL_QUOTE_CORE
            | CLMM_EXACT_QUOTE_STATUS_MISSING_AMM_CONFIG
            | CLMM_EXACT_QUOTE_STATUS_NO_MINT_IN
            | CLMM_EXACT_QUOTE_STATUS_INVALID_MINT_PAIR
            | CLMM_EXACT_QUOTE_STATUS_MISSING_RESERVES
            | CLMM_EXACT_QUOTE_STATUS_QUOTE_BUILD_FAILED
    )
}

fn clmm_exact_quote_status_is_dependency_missing(status: u8) -> bool {
    matches!(
        status,
        CLMM_EXACT_QUOTE_STATUS_MISSING_TICK_ARRAY_LOCAL
            | CLMM_EXACT_QUOTE_STATUS_MISSING_POOL_QUOTE_CORE
            | CLMM_EXACT_QUOTE_STATUS_MISSING_AMM_CONFIG
            | CLMM_EXACT_QUOTE_STATUS_NO_MINT_IN
            | CLMM_EXACT_QUOTE_STATUS_INVALID_MINT_PAIR
            | CLMM_EXACT_QUOTE_STATUS_MISSING_RESERVES
    )
}

fn clmm_exact_quote_timeout_has_terminal_no_quote(diag: &ClmmExactQuotePrimeTimeoutDiag) -> bool {
    (diag.snapshot_validity_flags & CLMM_EXACT_QUOTE_FLAG_NO_QUOTE) != 0
        && clmm_exact_quote_status_is_known_no_quote(diag.snapshot_status)
}

fn clmm_exact_quote_timeout_has_valid_quote(diag: &ClmmExactQuotePrimeTimeoutDiag) -> bool {
    (diag.snapshot_validity_flags & CLMM_EXACT_QUOTE_FLAG_VALID) != 0
}

fn classify_clmm_exact_quote_invalid_flags_detail(
    diag: &ClmmExactQuotePrimeTimeoutDiag,
) -> Option<ClmmExactQuoteInvalidFlagsDetail> {
    if diag.reason != ClmmExactQuotePrimeMismatchReason::InvalidFlags {
        return None;
    }
    if diag.snapshot_validity_flags == 0 {
        return Some(ClmmExactQuoteInvalidFlagsDetail::Zero);
    }
    if diag.snapshot_status != CLMM_EXACT_QUOTE_STATUS_UNSPECIFIED
        && !clmm_exact_quote_status_is_known_no_quote(diag.snapshot_status)
    {
        return Some(ClmmExactQuoteInvalidFlagsDetail::UnknownStatus);
    }
    if diag.snapshot_status != CLMM_EXACT_QUOTE_STATUS_UNSPECIFIED
        && (diag.snapshot_validity_flags & CLMM_EXACT_QUOTE_FLAG_NO_QUOTE) == 0
    {
        return Some(ClmmExactQuoteInvalidFlagsDetail::NoQuoteBit);
    }
    Some(ClmmExactQuoteInvalidFlagsDetail::NoValidBit)
}

fn build_clmm_exact_quote_timeout_diag(
    snapshots: [Option<(u32, ClmmExactQuotePayload192B)>; 2],
    request: &ClmmExactQuoteRequestPayload128B,
    intent: &WorkerIntent,
) -> ClmmExactQuotePrimeTimeoutDiag {
    let slot_sequences = snapshots.map(|entry| entry.map_or(0, |(seq, _)| seq));
    let snapshot = snapshots.into_iter().flatten().max_by_key(|(seq, _)| *seq);
    let Some((snapshot_sequence, snapshot)) = snapshot else {
        let mut diag = ClmmExactQuotePrimeTimeoutDiag::no_snapshot();
        diag.pool_index = intent.pool_index;
        diag.expected_pool_pubkey = request.pool_pubkey;
        diag.expected_mint_in_pubkey = request.mint_in_pubkey;
        diag.expected_mint_out_pubkey = request.mint_out_pubkey;
        diag.expected_amount_in = request.amount_in;
        diag.expected_request_id = request.request_id();
        return diag;
    };
    ClmmExactQuotePrimeTimeoutDiag {
        reason: explain_clmm_exact_quote_snapshot_mismatch(snapshot, request, intent),
        pool_index: intent.pool_index,
        snapshot_sequence,
        snapshot_slot0_sequence: slot_sequences[0],
        snapshot_slot1_sequence: slot_sequences[1],
        expected_pool_pubkey: request.pool_pubkey,
        expected_mint_in_pubkey: request.mint_in_pubkey,
        expected_mint_out_pubkey: request.mint_out_pubkey,
        expected_amount_in: request.amount_in,
        expected_request_id: request.request_id(),
        snapshot_pool_pubkey: snapshot.pool_pubkey,
        snapshot_mint_in_pubkey: snapshot.mint_in_pubkey,
        snapshot_mint_out_pubkey: snapshot.mint_out_pubkey,
        snapshot_amount_in: snapshot.amount_in,
        snapshot_direction: snapshot.direction,
        snapshot_request_id: snapshot.request_id(),
        snapshot_quote_epoch: snapshot.quote_epoch,
        snapshot_last_update_unix_ns: snapshot.last_update_unix_ns,
        snapshot_validity_flags: snapshot.validity_flags,
        snapshot_status: snapshot.status,
    }
}

fn clmm_exact_quote_outstanding_slots(capacity: u32) -> &'static [AtomicU32] {
    CLMM_EXACT_QUOTE_OUTSTANDING_REQUESTS.get_or_init(|| {
        (0..capacity)
            .map(|_| AtomicU32::new(0))
            .collect::<Vec<_>>()
            .into_boxed_slice()
    })
}

fn clmm_exact_quote_outstanding_slot(capacity: u32, pool_index: u32) -> Option<&'static AtomicU32> {
    clmm_exact_quote_outstanding_slots(capacity).get(pool_index as usize)
}

fn try_claim_clmm_exact_quote_outstanding_request(
    capacity: u32,
    pool_index: u32,
    request_id: u32,
) -> Result<(), u32> {
    let Some(slot) = clmm_exact_quote_outstanding_slot(capacity, pool_index) else {
        return Err(0);
    };
    let existing = slot.load(Ordering::Acquire);
    if existing != 0 {
        return Err(existing);
    }
    slot.compare_exchange(0, request_id, Ordering::AcqRel, Ordering::Acquire)
        .map(|_| ())
}

fn clear_clmm_exact_quote_outstanding_request(capacity: u32, pool_index: u32, request_id: u32) {
    let Some(slot) = clmm_exact_quote_outstanding_slot(capacity, pool_index) else {
        return;
    };
    let _ = slot.compare_exchange(request_id, 0, Ordering::AcqRel, Ordering::Acquire);
}

