#[inline(always)]
fn record_clmm_exact_quote_response_timeout(diag: ClmmExactQuotePrimeTimeoutDiag) {
    WORKER_CLMM_EXACT_QUOTE_RESPONSE_TIMEOUT.fetch_add(1, Ordering::Relaxed);
    set_last_clmm_exact_quote_response_timeout(diag);
    if clmm_exact_quote_timeout_has_terminal_no_quote(&diag) {
        WORKER_CLMM_EXACT_QUOTE_RESPONSE_TIMEOUT_TERMINAL_NO_QUOTE.fetch_add(1, Ordering::Relaxed);
        if diag.snapshot_status == CLMM_EXACT_QUOTE_STATUS_QUOTE_BUILD_FAILED {
            WORKER_CLMM_EXACT_QUOTE_RESPONSE_TIMEOUT_QUOTE_BUILD_FAILED
                .fetch_add(1, Ordering::Relaxed);
        }
        if clmm_exact_quote_status_is_dependency_missing(diag.snapshot_status) {
            WORKER_CLMM_EXACT_QUOTE_RESPONSE_TIMEOUT_DEPENDENCY_MISSING
                .fetch_add(1, Ordering::Relaxed);
        }
    }
    if clmm_exact_quote_timeout_has_valid_quote(&diag) {
        WORKER_CLMM_EXACT_QUOTE_RESPONSE_TIMEOUT_QUOTE_READY_REJECTED
            .fetch_add(1, Ordering::Relaxed);
    }
    if diag.reason == ClmmExactQuotePrimeMismatchReason::RequestIdMismatch {
        WORKER_CLMM_EXACT_QUOTE_RESPONSE_TIMEOUT_STALE_REQUEST_ID.fetch_add(1, Ordering::Relaxed);
    }
    match diag.reason {
        ClmmExactQuotePrimeMismatchReason::NoSnapshot => {
            WORKER_CLMM_EXACT_QUOTE_RESPONSE_NO_SNAPSHOT.fetch_add(1, Ordering::Relaxed);
        }
        ClmmExactQuotePrimeMismatchReason::InvalidFlags => {
            WORKER_CLMM_EXACT_QUOTE_RESPONSE_INVALID_FLAGS.fetch_add(1, Ordering::Relaxed);
            match classify_clmm_exact_quote_invalid_flags_detail(&diag) {
                Some(ClmmExactQuoteInvalidFlagsDetail::Zero) => {
                    WORKER_CLMM_EXACT_QUOTE_RESPONSE_INVALID_FLAGS_ZERO
                        .fetch_add(1, Ordering::Relaxed);
                }
                Some(ClmmExactQuoteInvalidFlagsDetail::NoValidBit) => {
                    WORKER_CLMM_EXACT_QUOTE_RESPONSE_INVALID_FLAGS_NO_VALID_BIT
                        .fetch_add(1, Ordering::Relaxed);
                }
                Some(ClmmExactQuoteInvalidFlagsDetail::NoQuoteBit) => {
                    WORKER_CLMM_EXACT_QUOTE_RESPONSE_INVALID_FLAGS_NO_QUOTE_BIT
                        .fetch_add(1, Ordering::Relaxed);
                }
                Some(ClmmExactQuoteInvalidFlagsDetail::UnknownStatus) => {
                    WORKER_CLMM_EXACT_QUOTE_RESPONSE_INVALID_FLAGS_UNKNOWN_STATUS
                        .fetch_add(1, Ordering::Relaxed);
                }
                None => {}
            }
        }
        ClmmExactQuotePrimeMismatchReason::InvalidValidQuoteShape => {
            WORKER_CLMM_EXACT_QUOTE_RESPONSE_INVALID_FLAGS.fetch_add(1, Ordering::Relaxed);
            WORKER_CLMM_EXACT_QUOTE_RESPONSE_INVALID_VALID_QUOTE_SHAPE
                .fetch_add(1, Ordering::Relaxed);
        }
        ClmmExactQuotePrimeMismatchReason::PoolMismatch => {
            WORKER_CLMM_EXACT_QUOTE_RESPONSE_POOL_MISMATCH.fetch_add(1, Ordering::Relaxed);
        }
        ClmmExactQuotePrimeMismatchReason::MintInMismatch
        | ClmmExactQuotePrimeMismatchReason::MintOutMismatch => {
            WORKER_CLMM_EXACT_QUOTE_RESPONSE_MINT_MISMATCH.fetch_add(1, Ordering::Relaxed);
        }
        ClmmExactQuotePrimeMismatchReason::AmountMismatch => {
            WORKER_CLMM_EXACT_QUOTE_RESPONSE_AMOUNT_MISMATCH.fetch_add(1, Ordering::Relaxed);
        }
        ClmmExactQuotePrimeMismatchReason::RequestIdMismatch => {
            WORKER_CLMM_EXACT_QUOTE_RESPONSE_REQUEST_ID_MISMATCH.fetch_add(1, Ordering::Relaxed);
        }
        ClmmExactQuotePrimeMismatchReason::LastUpdateBeforeRequest
        | ClmmExactQuotePrimeMismatchReason::StaleForIntent => {
            WORKER_CLMM_EXACT_QUOTE_RESPONSE_STALE.fetch_add(1, Ordering::Relaxed);
        }
        ClmmExactQuotePrimeMismatchReason::DirectionMismatch
        | ClmmExactQuotePrimeMismatchReason::WouldMatch => {}
    }
    if (diag.snapshot_validity_flags & CLMM_EXACT_QUOTE_FLAG_NO_QUOTE) != 0 {
        match diag.snapshot_status {
            CLMM_EXACT_QUOTE_STATUS_NO_CURRENT_ARRAY_UPSTREAM => {
                WORKER_CLMM_EXACT_QUOTE_RESPONSE_NO_QUOTE_NO_CURRENT_ARRAY_UPSTREAM
                    .fetch_add(1, Ordering::Relaxed);
            }
            CLMM_EXACT_QUOTE_STATUS_NO_LIQUIDITY_BOUNDARY => {
                WORKER_CLMM_EXACT_QUOTE_RESPONSE_NO_QUOTE_NO_LIQUIDITY_BOUNDARY
                    .fetch_add(1, Ordering::Relaxed);
            }
            CLMM_EXACT_QUOTE_STATUS_OUT_OF_RANGE => {
                WORKER_CLMM_EXACT_QUOTE_RESPONSE_NO_QUOTE_OUT_OF_RANGE
                    .fetch_add(1, Ordering::Relaxed);
            }
            CLMM_EXACT_QUOTE_STATUS_MISSING_TICK_ARRAY_LOCAL => {
                WORKER_CLMM_EXACT_QUOTE_RESPONSE_NO_QUOTE_MISSING_TICK_ARRAY_LOCAL
                    .fetch_add(1, Ordering::Relaxed);
            }
            _ => {}
        }
    }
}

