fn trace_public_rpc_scout_clmm_quote_request(
    record: &IngressRecord,
    intent: &WorkerIntent,
    result: ClmmExactQuotePrimeResult,
) {
    if !trace_public_rpc_scout_emit_enabled() || record.venue_id != ingest_venue::RAYDIUM_CLMM {
        return;
    }

    println!(
        "TRACE public_rpc_scout_clmm_census stage=quote_request status={} pool={} mint_in={} mint_out={} amount_in={} direction={} pool_index={} signature={} request_id={}",
        encode_clmm_exact_quote_prime_outcome(result.outcome),
        bs58::encode(intent.expected_pool_pubkey).into_string(),
        bs58::encode(intent.expected_mint_in_pubkey).into_string(),
        bs58::encode(intent.expected_mint_out_pubkey).into_string(),
        result.request_amount_in,
        intent.direction,
        intent.pool_index,
        bs58::encode(record.signature).into_string(),
        result.request_id,
    );

    let diag = result
        .timeout_diag
        .unwrap_or_else(ClmmExactQuotePrimeTimeoutDiag::no_snapshot);
    println!(
        "TRACE clmm_exact_quote_lifecycle side=tier0 outcome={} pool={} mint_in={} mint_out={} amount_in={} direction={} request_unix_ns={} publish_ok_unix_ns={} request_id={} poll_slot_index={} timeout_mismatch_reason={} timeout_last_sequence={} timeout_last_payload_flags={} timeout_last_status={} timeout_last_request_id={} signature={}",
        encode_clmm_exact_quote_prime_outcome(result.outcome),
        bs58::encode(intent.expected_pool_pubkey).into_string(),
        bs58::encode(intent.expected_mint_in_pubkey).into_string(),
        bs58::encode(intent.expected_mint_out_pubkey).into_string(),
        result.request_amount_in,
        intent.direction,
        intent.ingress_unix_ns,
        result.publish_ok_unix_ns,
        result.request_id,
        intent.pool_index,
        encode_clmm_exact_quote_prime_mismatch_reason(diag.reason),
        diag.snapshot_sequence,
        diag.snapshot_validity_flags,
        clmm_exact_quote_status_str(diag.snapshot_status),
        diag.snapshot_request_id,
        bs58::encode(record.signature).into_string(),
    );

    if result.outcome == ClmmExactQuotePrimeOutcome::QuoteWaitTimeout {
        println!(
            "TRACE public_rpc_scout_clmm_quote_timeout_diag pool_expected={} mint_in_expected={} mint_out_expected={} amount_expected={} direction_expected={} pool_index={} request_unix_ns={} max_pool_staleness_ns={} request_id_expected={} mismatch_reason={} snapshot_sequence={} snapshot_slot0_sequence={} snapshot_slot1_sequence={} pool_found={} mint_in_found={} mint_out_found={} amount_found={} direction_found={} request_id_found={} quote_epoch_found={} last_update_unix_ns_found={} validity_flags_found={} status_found={} signature={}",
            bs58::encode(diag.expected_pool_pubkey).into_string(),
            bs58::encode(diag.expected_mint_in_pubkey).into_string(),
            bs58::encode(diag.expected_mint_out_pubkey).into_string(),
            diag.expected_amount_in,
            intent.direction,
            diag.pool_index,
            intent.ingress_unix_ns,
            intent.max_pool_staleness_ns,
            diag.expected_request_id,
            encode_clmm_exact_quote_prime_mismatch_reason(diag.reason),
            diag.snapshot_sequence,
            diag.snapshot_slot0_sequence,
            diag.snapshot_slot1_sequence,
            bs58::encode(diag.snapshot_pool_pubkey).into_string(),
            bs58::encode(diag.snapshot_mint_in_pubkey).into_string(),
            bs58::encode(diag.snapshot_mint_out_pubkey).into_string(),
            diag.snapshot_amount_in,
            diag.snapshot_direction,
            diag.snapshot_request_id,
            diag.snapshot_quote_epoch,
            diag.snapshot_last_update_unix_ns,
            diag.snapshot_validity_flags,
            clmm_exact_quote_status_str(diag.snapshot_status),
            bs58::encode(record.signature).into_string(),
        );
    }
}

