fn process_intent_with_diagnostics(
    shared: &SharedRefs<'_>,
    record: &IngressRecord,
    resolved: &ResolvedRecord,
    route: &HydratedRoute,
    intent: &WorkerIntent,
    inputs: &mut PipelineInputs<'_>,
) -> Result<shadow_core::assembly::EmitReceipt, PipelineError> {
    WORKER_PIPELINE_ATTEMPTS.fetch_add(1, Ordering::Relaxed);
    WORKER_CANDIDATES_ENTERED_PROCESS_INTENT.fetch_add(1, Ordering::Relaxed);
    record_run38_target_process_intent(record, route.outcome.decision);
    record_dpdk_worker_counter(
        record.signal_source,
        &DPDK_WORKER_CANDIDATES_ENTERED_PROCESS_INTENT,
    );
    crate::tail_latency::record_process_intent_enter(record);
    let (guard_vault_in_pubkey, guard_vault_out_pubkey) =
        guard_vaults_for_live_intent(shared, record);
    inputs.guard_vault_in_pubkey = guard_vault_in_pubkey;
    inputs.guard_vault_out_pubkey = guard_vault_out_pubkey;
    trace_public_rpc_scout_guard_context(
        route,
        record,
        guard_vault_in_pubkey,
        guard_vault_out_pubkey,
        "primary",
    );
    if record.signal_source == SIGNAL_SOURCE_AFXDP {
        WORKER_R1_AFXDP_PRIVATE_GRADE_PROCESS_INTENT_ENTERED.fetch_add(1, Ordering::Relaxed);
    }
    let attempted_no_send_backend = inputs.rollout_no_send_backend
        || (inputs.intent.observe_only && inputs.rollout_shadow_sink.is_some());

    let scorecard_replay_quote_neutralization =
        scorecard_replay_target_no_send_quote_neutralization_enabled(
            record,
            route.outcome.decision,
            inputs.rollout_no_send_backend,
        );
    let result = if scorecard_replay_quote_neutralization {
        process_intent_with_probe_scorecard_replay_dev(inputs)
    } else {
        process_intent_with_probe(inputs)
    };
    match &result {
        Ok((receipt, probe)) => {
            WORKER_PIPELINE_SUCCESS.fetch_add(1, Ordering::Relaxed);
            record_pipeline_probe_diag(probe);
            if probe.quote_target_neutralized_for_replay {
                trace_run40_scorecard_replay_gate(
                    record,
                    "quote_target_neutralization_applied",
                    &format!(
                        "route_decision={} quote_expected_out={} quote_min_out={} projected_reserve_in={} projected_reserve_out={}",
                        encode_route_decision(route.outcome.decision),
                        probe.quote_expected_out_lamports,
                        probe.prepared_min_out_lamports,
                        probe.quote_projected_reserve_in,
                        probe.quote_projected_reserve_out
                    ),
                );
            }
            if route.outcome.decision == RouteDecision::TpuQuicPublic {
                set_tpu_quic_last_signature(receipt.signature);
            }
            trace_run40_scorecard_replay_gate(
                record,
                "process_intent_ok",
                &format!(
                    "lookup_ok={} policy_ok={} assembly_ready={} pm_reservation_created={} force_live_inventory_reservation={} emit_attempted={} emit_ok={}",
                    probe.lookup_ok,
                    probe.policy_ok,
                    probe.assembly_ready,
                    probe.pm_reservation_created,
                    inputs.force_live_inventory_reservation,
                    probe.emit_attempted,
                    probe.emit_ok
                ),
            );
            record_pm_reserve_diag(record, route, intent, inputs, probe, None);
            record_run38_target_pipeline_probe(record, route.outcome.decision, probe);
            trace_public_rpc_scout_clmm_quote_audit(route, record, intent, probe);
            trace_public_rpc_scout_process_result(route, record, Ok(()));
            record_terminal_pipeline_diag(None, attempted_no_send_backend);
        }
        Err((error, probe)) => {
            record_dpdk_worker_counter(record.signal_source, &DPDK_WORKER_PIPELINE_ERROR);
            record_pipeline_probe_diag(probe);
            if probe.quote_target_neutralized_for_replay {
                trace_run40_scorecard_replay_gate(
                    record,
                    "quote_target_neutralization_applied",
                    &format!(
                        "route_decision={} quote_expected_out={} quote_min_out={} projected_reserve_in={} projected_reserve_out={}",
                        encode_route_decision(route.outcome.decision),
                        probe.quote_expected_out_lamports,
                        probe.prepared_min_out_lamports,
                        probe.quote_projected_reserve_in,
                        probe.quote_projected_reserve_out
                    ),
                );
            }
            if route.outcome.decision == RouteDecision::TpuQuicPublic
                && matches!(
                    error,
                    PipelineError::EmitFailed(EmitError::EnqueueFailedRingFull)
                )
            {
                WORKER_TPU_QUIC_RING_ENQUEUE_ERR.fetch_add(1, Ordering::Relaxed);
            }
            record_pm_reserve_diag(record, route, intent, inputs, probe, Some(error));
            record_run38_target_pipeline_probe(record, route.outcome.decision, probe);
            trace_public_rpc_scout_clmm_quote_audit(route, record, intent, probe);
            trace_public_rpc_scout_process_result(route, record, Err(error));
            if exact_target_public_scout_record(record)
                && route.outcome.decision == RouteDecision::PublicRpcScout
            {
                let identity = process_intent_error_identity(error);
                let detail = format!(
                    "{}:{}",
                    encode_process_intent_error_stage(identity),
                    encode_process_intent_error_reason(identity)
                );
                trace_target_public_scout_blocked(
                    record,
                    route,
                    "process_intent",
                    TargetPublicScoutBlockedReason::GuardFailed,
                    &detail,
                );
            }
            let identity = process_intent_error_identity(error);
            trace_run40_scorecard_replay_gate(
                record,
                "process_intent_err",
                &format!(
                    "stage={} reason={} lookup_ok={} policy_ok={} assembly_ready={} pm_reservation_created={} force_live_inventory_reservation={} emit_attempted={} emit_ok={}",
                    encode_process_intent_error_stage(identity),
                    encode_process_intent_error_reason(identity),
                    probe.lookup_ok,
                    probe.policy_ok,
                    probe.assembly_ready,
                    probe.pm_reservation_created,
                    inputs.force_live_inventory_reservation,
                    probe.emit_attempted,
                    probe.emit_ok
                ),
            );
            record_pipeline_error_diag(error, Some(intent), inputs.clmm_exact_quote_arena);
            record_terminal_pipeline_diag(Some(error), attempted_no_send_backend);
            emit_pipeline_drop_event(shared, record, resolved, route, intent, error);
        }
    }
    result
        .map(|(receipt, _)| receipt)
        .map_err(|(error, _)| error)
}

