pub fn init_afxdp_hydration_hint_bridge(control_flags: Arc<MappedSegment<ShadowControlFlagsV1>>) {
    let _ = AFXDP_HYDRATION_HINT_FLAGS.set(control_flags);
}

fn record_afxdp_pool_hydration_hint(
    _worker_id: u32,
    record: &IngressRecord,
) -> HydrationHintOutcome {
    if !matches!(
        record.signal_source,
        SIGNAL_SOURCE_AFXDP | SIGNAL_SOURCE_DPDK
    ) {
        return HydrationHintOutcome::NotApplicable;
    }
    let Some(control_flags) = AFXDP_HYDRATION_HINT_FLAGS.get() else {
        return HydrationHintOutcome::FlagsUnavailable;
    };
    let hint_slot = HOT_POOL_HINT_CURSOR.fetch_add(1, Ordering::Relaxed) as u8;
    let enqueued = control_flags.payload().record_hot_pool_hint(
        hint_slot,
        record.pool_pubkey,
        record.signal_source,
    );
    if enqueued {
        WORKER_AFXDP_HYDRATION_REQUEST_ENQUEUED.fetch_add(1, Ordering::Relaxed);
        HydrationHintOutcome::Enqueued
    } else {
        WORKER_AFXDP_HYDRATION_REQUEST_DEDUPED.fetch_add(1, Ordering::Relaxed);
        HydrationHintOutcome::Deduped
    }
}

