/// Emit a single-line tactic attribution summary to stdout.
/// Called periodically by the hot path; zero allocation.
fn log_tactic_telemetry(worker_id: u32, tac: &TacticAttributionCounters) {
    println!(
        "[tac-w{worker_id}] \
         density intents={} avg={}\u{00b5}lam/CU | \
         baseline_jito intents={} avg={}\u{00b5}lam/CU | \
         exhaust eval={} eligible={} deploy_lam={} | \
         tick_boundary events={} suppressed={}",
        tac.cu_density_intents,
        tac.avg_density_tip_per_cu(),
        tac.baseline_jito_intents,
        tac.avg_baseline_tip_per_cu(),
        tac.exhaust_evaluated,
        tac.exhaust_eligible,
        tac.exhaust_deploy_lamports,
        tac.tick_boundary_events,
        tac.tick_boundary_suppressed,
    );
}

/// Shared-memory resources opened once at startup and `Arc`-cloned into every
/// money-worker thread.  All handles are read-only mmap views — zero-copy,
/// zero-allocation on the hot path.
pub struct MoneyWorkerSharedDeps {
    pub health: Arc<MappedSegment<HealthSnapshot>>,
    pub pool_tag_map: Arc<MappedTagMap>,
    pub pool_arena: Arc<MappedPoolStateArena>,
    pub clmm_exact_quote_arena: Option<Arc<MappedClmmExactQuoteArena>>,
    pub clmm_exact_quote_request_arena: Option<Arc<MappedClmmExactQuoteRequestArena>>,
    pub mint_tag_map: Arc<MappedTagMap>,
    pub mint_arena: Arc<MappedMintStateArena>,
    // --- G4-G1d: route hydration segments ---
    pub blockhash: Arc<MappedSegment<BlockhashSnapshot>>,
    pub leader_schedule: Arc<MappedSegment<LeaderSchedulePayload>>,
    pub risk_flags: Arc<MappedSegment<RiskFlags64B>>,
    pub egress_health: Arc<MappedSegment<EgressHealthSnapshot>>,
    pub routing_cfg: GuerrilaRoutingConfig,
    // --- G4-G1e: execution-phase deps ---
    /// Per-worker signer keypair (same for all workers — wraps the fee payer).
    pub signer: Arc<ThreadLocalSigner>,
    /// Global inventory allocation counter (shared across all workers).
    pub inventory_alloc: Arc<AtomicU64>,
    /// Boot-time snapshot of signer-owned token accounts for fail-closed CLMM gating.
    pub signer_token_inventory: Arc<SignerTokenInventory>,
    /// Absolute per-entity inventory ceiling in lamports.
    pub inventory_ceiling: u64,
    /// Jito tip LUT segment (shm, published by shadow-oracle).
    pub tip_lut_jito: Arc<MappedSegment<TipLutJitoSegment>>,
    /// Base (Harmonic) tip LUT segment (shm, published by shadow-oracle).
    pub tip_lut_base: Arc<MappedSegment<TipLutBaseSegment>>,
    /// Fixed swap account template (program_id + account metas).
    pub swap_accounts: FixedSwapAccounts,
    /// Fixed swap instruction data template.
    pub swap_ix_data: FixedSwapIxData,
    /// Rotated Jito tip account.
    pub jito_tip_rotation: JitoTipRotation,
    /// Base compute unit limit for the route.
    pub route_base_cu_limit: u32,
    /// Observe-only OPSO sidecar segment (optional; missing sidecar falls back to baseline).
    pub opso_sidecar: Option<Arc<MappedSegment<OpsShockSidecarSnapshot>>>,
    pub opso_stale_action: shadow_core::config::OpsoStaleAction,
    pub opso_max_staleness_ns: u64,
    /// ShadowGuard program ID.
    pub shadow_guard_program_id: [u8; 32],
    /// ShadowGuard vault-in pubkey.
    pub guard_vault_in_pubkey: [u8; 32],
    /// ShadowGuard vault-out pubkey.
    pub guard_vault_out_pubkey: [u8; 32],
    /// Number of nonce tuples to pre-seed per worker at startup.
    pub nonce_prefill: usize,
    /// Oracle-derived thresholds for intent classification.
    pub intent_shape: IntentShapeConfig,
    /// G9A: quant tactics configuration for density-optimized CU limit.
    pub quant_tactics: Option<shadow_core::config::QuantTacticsConfig>,
    /// G12 observe-only rollout backend: build/sign privately, publish shadow event only.
    pub rollout_no_send_backend: bool,
    /// SH8-B observe-only local replay: permit AF_XDP records from a catching-up
    /// validator to clear the stale-slot gate without affecting live modes.
    pub sh8_afxdp_allow_local_replay_stale_slots: bool,
    /// SH7-A: admit external/local Geyser only into the observe-only no-send shadow path.
    pub r0_allow_geyser_observe_shadow: bool,
    /// R1 tiny-live automatic admission. Fixed-width runtime view copied from config.
    pub r1_live_admission: R1LiveAdmissionRuntimeConfig,
}

/// Oracle-derived thresholds for intent classification.
///
/// Fixed-width, set at startup from config.  O(1) per-intent.
#[derive(Debug, Clone, Copy)]
pub struct IntentShapeConfig {
    /// Maximum live trade input in lamports (default 15 SOL = 15_000_000_000).
    pub max_live_trade_input_lamports: u64,
    /// Whether to emit ApexPartial intents for over-cap opportunities.
    pub allow_clamped_apex_partials: bool,
    /// Whether to allow ATBA (Jito-only) intents when CLMM sidecar is present.
    ///
    /// **Intentionally deferred**: ATBA requires a live CLMM sidecar publishing
    /// `dist_to_tick_lamports` per pool.  Until that sidecar exists, this flag
    /// has no runtime effect — `evaluate_target()` is called with
    /// `clmm_available=false`, so ATBA candidacy always returns Ineligible.
    /// The policy helpers and route-matrix proofs are in place; only the
    /// sidecar data source is missing.
    pub allow_atba_jito_only: bool,
}

/// Execution-phase dependencies that come from startup configuration,
/// not from shared-memory segments.
pub struct ExecutionDeps {
    pub signer: Arc<ThreadLocalSigner>,
    pub inventory_alloc: Arc<AtomicU64>,
    pub signer_token_inventory: Arc<SignerTokenInventory>,
    pub inventory_ceiling: u64,
    pub swap_accounts: FixedSwapAccounts,
    pub swap_ix_data: FixedSwapIxData,
    pub jito_tip_rotation: JitoTipRotation,
    pub route_base_cu_limit: u32,
    pub shadow_guard_program_id: [u8; 32],
    pub guard_vault_in_pubkey: [u8; 32],
    pub guard_vault_out_pubkey: [u8; 32],
    pub nonce_prefill: usize,
}

// Boot loaders live in boot_exec.rs to keep money_worker.rs free of
// filesystem operations (the G4-G1f structural test scans for banned
// syscall patterns to enforce no-syscall on the hot path).
pub use crate::boot_exec::{
    boot_execution_deps, decode_pubkey, load_signer, load_tip_lut, new_worker_local_state,
    seed_nonce_ring, BootExecError, MAX_INVENTORY_CEILING_LAMPORTS, MIN_INVENTORY_CEILING_LAMPORTS,
    TIP_LUT_FILE_SIZE,
};

#[inline]
fn sol_to_lamports(sol: f64) -> u64 {
    if !sol.is_finite() || sol <= 0.0 {
        0
    } else {
        (sol * 1_000_000_000.0) as u64
    }
}

fn r1_runtime_config(
    rollout_config: Option<&shadow_core::config::RolloutConfig>,
    r1_config: Option<&shadow_core::config::R1Config>,
) -> R1LiveAdmissionRuntimeConfig {
    let cfg = r1_config
        .map(|cfg| cfg.live_admission.clone())
        .unwrap_or_default();
    let no_send_observe = rollout_config
        .map(|cfg| cfg.mode == shadow_core::config::RolloutMode::ObserveOnly && cfg.no_send_backend)
        .unwrap_or(false);
    let rollout_max_trade = if no_send_observe {
        u64::MAX
    } else {
        rollout_config
            .map(|cfg| sol_to_lamports(cfg.max_live_trade_input_sol))
            .unwrap_or(u64::MAX)
    };
    let rollout_max_position = if no_send_observe {
        u64::MAX
    } else {
        rollout_config
            .map(|cfg| sol_to_lamports(cfg.max_position_sol_per_mint))
            .unwrap_or(u64::MAX)
    };
    let rollout_max_notional = if no_send_observe {
        u64::MAX
    } else {
        rollout_config
            .map(|cfg| sol_to_lamports(cfg.max_notional_sol_per_entity))
            .unwrap_or(u64::MAX)
    };

    R1LiveAdmissionRuntimeConfig {
        mode: cfg.mode,
        source_required: cfg.source_required,
        require_private_grade: cfg.require_private_grade,
        require_shadow_guard: cfg.require_shadow_guard,
        require_micro_market_uplift: cfg.require_micro_market_uplift,
        require_pre_sign_egress_admission: cfg.require_pre_sign_egress_admission,
        max_live_trade_input_lamports: sol_to_lamports(cfg.max_live_trade_input_sol)
            .min(rollout_max_trade),
        max_position_lamports_per_mint: sol_to_lamports(cfg.max_position_sol_per_mint)
            .min(rollout_max_position),
        max_notional_lamports_per_entity: sol_to_lamports(cfg.max_notional_sol_per_entity)
            .min(rollout_max_notional),
        min_retained_ev_lamports: cfg.min_retained_ev_lamports,
        min_net_after_fee_lamports: cfg.min_net_after_fee_lamports,
    }
}

/// Open all shared-memory resources needed by money workers.
///
/// Called once at startup before spawning threads.  Each `MappedSegment` /
/// arena / tag-map is opened read-only and wrapped in `Arc` for cloning.
///
/// `shm_dir` defaults to `/dev/shm` if the config doesn't override it.
/// `exec` provides execution-phase deps (signer, LUTs, inventory, etc.)
/// from startup configuration.
pub fn open_worker_shared_deps(
    shm_dir: &str,
    routing_cfg: GuerrilaRoutingConfig,
    exec: ExecutionDeps,
    intent_shape: IntentShapeConfig,
    opso_config: Option<shadow_core::config::OpsoConfig>,
    rollout_config: Option<shadow_core::config::RolloutConfig>,
    r1_config: Option<shadow_core::config::R1Config>,
) -> MoneyWorkerSharedDeps {
    let shm = Path::new(shm_dir);

    let health = MappedSegment::<HealthSnapshot>::open_ro(&shm.join("shadow_health"))
        .unwrap_or_else(|e| panic!("FATAL  failed to open health segment: {e}"));

    let pool_tag_map = shadow_ipc::tag_map::open_pool_index_map_ro(&shm.join("pool_index_map"))
        .unwrap_or_else(|e| panic!("FATAL  failed to open pool index map: {e}"));

    let pool_arena = MappedPoolStateArena::open_ro(&shm.join("pool_state"))
        .unwrap_or_else(|e| panic!("FATAL  failed to open pool state arena: {e:?}"));

    let clmm_exact_quote_path = shm.join("clmm_exact_quote");
    let clmm_exact_quote_arena = match MappedClmmExactQuoteArena::open_ro(&clmm_exact_quote_path) {
        Ok(arena) => {
            eprintln!(
                "PASS  CLMM exact quote sidecar opened path={} version={} capacity={}",
                clmm_exact_quote_path.display(),
                CLMM_EXACT_QUOTE_VERSION,
                arena.capacity()
            );
            Some(Arc::new(arena))
        }
        Err(err) => {
            let diagnostics = inspect_clmm_exact_quote_arena(&clmm_exact_quote_path).ok();
            log_clmm_exact_quote_sidecar_failure(&clmm_exact_quote_path, &err, diagnostics);
            eprintln!("WARN  CLMM remains fail-closed until exact quote sidecar opens cleanly");
            None
        }
    };
    let clmm_exact_quote_request_arena = match MappedClmmExactQuoteRequestArena::open_rw(
        &shm.join("clmm_exact_quote_request"),
    ) {
        Ok(arena) => Some(Arc::new(arena)),
        Err(err) => {
            eprintln!(
                    "WARN  CLMM exact quote request sidecar unavailable ({err:?}) — worker cannot prime CLMM exact quotes"
                );
            None
        }
    };

    let mint_tag_map = shadow_ipc::tag_map::open_mint_index_map_ro(&shm.join("mint_index_map"))
        .unwrap_or_else(|e| panic!("FATAL  failed to open mint index map: {e}"));

    let mint_arena = MappedMintStateArena::open_ro(&shm.join("mint_state"))
        .unwrap_or_else(|e| panic!("FATAL  failed to open mint state arena: {e:?}"));

    let blockhash = MappedSegment::<BlockhashSnapshot>::open_ro(&shm.join("shadow_blockhash"))
        .unwrap_or_else(|e| panic!("FATAL  failed to open blockhash segment: {e}"));

    let leader_schedule =
        MappedSegment::<LeaderSchedulePayload>::open_ro(&shm.join("shadow_leader_schedule"))
            .unwrap_or_else(|e| panic!("FATAL  failed to open leader schedule segment: {e}"));

    let risk_flags = MappedSegment::<RiskFlags64B>::open_ro(&shm.join("shadow_risk_flags"))
        .unwrap_or_else(|e| panic!("FATAL  failed to open risk flags segment: {e}"));

    let egress_health =
        MappedSegment::<EgressHealthSnapshot>::open_ro(&shm.join("shadow_egress_health"))
            .unwrap_or_else(|e| panic!("FATAL  failed to open egress health segment: {e}"));

    // Tip LUT segments (published by shadow-oracle, double-buffered).
    let tip_lut_jito =
        MappedSegment::<TipLutJitoSegment>::open_ro(&shm.join("shadow_tip_lut_jito"))
            .unwrap_or_else(|e| panic!("FATAL  failed to open Jito tip LUT segment: {e}"));

    let tip_lut_base =
        MappedSegment::<TipLutBaseSegment>::open_ro(&shm.join("shadow_tip_lut_base"))
            .unwrap_or_else(|e| panic!("FATAL  failed to open base tip LUT segment: {e}"));

    let opso_stale_action = opso_config
        .as_ref()
        .map(|cfg| cfg.sidecar_stale_action)
        .unwrap_or(shadow_core::config::OpsoStaleAction::FallbackToBaseline);
    let opso_max_staleness_ns = opso_config
        .as_ref()
        .map(|cfg| cfg.max_sidecar_staleness_ns)
        .unwrap_or(0);
    let opso_sidecar = match opso_config.as_ref() {
        Some(cfg) if cfg.enabled && cfg.sidecar_enabled => {
            match open_shadow_ops_shock_sidecar_ro() {
                Ok(seg) => Some(Arc::new(seg)),
                Err(_) => None,
            }
        }
        _ => None,
    };
    let rollout_no_send_backend = rollout_config
        .as_ref()
        .map(|cfg| cfg.mode == shadow_core::config::RolloutMode::ObserveOnly && cfg.no_send_backend)
        .unwrap_or(false);
    let r0_allow_geyser_observe_shadow = rollout_config
        .as_ref()
        .map(|cfg| cfg.r0_allow_geyser_observe_shadow)
        .unwrap_or(false);
    let sh8_afxdp_allow_local_replay_stale_slots = rollout_config
        .as_ref()
        .map(|cfg| {
            cfg.mode == shadow_core::config::RolloutMode::ObserveOnly
                && cfg.no_send_backend
                && cfg.sh8_afxdp_allow_local_replay_stale_slots
        })
        .unwrap_or(false);
    let public_scout_max_attempts_per_window = r1_config
        .as_ref()
        .map(|cfg| cfg.public_scout.max_scout_attempts_per_window as u64)
        .unwrap_or(u64::MAX);
    PUBLIC_SCOUT_MAX_ATTEMPTS_PER_WINDOW
        .store(public_scout_max_attempts_per_window, Ordering::Relaxed);
    reset_public_scout_attempt_latch_state();
    let r1_live_admission = r1_runtime_config(rollout_config.as_ref(), r1_config.as_ref());

    MoneyWorkerSharedDeps {
        health: Arc::new(health),
        pool_tag_map: Arc::new(pool_tag_map),
        pool_arena: Arc::new(pool_arena),
        clmm_exact_quote_arena,
        clmm_exact_quote_request_arena,
        mint_tag_map: Arc::new(mint_tag_map),
        mint_arena: Arc::new(mint_arena),
        blockhash: Arc::new(blockhash),
        leader_schedule: Arc::new(leader_schedule),
        risk_flags: Arc::new(risk_flags),
        egress_health: Arc::new(egress_health),
        routing_cfg,
        signer: exec.signer,
        inventory_alloc: exec.inventory_alloc,
        signer_token_inventory: exec.signer_token_inventory,
        inventory_ceiling: exec.inventory_ceiling,
        tip_lut_jito: Arc::new(tip_lut_jito),
        tip_lut_base: Arc::new(tip_lut_base),
        swap_accounts: exec.swap_accounts,
        swap_ix_data: exec.swap_ix_data,
        jito_tip_rotation: exec.jito_tip_rotation,
        route_base_cu_limit: exec.route_base_cu_limit,
        opso_sidecar,
        opso_stale_action,
        opso_max_staleness_ns,
        shadow_guard_program_id: exec.shadow_guard_program_id,
        guard_vault_in_pubkey: exec.guard_vault_in_pubkey,
        guard_vault_out_pubkey: exec.guard_vault_out_pubkey,
        nonce_prefill: exec.nonce_prefill,
        intent_shape,
        quant_tactics: None,
        rollout_no_send_backend,
        sh8_afxdp_allow_local_replay_stale_slots,
        r0_allow_geyser_observe_shadow,
        r1_live_admission,
    }
}

/// Per-worker thread-local state.  One instance per money worker, never shared.
///
/// **Zero-allocation**: `SigDedupe` (2 KiB ring) and `PoolOverlay` (16-slot
/// fixed array) live entirely on the stack / in the struct — no heap.
/// `NonceRing` is fixed-size (128 entries, ~8 KiB).
pub struct WorkerLocalState {
    /// Signature dedupe filter — first gate in the hot path.
    pub dedupe: SigDedupe,
    /// Dirty overlay tracking unconfirmed reserve deltas for pools touched by
    /// this worker.  Seeded empty; accumulated on successful egress push.
    pub overlay: PoolOverlay,
    /// Ed25519 nonce ring for signing.  Populated externally (e.g. by a nonce
    /// generator thread); consumed one tuple per successful emit.
    pub nonce_ring: NonceRing,
    /// G9A: per-worker tactic attribution counters (thread-local, zero alloc).
    pub tac: TacticAttributionCounters,
}

impl WorkerLocalState {
    /// Create a fresh worker-local state.  Called once per thread at startup.
    pub fn new() -> Self {
        Self {
            dedupe: SigDedupe::new(),
            overlay: PoolOverlay::new(),
            nonce_ring: NonceRing {
                tuples: [NonceTuple {
                    secret_scalar: [0; 32],
                    nonce_pubkey: [0; 32],
                }; 128],
                head: 0,
                tail: 0,
            },
            tac: Default::default(),
        }
    }
}

/// Per-worker handle returned to the caller for join.
pub struct MoneyWorkerHandle {
    #[allow(dead_code)]
    pub worker_id: u32,
    pub thread: thread::JoinHandle<()>,
    #[allow(dead_code)]
    pub nonce_producer: NonceProducerHandle,
}

/// Spawn one money-worker thread per `topology.money_workers`.
///
/// Each thread opens its own feed rings (consumer side), Jito egress ring
/// (producer side), and Harmonic egress ring (producer side), then enters
/// the worker loop.
///
/// `shared` provides read-only handles to health, pool/mint tag maps+arenas.
///
/// Returns a handle vec for the caller to join.
pub fn spawn_money_workers(
    topology: &ValidatedTopology,
    shared: &MoneyWorkerSharedDeps,
) -> Vec<MoneyWorkerHandle> {
    let num_workers = topology.money_workers;
    let replay_extra = if crate::scorecard_replay::scorecard_replay_requested() {
        1
    } else {
        0
    };
    let num_producers = topology.shred_capture_workers + topology.grpc_workers + replay_extra;

    let mut handles = Vec::with_capacity(num_workers as usize);

    for worker_id in 0..num_workers {
        let np = num_producers;
        let health = Arc::clone(&shared.health);
        let pool_tag_map = Arc::clone(&shared.pool_tag_map);
        let pool_arena = Arc::clone(&shared.pool_arena);
        let clmm_exact_quote_arena = shared.clmm_exact_quote_arena.as_ref().map(Arc::clone);
        let clmm_exact_quote_request_arena = shared
            .clmm_exact_quote_request_arena
            .as_ref()
            .map(Arc::clone);
        let mint_tag_map = Arc::clone(&shared.mint_tag_map);
        let mint_arena = Arc::clone(&shared.mint_arena);
        let blockhash = Arc::clone(&shared.blockhash);
        let leader_schedule = Arc::clone(&shared.leader_schedule);
        let risk_flags = Arc::clone(&shared.risk_flags);
        let egress_health = Arc::clone(&shared.egress_health);
        let routing_cfg = shared.routing_cfg.clone();
        let signer = Arc::clone(&shared.signer);
        let inventory_alloc = Arc::clone(&shared.inventory_alloc);
        let signer_token_inventory = Arc::clone(&shared.signer_token_inventory);
        let inventory_ceiling = shared.inventory_ceiling;
        let tip_lut_jito = Arc::clone(&shared.tip_lut_jito);
        let tip_lut_base = Arc::clone(&shared.tip_lut_base);
        let swap_accounts = shared.swap_accounts.clone();
        let swap_ix_data = shared.swap_ix_data.clone();
        let jito_tip_rotation = shared.jito_tip_rotation;
        let route_base_cu_limit = shared.route_base_cu_limit;
        let opso_sidecar = shared.opso_sidecar.as_ref().map(Arc::clone);
        let opso_stale_action = shared.opso_stale_action;
        let opso_max_staleness_ns = shared.opso_max_staleness_ns;
        let shadow_guard_program_id = shared.shadow_guard_program_id;
        let guard_vault_in_pubkey = shared.guard_vault_in_pubkey;
        let guard_vault_out_pubkey = shared.guard_vault_out_pubkey;
        let nonce_prefill = shared.nonce_prefill;
        let intent_shape = shared.intent_shape;
        let quant_tactics = shared.quant_tactics.clone();
        let rollout_no_send_backend = shared.rollout_no_send_backend;
        let sh8_afxdp_allow_local_replay_stale_slots =
            shared.sh8_afxdp_allow_local_replay_stale_slots;
        let r0_allow_geyser_observe_shadow = shared.r0_allow_geyser_observe_shadow;
        let r1_live_admission = shared.r1_live_admission;

        // Create shared nonce ring and spawn background producer thread.
        // Index base: worker_id * 2^32 so each worker's nonce domain never overlaps.
        let shared_nonce_ring = Arc::new(SharedNonceRing::new());
        let nonce_producer_handle = spawn_nonce_producer(
            worker_id,
            Arc::clone(&signer),
            Arc::clone(&shared_nonce_ring),
            worker_id as u64 * (1u64 << 32),
        );

        let handle = thread::Builder::new()
            .name(format!("money-worker-{worker_id}"))
            .spawn(move || {
                // 1. Open per-producer feed rings (consumer/rw).
                let mut feed_rings: Vec<MappedSpscRing<IngressRecord>> =
                    Vec::with_capacity(np as usize);

                for producer_id in 0..np {
                    let path = feed_ring_path(worker_id as usize, producer_id as usize);
                    match open_feed_ring_rw(&path) {
                        Ok(ring) => feed_rings.push(ring),
                        Err(e) => {
                            panic!(
                                "money-worker-{worker_id}: failed to open feed ring \
                                 w{worker_id}_p{producer_id}: {e}"
                            );
                        }
                    }
                }
                println!(
                    "money-worker-{worker_id}: opened {} feed ring(s)",
                    feed_rings.len()
                );

                // 2. Open this worker's Jito egress ring (producer/rw).
                let jito_ring: MappedSpscRing<SignedTxEnvelope> =
                    open_jito_egress_ring_rw(worker_id).unwrap_or_else(|e| {
                        panic!("money-worker-{worker_id}: failed to open Jito egress ring: {e}");
                    });
                println!("money-worker-{worker_id}: opened Jito egress ring");

                // 3. Open this worker's TPU egress ring (producer/rw).
                let tpu_ring: MappedSpscRing<SignedTxEnvelope> = open_tpu_egress_ring_rw(worker_id)
                    .unwrap_or_else(|e| {
                        panic!("money-worker-{worker_id}: failed to open TPU egress ring: {e}");
                    });
                println!("money-worker-{worker_id}: opened TPU egress ring");

                // 4. Open this worker's Harmonic egress ring (producer/rw).
                let harmonic_ring: MappedSpscRing<SignedTxEnvelope> =
                    open_harmonic_egress_ring_rw(worker_id).unwrap_or_else(|e| {
                        panic!(
                            "money-worker-{worker_id}: failed to open Harmonic egress ring: {e}"
                        );
                    });
                println!("money-worker-{worker_id}: opened Harmonic egress ring");

                let rollout_shadow_sink = if rollout_no_send_backend {
                    let ring = open_rollout_shadow_ring_rw(worker_id).unwrap_or_else(|e| {
                        panic!("money-worker-{worker_id}: failed to open rollout shadow ring: {e}");
                    });
                    Some(NoSendSink::new(ring))
                } else {
                    None
                };
                let clmm_exact_quote_ready_ring = ensure_clmm_exact_quote_ready_ring_rw(
                    worker_id,
                    CLMM_EXACT_QUOTE_READY_RING_CAPACITY,
                )
                .unwrap_or_else(|e| {
                    panic!(
                        "money-worker-{worker_id}: failed to open CLMM exact-quote ready ring: {e}"
                    );
                });

                // 5. Worker loop with pipeline execution (G4-G1e).
                let mut local = new_worker_local_state(&signer, worker_id, nonce_prefill);
                let shared_refs = SharedRefs {
                    health: &health,
                    pool_tag_map: &pool_tag_map,
                    pool_arena: &pool_arena,
                    clmm_exact_quote_arena: clmm_exact_quote_arena.as_deref(),
                    mint_tag_map: &mint_tag_map,
                    mint_arena: &mint_arena,
                    blockhash: &blockhash,
                    leader_schedule: &leader_schedule,
                    risk_flags: &risk_flags,
                    egress_health: &egress_health,
                    routing_cfg: &routing_cfg,
                    signer: &signer,
                    inventory_alloc: &inventory_alloc,
                    signer_token_inventory: &signer_token_inventory,
                    inventory_ceiling,
                    tip_lut_jito: &tip_lut_jito,
                    tip_lut_base: &tip_lut_base,
                    swap_accounts: &swap_accounts,
                    swap_ix_data: &swap_ix_data,
                    jito_tip_rotation,
                    route_base_cu_limit,
                    shadow_guard_program_id,
                    guard_vault_in_pubkey,
                    guard_vault_out_pubkey,
                    intent_shape,
                    quant_tactics,
                    rollout_shadow_sink: rollout_shadow_sink
                        .as_ref()
                        .map(|sink| sink as &dyn RolloutShadowPush),
                    rollout_no_send_backend,
                    sh8_afxdp_allow_local_replay_stale_slots,
                    r0_allow_geyser_observe_shadow,
                    r1_live_admission,
                };
                money_worker_loop(
                    worker_id,
                    &feed_rings,
                    &jito_ring,
                    &tpu_ring,
                    &harmonic_ring,
                    &shared_nonce_ring,
                    &mut local,
                    &shared_refs,
                    clmm_exact_quote_request_arena.as_deref(),
                    Some(&clmm_exact_quote_ready_ring),
                    opso_sidecar.as_deref(),
                    opso_stale_action,
                    opso_max_staleness_ns,
                );
            })
            .unwrap_or_else(|e| {
                panic!("failed to spawn money-worker-{worker_id}: {e}");
            });

        handles.push(MoneyWorkerHandle {
            worker_id,
            thread: handle,
            nonce_producer: nonce_producer_handle,
        });
    }

    handles
}

/// Borrowed view of shared deps for the loop body (avoids Arc deref per iter).
struct SharedRefs<'a> {
    health: &'a MappedSegment<HealthSnapshot>,
    pool_tag_map: &'a MappedTagMap,
    pool_arena: &'a MappedPoolStateArena,
    clmm_exact_quote_arena: Option<&'a MappedClmmExactQuoteArena>,
    mint_tag_map: &'a MappedTagMap,
    mint_arena: &'a MappedMintStateArena,
    // --- G4-G1d: route hydration ---
    blockhash: &'a MappedSegment<BlockhashSnapshot>,
    leader_schedule: &'a MappedSegment<LeaderSchedulePayload>,
    risk_flags: &'a MappedSegment<RiskFlags64B>,
    egress_health: &'a MappedSegment<EgressHealthSnapshot>,
    routing_cfg: &'a GuerrilaRoutingConfig,
    // --- G4-G1e: execution ---
    signer: &'a ThreadLocalSigner,
    inventory_alloc: &'a AtomicU64,
    signer_token_inventory: &'a SignerTokenInventory,
    inventory_ceiling: u64,
    tip_lut_jito: &'a MappedSegment<TipLutJitoSegment>,
    tip_lut_base: &'a MappedSegment<TipLutBaseSegment>,
    swap_accounts: &'a FixedSwapAccounts,
    swap_ix_data: &'a FixedSwapIxData,
    jito_tip_rotation: JitoTipRotation,
    route_base_cu_limit: u32,
    shadow_guard_program_id: [u8; 32],
    guard_vault_in_pubkey: [u8; 32],
    guard_vault_out_pubkey: [u8; 32],
    intent_shape: IntentShapeConfig,
    quant_tactics: Option<shadow_core::config::QuantTacticsConfig>,
    rollout_shadow_sink: Option<&'a dyn RolloutShadowPush>,
    rollout_no_send_backend: bool,
    sh8_afxdp_allow_local_replay_stale_slots: bool,
    r0_allow_geyser_observe_shadow: bool,
    r1_live_admission: R1LiveAdmissionRuntimeConfig,
}

/// Result of the early-drop shell.  Carries the resolved arena indices and
/// pool reserve snapshot so the downstream quote/build/sign path never
/// re-does the O(1) lookups.
#[derive(Debug, Clone, Copy)]
pub struct ResolvedRecord {
    /// Pool arena index (from tag-map lookup, arena-verified).
    pub pool_index: u32,
    /// Mint-in arena index.
    pub mint_in_index: u32,
    /// Mint-out arena index.
    pub mint_out_index: u32,
    /// Snapshot of pool reserves at the time of resolution.
    pub reserve_in: u64,
    pub reserve_out: u64,
    /// Health snapshot slot at resolution time.
    pub snapshot_slot: u64,
}

/// Map the wire-level `SIGNAL_SOURCE_*` u8 to the routing-level [`SignalSource`].
///
/// - `PUBLIC_GEYSER` (0) → `PublicGeyser` (routing policy will drop these).
/// - `EXTERNAL_GEYSER` (5) → `PublicGeyser` (observe-only only, never private-grade).
/// - `LOCAL_VALIDATOR_GEYSER` (6) → `PublicGeyser` (useful for SH0/SH1 proof, never private-grade).
/// - `JITO_SEARCHER_API` (1) → `JitoSearcherApi`.
/// - `PRIVATE_MEMPOOL` (2) → `PrivateMempool`.
/// - `HARMONIC_SEARCHER_API` (3) → `PrivateMempool` (private-grade signal).
/// - `AFXDP` (4) → `PrivateMempool` (fastest primary path, private-grade).
/// - anything else → `None` (fail closed).
#[inline]
pub fn signal_source_from_u8(src: u8) -> Option<SignalSource> {
    match src {
        SIGNAL_SOURCE_PUBLIC_GEYSER => Some(SignalSource::PublicGeyser),
        SIGNAL_SOURCE_EXTERNAL_GEYSER => Some(SignalSource::PublicGeyser),
        SIGNAL_SOURCE_LOCAL_VALIDATOR_GEYSER => Some(SignalSource::PublicGeyser),
        SIGNAL_SOURCE_JITO_SEARCHER_API => Some(SignalSource::JitoSearcherApi),
        SIGNAL_SOURCE_PRIVATE_MEMPOOL => Some(SignalSource::PrivateMempool),
        SIGNAL_SOURCE_HARMONIC_SEARCHER_API => Some(SignalSource::PrivateMempool),
        SIGNAL_SOURCE_AFXDP => Some(SignalSource::PrivateMempool),
        SIGNAL_SOURCE_DPDK => Some(SignalSource::PrivateMempool),
        _ => None,
    }
}

#[inline(always)]
fn is_observe_shadow_geyser_signal(signal_source: u8) -> bool {
    matches!(
        signal_source,
        SIGNAL_SOURCE_EXTERNAL_GEYSER | SIGNAL_SOURCE_LOCAL_VALIDATOR_GEYSER
    )
}

#[inline(always)]
fn record_geyser_shadow_no_send_source_diag(signal_source: u8) {
    match signal_source {
        SIGNAL_SOURCE_EXTERNAL_GEYSER => {
            WORKER_GEYSER_SHADOW_NO_SEND_SOURCE_EXTERNAL.fetch_add(1, Ordering::Relaxed);
        }
        SIGNAL_SOURCE_LOCAL_VALIDATOR_GEYSER => {
            WORKER_GEYSER_SHADOW_NO_SEND_SOURCE_LOCAL_VALIDATOR.fetch_add(1, Ordering::Relaxed);
        }
        _ => {}
    }
}

#[inline(always)]
fn record_r1_auto_admission_drop(reason: R1DropReason) {
    match reason {
        R1DropReason::Source => {
            WORKER_R1_AUTO_ADMISSION_DROP_SOURCE.fetch_add(1, Ordering::Relaxed);
        }
        R1DropReason::NonPrivateGrade => {
            WORKER_R1_AUTO_ADMISSION_DROP_NON_PRIVATE_GRADE.fetch_add(1, Ordering::Relaxed);
        }
        R1DropReason::ShadowGuard => {
            WORKER_R1_AUTO_ADMISSION_DROP_SHADOWGUARD.fetch_add(1, Ordering::Relaxed);
        }
        R1DropReason::MicroMarket | R1DropReason::RetainedEvFloor => {
            WORKER_R1_AUTO_ADMISSION_DROP_MICRO_MARKET.fetch_add(1, Ordering::Relaxed);
        }
        R1DropReason::NetAfterFeeFloor => {
            WORKER_R1_AUTO_ADMISSION_DROP_MICRO_MARKET.fetch_add(1, Ordering::Relaxed);
        }
        R1DropReason::Egress => {
            WORKER_R1_AUTO_ADMISSION_DROP_EGRESS.fetch_add(1, Ordering::Relaxed);
        }
        R1DropReason::Inventory => {
            WORKER_R1_AUTO_ADMISSION_DROP_INVENTORY.fetch_add(1, Ordering::Relaxed);
        }
        R1DropReason::Cap => {
            WORKER_R1_AUTO_ADMISSION_DROP_CAP.fetch_add(1, Ordering::Relaxed);
        }
        R1DropReason::Stale | R1DropReason::Health => {
            WORKER_R1_AUTO_ADMISSION_DROP_STALE.fetch_add(1, Ordering::Relaxed);
        }
        R1DropReason::PublicRoute
        | R1DropReason::ManualAllowlistSelected
        | R1DropReason::PassAllForbidden => {
            WORKER_R1_AUTO_ADMISSION_DROP_PUBLIC_ROUTE.fetch_add(1, Ordering::Relaxed);
        }
    }
}

#[inline(always)]
fn record_r1_auto_admission_proof_filter_breakdown(reason: R1ProofFilterRejectReason) {
    match reason {
        R1ProofFilterRejectReason::NoQuote => {
            WORKER_R1_AUTO_ADMISSION_REJECT_PROOF_FILTER_NO_QUOTE.fetch_add(1, Ordering::Relaxed);
        }
        R1ProofFilterRejectReason::NoPositiveEv => {
            WORKER_R1_AUTO_ADMISSION_REJECT_PROOF_FILTER_NO_POSITIVE_EV
                .fetch_add(1, Ordering::Relaxed);
        }
        R1ProofFilterRejectReason::NoShadowGuard => {
            WORKER_R1_AUTO_ADMISSION_REJECT_PROOF_FILTER_NO_SHADOW_GUARD
                .fetch_add(1, Ordering::Relaxed);
        }
        R1ProofFilterRejectReason::PublicScoutShape => {
            WORKER_R1_AUTO_ADMISSION_REJECT_PROOF_FILTER_PUBLIC_SCOUT_SHAPE
                .fetch_add(1, Ordering::Relaxed);
        }
        R1ProofFilterRejectReason::Other => {
            WORKER_R1_AUTO_ADMISSION_REJECT_PROOF_FILTER_OTHER.fetch_add(1, Ordering::Relaxed);
        }
    }
}

#[inline(always)]
fn record_r1_auto_admission_micro_market_breakdown_from_drop(reason: R1DropReason) {
    match reason {
        R1DropReason::MicroMarket => {
            WORKER_R1_AUTO_ADMISSION_REJECT_MICRO_MARKET_NO_UPLIFT.fetch_add(1, Ordering::Relaxed);
        }
        R1DropReason::NetAfterFeeFloor => {
            WORKER_R1_AUTO_ADMISSION_REJECT_MICRO_MARKET_NEGATIVE_EV
                .fetch_add(1, Ordering::Relaxed);
        }
        R1DropReason::RetainedEvFloor => {
            WORKER_R1_AUTO_ADMISSION_REJECT_MICRO_MARKET_BELOW_FLOOR
                .fetch_add(1, Ordering::Relaxed);
        }
        _ => {
            WORKER_R1_AUTO_ADMISSION_REJECT_MICRO_MARKET_OTHER.fetch_add(1, Ordering::Relaxed);
        }
    }
}

#[inline(always)]
fn record_public_scout_shape_reject(
    record: &IngressRecord,
    route_decision: RouteDecision,
    reason: PublicScoutShapeRejectReason,
) {
    match reason {
        PublicScoutShapeRejectReason::None => {}
        PublicScoutShapeRejectReason::RouteNotPublicScout => {
            WORKER_R1_AUTO_ADMISSION_REJECT_PUBLIC_SCOUT_SHAPE_ROUTE_NOT_PUBLIC_SCOUT
                .fetch_add(1, Ordering::Relaxed);
        }
        PublicScoutShapeRejectReason::WrongSource => {
            WORKER_R1_AUTO_ADMISSION_REJECT_PUBLIC_SCOUT_SHAPE_WRONG_SOURCE
                .fetch_add(1, Ordering::Relaxed);
        }
        PublicScoutShapeRejectReason::WrongVenue => {
            WORKER_R1_AUTO_ADMISSION_REJECT_PUBLIC_SCOUT_SHAPE_WRONG_VENUE
                .fetch_add(1, Ordering::Relaxed);
        }
        PublicScoutShapeRejectReason::MissingTemplateFamily => {
            WORKER_R1_AUTO_ADMISSION_REJECT_PUBLIC_SCOUT_SHAPE_MISSING_TEMPLATE_FAMILY
                .fetch_add(1, Ordering::Relaxed);
        }
        PublicScoutShapeRejectReason::RouteTemplateMismatch => {
            WORKER_R1_AUTO_ADMISSION_REJECT_PUBLIC_SCOUT_SHAPE_ROUTE_TEMPLATE_MISMATCH
                .fetch_add(1, Ordering::Relaxed);
        }
        PublicScoutShapeRejectReason::Other => {
            WORKER_R1_AUTO_ADMISSION_REJECT_PUBLIC_SCOUT_SHAPE_OTHER
                .fetch_add(1, Ordering::Relaxed);
        }
    }
    set_last_public_scout_shape_reject(record, route_decision, reason);
}

#[inline(always)]
fn record_r1_auto_admission_reject(record: &IngressRecord, reason: R1AutoAdmissionRejectReason) {
    match reason {
        R1AutoAdmissionRejectReason::ProofFilter => {
            WORKER_R1_AUTO_ADMISSION_REJECT_PROOF_FILTER.fetch_add(1, Ordering::Relaxed);
        }
        R1AutoAdmissionRejectReason::TemplateExecutability => {
            WORKER_R1_AUTO_ADMISSION_REJECT_TEMPLATE_EXECUTABILITY.fetch_add(1, Ordering::Relaxed);
        }
        R1AutoAdmissionRejectReason::AttemptLatch => {
            WORKER_R1_AUTO_ADMISSION_REJECT_ATTEMPT_LATCH.fetch_add(1, Ordering::Relaxed);
            WORKER_R1_AUTO_ADMISSION_REJECT_PROOF_FILTER_ATTEMPT_LATCH
                .fetch_add(1, Ordering::Relaxed);
        }
        _ => {}
    }
    set_last_r1_auto_admission_reject(record, reason);
}

#[inline(always)]
fn record_r1_template_executability_reject(
    record: &IngressRecord,
    route_decision: RouteDecision,
    failure: ClmmPublicScoutOutputAccountFailure,
) {
    set_last_r1_template_executability_reject(record, route_decision, failure);
    record_r1_auto_admission_reject(record, R1AutoAdmissionRejectReason::TemplateExecutability);
    record_run38_target_r1_reject(
        record,
        route_decision,
        R1AutoAdmissionRejectReason::TemplateExecutability,
    );
}

#[inline(always)]
fn record_r1_admit_to_process_intent_attempt() {
    WORKER_R1_AUTO_ADMISSION_ADMIT_TO_PROCESS_INTENT_ATTEMPT.fetch_add(1, Ordering::Relaxed);
}

#[inline(always)]
fn record_r1_admit_to_process_intent_ok() {
    WORKER_R1_AUTO_ADMISSION_ADMIT_TO_PROCESS_INTENT_OK.fetch_add(1, Ordering::Relaxed);
}

#[inline(always)]
fn record_r1_admit_to_process_intent_drop(
    record: &IngressRecord,
    route: &HydratedRoute,
    reason: R1AdmitToProcessIntentDropReason,
    public_scout_shape_reason: Option<PublicScoutShapeRejectReason>,
) {
    WORKER_R1_AUTO_ADMISSION_ADMIT_TO_PROCESS_INTENT_DROP.fetch_add(1, Ordering::Relaxed);
    set_last_r1_admit_to_process_intent_drop(record, route, reason);
    trace_run40_scorecard_replay_gate(
        record,
        "admit_to_process_intent_drop",
        encode_r1_admit_to_process_intent_drop_reason(reason),
    );
    match reason {
        R1AdmitToProcessIntentDropReason::TemplateDrop => {
            record_r1_auto_admission_proof_filter_breakdown(
                R1ProofFilterRejectReason::PublicScoutShape,
            );
            record_public_scout_shape_reject(
                record,
                route.outcome.decision,
                public_scout_shape_reason.unwrap_or(PublicScoutShapeRejectReason::Other),
            );
        }
        R1AdmitToProcessIntentDropReason::RequestArenaMissing
        | R1AdmitToProcessIntentDropReason::AmountPreviewFailed
        | R1AdmitToProcessIntentDropReason::PublishFailed
        | R1AdmitToProcessIntentDropReason::QuoteArenaMissing
        | R1AdmitToProcessIntentDropReason::OutstandingSamePool
        | R1AdmitToProcessIntentDropReason::QuoteWaitTimeout => {
            record_r1_auto_admission_proof_filter_breakdown(R1ProofFilterRejectReason::NoQuote);
        }
        R1AdmitToProcessIntentDropReason::None => {}
    }
}

#[inline(always)]
fn has_active_lut_for_route(
    route: RouteDecision,
    jito_lut_present: bool,
    harmonic_lut_present: bool,
) -> bool {
    match route {
        RouteDecision::JitoBundle
        | RouteDecision::PublicRpcScout
        | RouteDecision::TpuQuicPublic => jito_lut_present,
        RouteDecision::HarmonicBundle => harmonic_lut_present,
        RouteDecision::Drop => false,
        #[cfg(feature = "public_lane")]
        RouteDecision::StakedBlast => false,
    }
}

#[inline(always)]
fn shadow_guard_template_configured(shared: &SharedRefs<'_>) -> bool {
    shared.shadow_guard_program_id != [0u8; 32]
        && shared.guard_vault_in_pubkey != [0u8; 32]
        && shared.guard_vault_out_pubkey != [0u8; 32]
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum R1AutoAdmissionOutcome {
    Admitted,
    Dropped(R1DropReason),
    ProofFilterDrop,
    TemplateExecutabilityDrop,
    AttemptLatchDrop,
}

#[derive(Serialize)]
struct Run39BroadSurfaceObservation {
    record_type: &'static str,
    unix_ns: u64,
    slot: u64,
    signature: String,
    source: String,
    venue: String,
    route: &'static str,
    route_reason: &'static str,
    pool: String,
    mint_in: String,
    mint_out: String,
    trade_size_lamports: u64,
    retained_ev_lamports: u64,
    net_after_fee_lamports: u64,
    input_account_status: String,
    output_account_status: String,
    proof_filter_result: String,
    micro_market_result: String,
    template_executability_result: String,
    would_admit: bool,
    r1_outcome: &'static str,
}

fn encode_run39_proof_filter_result(
    reason: R1ProofFilterRejectReason,
    public_scout_shape_reason: Option<PublicScoutShapeRejectReason>,
) -> String {
    match reason {
        R1ProofFilterRejectReason::NoQuote => "no_quote".to_string(),
        R1ProofFilterRejectReason::NoPositiveEv => "no_positive_ev".to_string(),
        R1ProofFilterRejectReason::NoShadowGuard => "no_shadow_guard".to_string(),
        R1ProofFilterRejectReason::PublicScoutShape => format!(
            "public_scout_shape_{}",
            encode_public_scout_shape_reject_reason(
                public_scout_shape_reason.unwrap_or(PublicScoutShapeRejectReason::Other)
            )
        ),
        R1ProofFilterRejectReason::Other => "other".to_string(),
    }
}

fn encode_run39_micro_market_result(reason: R1DropReason) -> &'static str {
    match reason {
        R1DropReason::MicroMarket => "no_uplift",
        R1DropReason::RetainedEvFloor => "below_floor",
        R1DropReason::NetAfterFeeFloor => "negative_ev",
        _ => "not_evaluated",
    }
}

fn encode_run39_r1_outcome(outcome: R1AutoAdmissionOutcome) -> &'static str {
    match outcome {
        R1AutoAdmissionOutcome::Admitted => "admitted",
        R1AutoAdmissionOutcome::Dropped(reason) => encode_r1_drop_reason(reason),
        R1AutoAdmissionOutcome::ProofFilterDrop => "proof_filter",
        R1AutoAdmissionOutcome::TemplateExecutabilityDrop => "template_executability",
        R1AutoAdmissionOutcome::AttemptLatchDrop => "attempt_latch",
    }
}

fn trace_run39_broad_surface_observation(
    shared: &SharedRefs<'_>,
    record: &IngressRecord,
    route: &HydratedRoute,
    intent: &WorkerIntent,
    input_account_status: &str,
    output_account_status: &str,
    proof_filter_result: &str,
    micro_market_result: &str,
    template_executability_result: &str,
    net_after_fee_lamports: u64,
    outcome: R1AutoAdmissionOutcome,
) {
    if !run39_broad_surface_enabled(shared.rollout_no_send_backend) {
        return;
    }

    let source = encode_ingress_signal_source(record.signal_source);
    let venue = encode_ingress_venue(record.venue_id);
    let observation = Run39BroadSurfaceObservation {
        record_type: "run39_broad_surface",
        unix_ns: record.unix_ns,
        slot: record.slot,
        signature: bs58::encode(record.signature).into_string(),
        source: if source.is_empty() {
            format!("source_{}", record.signal_source)
        } else {
            source.to_string()
        },
        venue: if venue.is_empty() {
            format!("venue_{}", record.venue_id)
        } else {
            venue.to_string()
        },
        route: encode_route_decision(route.outcome.decision),
        route_reason: encode_route_reason(route.outcome.reason),
        pool: bs58::encode(record.pool_pubkey).into_string(),
        mint_in: bs58::encode(record.mint_in).into_string(),
        mint_out: bs58::encode(record.mint_out).into_string(),
        trade_size_lamports: intent.amount,
        retained_ev_lamports: intent.pre_tip_retained_lcb_lamports,
        net_after_fee_lamports,
        input_account_status: input_account_status.to_string(),
        output_account_status: output_account_status.to_string(),
        proof_filter_result: proof_filter_result.to_string(),
        micro_market_result: micro_market_result.to_string(),
        template_executability_result: template_executability_result.to_string(),
        would_admit: matches!(outcome, R1AutoAdmissionOutcome::Admitted),
        r1_outcome: encode_run39_r1_outcome(outcome),
    };

    if let Ok(json) = serde_json::to_string(&observation) {
        println!("RUN39_BROAD_SURFACE {}", json);
    }
}

#[inline(always)]
fn r1_auto_admission_admits(
    shared: &SharedRefs<'_>,
    record: &IngressRecord,
    resolved: &ResolvedRecord,
    route: &HydratedRoute,
    intent: &WorkerIntent,
    jito_lut_bank: Option<&shadow_core::policy::TipLut>,
    harmonic_lut_bank: Option<&shadow_core::policy::TipLut>,
) -> R1AutoAdmissionOutcome {
    if shared.r1_live_admission.mode != shadow_core::config::R1LiveAdmissionMode::AutoPrivateGrade {
        return R1AutoAdmissionOutcome::Admitted;
    }

    WORKER_R1_AUTO_ADMISSION_ATTEMPT.fetch_add(1, Ordering::Relaxed);
    if record.signal_source == SIGNAL_SOURCE_AFXDP {
        WORKER_R1_AFXDP_PRIVATE_GRADE_AUTO_ADMISSION_ATTEMPT.fetch_add(1, Ordering::Relaxed);
    }
    record_run38_target_r1_attempt(record, route.outcome.decision);
    let gate = R1TinyAutoAdmissionGate::new(shared.r1_live_admission);
    let health_ok = shared
        .health
        .payload()
        .read_active()
        .map(|health| health.state_is_healthy != 0)
        .unwrap_or(false);
    let mut candidate = R1CandidateContext {
        signal_source: record.signal_source,
        private_grade: is_private_packet_signal(record.signal_source),
        route_decision: route.outcome.decision,
        shadow_guard_template_ok: shadow_guard_template_configured(shared),
        micro_market_uplift_ok: has_active_lut_for_route(
            route.outcome.decision,
            jito_lut_bank.is_some(),
            harmonic_lut_bank.is_some(),
        ),
        egress_admissible: route.outcome.decision != RouteDecision::Drop,
        trade_size_lamports: intent.amount,
        retained_ev_lamports: intent.pre_tip_retained_lcb_lamports,
        net_after_fee_lamports: preview_policy_fee_state(&PolicyFeePreviewInput {
            route_decision: route.outcome.decision,
            alpha_bucket: intent.alpha_bucket,
            obscurity_score: intent.obscurity_score,
            leader_class_id: route.leader_class_id.unwrap_or(0),
            alpha_lcb_lamports: intent.alpha_lcb_lamports,
            pre_tip_retained_lcb_lamports: intent.pre_tip_retained_lcb_lamports,
            cu_price_reciprocal_q32: intent.cu_price_reciprocal_q32,
            jito_lut_bank,
            harmonic_lut_bank,
        })
        .map(|preview| {
            preview
                .retained_lcb_lamports
                .saturating_sub(SOLANA_BASE_TX_FEE_LAMPORTS)
        })
        .unwrap_or(0),
        stale_state: false,
    };
    let state = R1WorkerState {
        health_ok,
        current_notional_lamports: shared.inventory_alloc.load(Ordering::Relaxed),
    };
    let _scorecard_replay_source_override_applied =
        apply_run40_scorecard_replay_source_override(shared, record, route, &mut candidate);
    let proof_filter_required = require_target_public_scout_enabled()
        || require_any_public_scout_enabled()
        || route.outcome.decision == RouteDecision::PublicRpcScout;
    let mut input_account_status = if route.outcome.decision == RouteDecision::PublicRpcScout
        && record.venue_id == ingest_venue::RAYDIUM_CLMM
    {
        "not_evaluated".to_string()
    } else {
        "not_applicable".to_string()
    };
    let mut output_account_status = if route.outcome.decision == RouteDecision::PublicRpcScout
        && record.venue_id == ingest_venue::RAYDIUM_CLMM
    {
        "not_evaluated".to_string()
    } else {
        "not_applicable".to_string()
    };
    let mut proof_filter_result = if proof_filter_required {
        "not_evaluated".to_string()
    } else {
        "not_applicable".to_string()
    };
    let mut micro_market_result = "not_evaluated".to_string();
    let mut template_executability_result = if route.outcome.decision
        == RouteDecision::PublicRpcScout
        && record.venue_id == ingest_venue::RAYDIUM_CLMM
    {
        "not_evaluated".to_string()
    } else {
        "not_applicable".to_string()
    };

    let outcome = match gate.evaluate(&candidate, &state) {
        R1AdmissionDecision::Admit { .. } => {
            micro_market_result = "passed".to_string();
            if proof_filter_required {
                if let Some(reason) = public_scout_proof_filter_reject_reason(record) {
                    let public_scout_shape_reason =
                        if matches!(reason, R1ProofFilterRejectReason::PublicScoutShape) {
                            Some(classify_public_scout_shape_reject_from_filter(
                                record, route,
                            ))
                        } else {
                            None
                        };
                    proof_filter_result =
                        encode_run39_proof_filter_result(reason, public_scout_shape_reason);
                    record_r1_auto_admission_reject(
                        record,
                        R1AutoAdmissionRejectReason::ProofFilter,
                    );
                    record_run38_target_r1_reject(
                        record,
                        route.outcome.decision,
                        R1AutoAdmissionRejectReason::ProofFilter,
                    );
                    record_r1_auto_admission_proof_filter_breakdown(reason);
                    if matches!(reason, R1ProofFilterRejectReason::PublicScoutShape) {
                        record_public_scout_shape_reject(
                            record,
                            route.outcome.decision,
                            public_scout_shape_reason
                                .unwrap_or(PublicScoutShapeRejectReason::Other),
                        );
                    }
                    R1AutoAdmissionOutcome::ProofFilterDrop
                } else {
                    proof_filter_result = "passed".to_string();
                    if route.outcome.decision == RouteDecision::PublicRpcScout {
                        if record.venue_id == ingest_venue::RAYDIUM_CLMM {
                            let input_check = match clmm_public_scout_input_token_account(
                                shared, record, resolved, intent, "deferred",
                            ) {
                                Ok(input_check) => {
                                    input_account_status = "ok".to_string();
                                    Some(input_check)
                                }
                                Err(failure) => {
                                    input_account_status = failure.input_status().to_string();
                                    if failure.blocks_r1_inventory_gate() {
                                        record_r1_auto_admission_drop(R1DropReason::Inventory);
                                        record_r1_auto_admission_reject(
                                            record,
                                            R1AutoAdmissionRejectReason::Inventory,
                                        );
                                        record_run38_target_r1_reject(
                                            record,
                                            route.outcome.decision,
                                            R1AutoAdmissionRejectReason::Inventory,
                                        );
                                        record_run38_target_inventory_reject(
                                            record,
                                            route.outcome.decision,
                                            failure,
                                        );
                                        None
                                    } else {
                                        None
                                    }
                                }
                            };
                            if input_account_status != "ok"
                                && input_account_status != "mint_state_missing"
                            {
                                R1AutoAdmissionOutcome::Dropped(R1DropReason::Inventory)
                            } else {
                                let template_gate_outcome = if let Some(input_check) = input_check {
                                    match clmm_public_scout_output_token_account(
                                        shared,
                                        record,
                                        resolved,
                                        intent,
                                        input_check.input_token_account_pubkey,
                                        "ok",
                                    ) {
                                        Ok(_) => {
                                            output_account_status = "ok".to_string();
                                            template_executability_result = "passed".to_string();
                                            None
                                        }
                                        Err(failure) => {
                                            output_account_status =
                                                failure.output_status().to_string();
                                            template_executability_result =
                                                failure.output_status().to_string();
                                            if failure.blocks_r1_output_gate() {
                                                record_r1_template_executability_reject(
                                                    record,
                                                    route.outcome.decision,
                                                    failure,
                                                );
                                                Some(R1AutoAdmissionOutcome::TemplateExecutabilityDrop)
                                            } else {
                                                None
                                            }
                                        }
                                    }
                                } else {
                                    None
                                };
                                if let Some(outcome) = template_gate_outcome {
                                    outcome
                                } else if !reserve_public_scout_attempt(record.signature) {
                                    record_r1_auto_admission_reject(
                                        record,
                                        R1AutoAdmissionRejectReason::AttemptLatch,
                                    );
                                    record_run38_target_r1_reject(
                                        record,
                                        route.outcome.decision,
                                        R1AutoAdmissionRejectReason::AttemptLatch,
                                    );
                                    R1AutoAdmissionOutcome::AttemptLatchDrop
                                } else {
                                    WORKER_R1_AUTO_ADMISSION_ADMIT.fetch_add(1, Ordering::Relaxed);
                                    if record.signal_source == SIGNAL_SOURCE_AFXDP {
                                        WORKER_R1_AFXDP_PRIVATE_GRADE_AUTO_ADMISSION_ADMIT
                                            .fetch_add(1, Ordering::Relaxed);
                                    }
                                    record_run38_target_r1_admit(record, route.outcome.decision);
                                    R1AutoAdmissionOutcome::Admitted
                                }
                            }
                        } else if !reserve_public_scout_attempt(record.signature) {
                            record_r1_auto_admission_reject(
                                record,
                                R1AutoAdmissionRejectReason::AttemptLatch,
                            );
                            record_run38_target_r1_reject(
                                record,
                                route.outcome.decision,
                                R1AutoAdmissionRejectReason::AttemptLatch,
                            );
                            R1AutoAdmissionOutcome::AttemptLatchDrop
                        } else {
                            WORKER_R1_AUTO_ADMISSION_ADMIT.fetch_add(1, Ordering::Relaxed);
                            if record.signal_source == SIGNAL_SOURCE_AFXDP {
                                WORKER_R1_AFXDP_PRIVATE_GRADE_AUTO_ADMISSION_ADMIT
                                    .fetch_add(1, Ordering::Relaxed);
                            }
                            record_run38_target_r1_admit(record, route.outcome.decision);
                            R1AutoAdmissionOutcome::Admitted
                        }
                    } else {
                        WORKER_R1_AUTO_ADMISSION_ADMIT.fetch_add(1, Ordering::Relaxed);
                        if record.signal_source == SIGNAL_SOURCE_AFXDP {
                            WORKER_R1_AFXDP_PRIVATE_GRADE_AUTO_ADMISSION_ADMIT
                                .fetch_add(1, Ordering::Relaxed);
                        }
                        record_run38_target_r1_admit(record, route.outcome.decision);
                        R1AutoAdmissionOutcome::Admitted
                    }
                }
            } else {
                WORKER_R1_AUTO_ADMISSION_ADMIT.fetch_add(1, Ordering::Relaxed);
                if record.signal_source == SIGNAL_SOURCE_AFXDP {
                    WORKER_R1_AFXDP_PRIVATE_GRADE_AUTO_ADMISSION_ADMIT
                        .fetch_add(1, Ordering::Relaxed);
                }
                record_run38_target_r1_admit(record, route.outcome.decision);
                R1AutoAdmissionOutcome::Admitted
            }
        }
        R1AdmissionDecision::Drop { reason_code } => {
            micro_market_result = encode_run39_micro_market_result(reason_code).to_string();
            let reject_reason = r1_auto_admission_reject_reason_from_drop(reason_code);
            record_r1_auto_admission_drop(reason_code);
            if matches!(reject_reason, R1AutoAdmissionRejectReason::MicroMarket) {
                record_r1_auto_admission_micro_market_breakdown_from_drop(reason_code);
            }
            record_r1_auto_admission_reject(record, reject_reason);
            record_run38_target_r1_reject(record, route.outcome.decision, reject_reason);
            R1AutoAdmissionOutcome::Dropped(reason_code)
        }
    };
    trace_run39_broad_surface_observation(
        shared,
        record,
        route,
        intent,
        &input_account_status,
        &output_account_status,
        &proof_filter_result,
        &micro_market_result,
        &template_executability_result,
        candidate.net_after_fee_lamports,
        outcome,
    );
    outcome
}

#[inline(always)]
fn r1_auto_admission_blocks_process_intent(
    rollout_no_send_backend: bool,
    outcome: R1AutoAdmissionOutcome,
) -> bool {
    !rollout_no_send_backend && !matches!(outcome, R1AutoAdmissionOutcome::Admitted)
}

#[inline(always)]
fn r1_auto_admission_admitted(outcome: R1AutoAdmissionOutcome) -> bool {
    matches!(outcome, R1AutoAdmissionOutcome::Admitted)
}

#[inline(always)]
fn geyser_shadow_no_send_allowed(
    shared: &SharedRefs<'_>,
    record: &IngressRecord,
    route: &HydratedRoute,
) -> bool {
    route.outcome.decision == RouteDecision::Drop
        && route.outcome.reason == RouteReason::PublicTarget
        && is_observe_shadow_geyser_signal(record.signal_source)
        && shared.r0_allow_geyser_observe_shadow
        && shared.rollout_no_send_backend
        && shared.rollout_shadow_sink.is_some()
        && !shadow_core::routing::public_execution_reachable()
}

#[inline(always)]
fn shadow_no_send_route_from_public_drop(route: &HydratedRoute) -> HydratedRoute {
    let mut shadow_route = route.clone();
    shadow_route.ctx.signal_source = SignalSource::PrivateMempool;
    shadow_route.ctx.jito_compatible_now = true;
    shadow_route.ctx.timing_margin_ok = true;
    shadow_route.outcome = RouteOutcome {
        decision: RouteDecision::JitoBundle,
        reason: RouteReason::JitoDirect,
    };
    shadow_route
}

#[inline(always)]
fn set_intent_lookup_staleness_ns(intent: &mut WorkerIntent, max_staleness_ns: u64) {
    intent.max_pool_staleness_ns = max_staleness_ns;
    intent.max_mint_staleness_ns = max_staleness_ns;
    intent.max_alt_staleness_ns = max_staleness_ns;
}

#[inline(always)]
fn apply_route_intent_overrides(
    intent: &mut WorkerIntent,
    record: &IngressRecord,
    route: &HydratedRoute,
    rollout_no_send_backend: bool,
) {
    if route.outcome.decision == RouteDecision::PublicRpcScout {
        set_intent_lookup_staleness_ns(intent, PUBLIC_RPC_SCOUT_MAX_STALENESS_NS);
    }

    if is_observe_shadow_geyser_signal(record.signal_source)
        && route.ctx.signal_source == SignalSource::PrivateMempool
        && rollout_no_send_backend
    {
        intent.source = SignalSource::PrivateMempool;
        set_intent_lookup_staleness_ns(intent, GEYSER_SHADOW_NO_SEND_MAX_STALENESS_NS);
    }
}

enum HydratedRouteOutcome {
    Actionable(HydratedRoute),
    Dropped(HydratedRoute),
    UnavailableUnknownSignal,
    UnavailableHydrationNone,
}

/// Call [`derive_route_inputs_guerrila`] using the pre-opened shared segments and
/// preserve route-level drop reasons for G12 telemetry.
#[inline]
fn hydrate_route_observed(
    record: &IngressRecord,
    intent_kind: IntentKind,
    harmonic_tactic_class: Option<u16>,
    jito_compatible_now: bool,
    timing_margin_ok: bool,
    shared: &SharedRefs<'_>,
) -> HydratedRouteOutcome {
    let signal = match signal_source_from_u8(record.signal_source) {
        Some(signal) => signal,
        None => return HydratedRouteOutcome::UnavailableUnknownSignal,
    };

    let route = match derive_route_inputs_guerrila(
        signal,
        record.slot,
        intent_kind,
        harmonic_tactic_class,
        jito_compatible_now,
        timing_margin_ok,
        shared.blockhash.payload(),
        shared.leader_schedule.payload(),
        shared.risk_flags.payload(),
        shared.health.payload(),
        shared.egress_health.payload(),
        shared.routing_cfg,
    ) {
        Some(route) => route,
        None => return HydratedRouteOutcome::UnavailableHydrationNone,
    };

    if route.outcome.decision == RouteDecision::Drop {
        return HydratedRouteOutcome::Dropped(route);
    }

    HydratedRouteOutcome::Actionable(route)
}

#[inline]
fn hydrate_route(
    record: &IngressRecord,
    intent_kind: IntentKind,
    harmonic_tactic_class: Option<u16>,
    jito_compatible_now: bool,
    timing_margin_ok: bool,
    shared: &SharedRefs<'_>,
) -> Option<HydratedRoute> {
    match hydrate_route_observed(
        record,
        intent_kind,
        harmonic_tactic_class,
        jito_compatible_now,
        timing_margin_ok,
        shared,
    ) {
        HydratedRouteOutcome::Actionable(route) => Some(route),
        HydratedRouteOutcome::Dropped(_)
        | HydratedRouteOutcome::UnavailableUnknownSignal
        | HydratedRouteOutcome::UnavailableHydrationNone => None,
    }
}

/// Run the early-drop gate sequence on a single [`IngressRecord`].
///
/// Returns `Some(ResolvedRecord)` if the record passes all gates, `None` if
/// it should be dropped.  Every gate is O(1) with no allocation.
///
/// **Gate order:**
/// 1. Health — drop if unhealthy or torn read.
/// 2. Slot staleness — drop if `record.slot + MAX_SLOT_AGE < snapshot_slot`.
/// 3. Pool tag-map — `find_by_hash40` → drop on miss.
/// 4. Pool arena — seqlock `read_active` → drop on torn/None/pubkey mismatch.
/// 5. Mint-in tag-map — drop on miss.
/// 6. Mint-out tag-map — drop on miss.
#[inline]
fn run_early_drop_gates(
    worker_id: u32,
    record: &IngressRecord,
    shared: &SharedRefs<'_>,
) -> Option<ResolvedRecord> {
    // Gate 2: health.
    let health = match shared.health.payload().read_active() {
        Some(health) => health,
        None => {
            WORKER_HEALTH_SNAPSHOT_MISSING.fetch_add(1, Ordering::Relaxed);
            return None;
        }
    };
    if health.state_is_healthy == 0 {
        WORKER_HEALTH_DROPS.fetch_add(1, Ordering::Relaxed);
        record_dpdk_worker_counter(record.signal_source, &DPDK_WORKER_HEALTH_DROPS);
        return None;
    }

    // Gate 3: slot staleness.
    let snapshot_slot = health.snapshot_slot;
    let sh8_local_replay_stale_bypass = shared.sh8_afxdp_allow_local_replay_stale_slots
        && record.signal_source == SIGNAL_SOURCE_AFXDP;
    let run40_scorecard_replay_stale_bypass = record.slot.saturating_add(MAX_SLOT_AGE)
        < snapshot_slot
        && apply_run40_scorecard_replay_stale_slot_bypass(shared, record, snapshot_slot);
    if record.slot.saturating_add(MAX_SLOT_AGE) < snapshot_slot
        && !sh8_local_replay_stale_bypass
        && !run40_scorecard_replay_stale_bypass
    {
        WORKER_STALE_SLOT_DROPS.fetch_add(1, Ordering::Relaxed);
        record_dpdk_worker_counter(record.signal_source, &DPDK_WORKER_STALE_SLOT_DROPS);
        return None;
    }

    // Gate 4: pool tag-map lookup.
    let pool_index = match shared.pool_tag_map.find_by_hash40(&record.pool_pubkey) {
        Some(index) => index,
        None => {
            trace_run40_scorecard_replay_gate(record, "pool_tag_miss", "after_stale_bypass");
            record_pool_state_miss(
                worker_id,
                record,
                snapshot_slot,
                PoolStateMissReason::TagMapAbsent,
            );
            return None;
        }
    };

    // Gate 5: pool arena read + pubkey verification.
    let pool_elems = shared.pool_arena.elements();
    if (pool_index as usize) >= pool_elems.len() {
        trace_run40_scorecard_replay_gate(record, "pool_arena_oob", "after_pool_tag_hit");
        record_pool_state_miss(
            worker_id,
            record,
            snapshot_slot,
            PoolStateMissReason::ArenaIndexOob,
        );
        return None;
    }
    let pool_payload = match pool_elems[pool_index as usize].read_active() {
        Some(payload) => payload,
        None => {
            trace_run40_scorecard_replay_gate(record, "pool_arena_torn", "after_pool_tag_hit");
            record_pool_state_miss(
                worker_id,
                record,
                snapshot_slot,
                PoolStateMissReason::ArenaTorn,
            );
            return None;
        }
    };
    if pool_payload.pool_pubkey != record.pool_pubkey {
        // Hash collision — fail closed.
        trace_run40_scorecard_replay_gate(record, "pool_pubkey_mismatch", "after_pool_arena_read");
        record_pool_state_miss(
            worker_id,
            record,
            snapshot_slot,
            PoolStateMissReason::PubkeyMismatch,
        );
        return None;
    }

    let zero_mint_fallback = shared.rollout_no_send_backend
        && record.mint_in == [0u8; 32]
        && record.mint_out == [0u8; 32];

    let (mint_in_index, mint_out_index) = if zero_mint_fallback {
        // Observe-only/no-send may deliberately carry zeroed mint pubkeys from the
        // lenient ingest-side fallback so the worker can still publish a truthful
        // drop-path rollout shadow event instead of disappearing before PM sees it.
        (OBSERVE_ONLY_ZERO_MINT_INDEX, OBSERVE_ONLY_ZERO_MINT_INDEX)
    } else {
        // Gate 6: mint-in tag-map lookup.
        let mint_in_index = match shared.mint_tag_map.find_by_hash40(&record.mint_in) {
            Some(index) => index,
            None => {
                trace_run40_scorecard_replay_gate(
                    record,
                    "mint_in_tag_miss",
                    "after_pool_state_hit",
                );
                WORKER_EARLY_DROP_MINT_IN_TAG_MISSING.fetch_add(1, Ordering::Relaxed);
                return None;
            }
        };

        // Gate 7: mint-out tag-map lookup.
        let mint_out_index = match shared.mint_tag_map.find_by_hash40(&record.mint_out) {
            Some(index) => index,
            None => {
                trace_run40_scorecard_replay_gate(
                    record,
                    "mint_out_tag_miss",
                    "after_mint_in_tag_hit",
                );
                WORKER_EARLY_DROP_MINT_OUT_TAG_MISSING.fetch_add(1, Ordering::Relaxed);
                return None;
            }
        };

        trace_run40_scorecard_replay_gate(record, "resolved_record", "after_mint_tag_hits");
        WORKER_POOL_STATE_HIT.fetch_add(1, Ordering::Relaxed);
        record_dpdk_worker_counter(record.signal_source, &DPDK_WORKER_POOL_STATE_HIT);
        (mint_in_index, mint_out_index)
    };

    Some(ResolvedRecord {
        pool_index,
        mint_in_index,
        mint_out_index,
        reserve_in: pool_payload.reserve_in,
        reserve_out: pool_payload.reserve_out,
        snapshot_slot,
    })
}

#[inline]
fn read_opso_metadata(
    record_unix_ns: u64,
    pool_index: u32,
    sidecar: Option<&MappedSegment<OpsShockSidecarSnapshot>>,
    stale_action: shadow_core::config::OpsoStaleAction,
    max_staleness_ns: u64,
) -> OpsoObserveOnlyMetadata {
    let sidecar_state = match sidecar {
        Some(seg) => match seg.payload().read_active() {
            Some(payload)
                if (payload.pool_index == 0 || payload.pool_index == pool_index)
                    && !payload.is_stale(record_unix_ns, max_staleness_ns) =>
            {
                OpsoSidecarState::Fresh(payload)
            }
            Some(_) => OpsoSidecarState::Stale,
            None => OpsoSidecarState::Missing,
        },
        None => OpsoSidecarState::Missing,
    };
    decide_observe_only_metadata(sidecar_state, stale_action)
}

/// Build a [`WorkerIntent`] from an ingress record, resolved arena state,
/// and hydrated route.
///
/// Maps wire-level fields to pipeline-level fields with conservative defaults
/// for fields not carried on the ingress record.  The intent is consumed by
/// [`process_intent`] which chains quote → policy → build → sign → egress.
#[inline]
fn build_worker_intent(
    record: &IngressRecord,
    resolved: &ResolvedRecord,
    route: &HydratedRoute,
    route_base_cu_limit: u32,
    shape: &IntentShapeConfig,
    r1_live_admission: R1LiveAdmissionRuntimeConfig,
    opso_metadata: OpsoObserveOnlyMetadata,
) -> WorkerIntent {
    let source =
        signal_source_from_u8(record.signal_source).unwrap_or(SignalSource::PrivateMempool);
    let deployed_amount =
        if r1_live_admission.mode == shadow_core::config::R1LiveAdmissionMode::AutoPrivateGrade {
            record
                .amount_in
                .min(r1_live_admission.max_live_trade_input_lamports)
        } else {
            record.amount_in
        };

    // Deadline: 400ms from ingress timestamp (one slot budget).
    let deadline_unix_ns = record.unix_ns.saturating_add(400_000_000);

    // Conservative alpha estimate: backrun captures ~fee_fraction of the victim swap.
    let trade_fee_num: u64 = 25; // Raydium V4 default: 25/10000 = 0.25%
    let trade_fee_denom: u64 = 10000;
    let alpha_lcb =
        record.amount_in.checked_mul(trade_fee_num).unwrap_or(0) / trade_fee_denom.max(1);

    // Alpha bucket: 6-bit (0..63) for LUT column indexing.
    let alpha_bucket = (alpha_lcb / 1_000_000).min(63) as u16;

    // CU price reciprocal Q32: (1_000_000 << 32) / cu_limit.
    let cu_price_reciprocal_q32 = if route_base_cu_limit > 0 {
        (1_000_000u64 << 32) / route_base_cu_limit as u64
    } else {
        0
    };

    // Intent classification via canonical target-filter policy.
    let notional_sol = deployed_amount as f64 / 1_000_000_000.0;
    let cap_sol = shape.max_live_trade_input_lamports as f64 / 1_000_000_000.0;
    let target_decision = shadow_core::target_filter::evaluate_target(
        notional_sol,
        0.0,      // entity_exposure_sol: not tracked per-worker (oracle-level concern)
        cap_sol,  // per-mint cap: use retail cap (conservative default)
        f64::MAX, // entity cap: no per-entity limit at worker level
        cap_sol,  // retail cap
        shape.allow_clamped_apex_partials,
        false, // is_atba: ATBA classification is separate (CLMM sidecar not yet wired)
        shape.allow_atba_jito_only,
    );
    let (kind, apex_lamports) = match target_decision {
        shadow_core::target_filter::TargetDecision::PlainWithinCap => {
            (IntentKind::PlainWithinCap, 0)
        }
        shadow_core::target_filter::TargetDecision::ApexPartial { deployed_lamports } => {
            (IntentKind::ApexPartial, deployed_lamports)
        }
        shadow_core::target_filter::TargetDecision::Drop { .. } => (IntentKind::OverCap, 0),
    };

    WorkerIntent {
        kind,
        amount: deployed_amount,
        source,
        signal_source: record.signal_source,
        expected_pool_pubkey: record.pool_pubkey,
        expected_mint_in_pubkey: record.mint_in,
        expected_mint_out_pubkey: record.mint_out,
        target_gross_amount_in: record.amount_in,
        dist_to_tick_lamports: None,
        obscurity_score: record.obscurity_score as u16,
        tactic_class: route.leader_class_id,
        direction: 0, // BuyOut default — Guerrila primary direction
        pool_index: resolved.pool_index,
        observe_only: true, // Guerrila spec: start in observe-only, promote to live after warm-up
        alpha_bucket,
        venue_id: record.venue_id,
        pre_tip_retained_lcb_lamports: alpha_lcb,
        min_net_after_fee_lamports: r1_live_admission.min_net_after_fee_lamports,
        min_incremental_retained_lcb_lamports: 5_000_000, // Guerrila spec: 5M lamports (0.005 SOL)
        cu_price_reciprocal_q32,
        jito_compatible_now: route_uses_jito_lane(route.outcome.decision),
        timing_margin_ok: true,
        published_apex_partial_lamports: apex_lamports,
        slip_bps: 100, // 1% default slippage budget
        alpha_lcb_lamports: alpha_lcb,
        deadline_unix_ns,
        ingress_unix_ns: record.unix_ns,
        max_pool_staleness_ns: DEFAULT_WORKER_MAX_STALENESS_NS, // 10s
        max_mint_staleness_ns: DEFAULT_WORKER_MAX_STALENESS_NS,
        max_alt_staleness_ns: DEFAULT_WORKER_MAX_STALENESS_NS,
        trade_fee_num,
        trade_fee_denom,
        opso_episode_id_mod: opso_metadata.episode_id_mod,
        opso_owner_mode: opso_metadata.owner_mode.as_u8(),
        opso_fallback_mode: opso_metadata.fallback_mode.as_u8(),
        opso_reason_code: opso_metadata.reason_code as u8,
        opso_bid_ceiling_bucket: opso_metadata.bid_ceiling_bucket,
        opso_fallback_value_bucket: opso_metadata.fallback_value_bucket,
        opso_backrun_value_bucket: opso_metadata.backrun_value_bucket,
    }
}

#[inline(always)]
fn clmm_exact_quote_matches_request(
    snapshot: shadow_ipc::clmm_exact_quote_sidecar::ClmmExactQuotePayload192B,
    request: &ClmmExactQuoteRequestPayload128B,
    intent: &WorkerIntent,
) -> bool {
    let is_valid = snapshot.validity_flags & CLMM_EXACT_QUOTE_FLAG_VALID != 0;
    let is_no_quote = snapshot.validity_flags & CLMM_EXACT_QUOTE_FLAG_NO_QUOTE != 0;
    (is_valid || is_no_quote)
        && snapshot.pool_pubkey == request.pool_pubkey
        && snapshot.mint_in_pubkey == request.mint_in_pubkey
        && snapshot.mint_out_pubkey == request.mint_out_pubkey
        && snapshot.amount_in == request.amount_in
        && snapshot.direction == request.direction
        && snapshot.request_id() == request.request_id()
        && snapshot.last_update_unix_ns >= request.request_unix_ns
        && intent
            .ingress_unix_ns
            .saturating_sub(snapshot.last_update_unix_ns)
            <= intent.max_pool_staleness_ns
        && (!is_valid
            || (snapshot.expected_out != 0
                && snapshot.min_out != 0
                && snapshot.min_out <= snapshot.expected_out))
}

#[inline(always)]
fn max_seen_clmm_exact_quote_request_id(
    request_arena: &MappedClmmExactQuoteRequestArena,
    quote_arena: Option<&MappedClmmExactQuoteArena>,
    pool_index: u32,
) -> u32 {
    let request_max = request_arena
        .read_stable_with_sequences_at(pool_index)
        .into_iter()
        .flatten()
        .map(|(_, payload)| payload.request_id())
        .max()
        .unwrap_or(0);
    let quote_max = quote_arena
        .map(|arena| {
            arena
                .read_stable_with_sequences_at(pool_index)
                .into_iter()
                .flatten()
                .map(|(_, payload)| payload.request_id())
                .max()
                .unwrap_or(0)
        })
        .unwrap_or(0);
    request_max.max(quote_max)
}

#[inline(always)]
fn allocate_clmm_exact_quote_request_id(
    request_arena: &MappedClmmExactQuoteRequestArena,
    quote_arena: Option<&MappedClmmExactQuoteArena>,
    pool_index: u32,
) -> u32 {
    let observed_floor =
        max_seen_clmm_exact_quote_request_id(request_arena, quote_arena, pool_index)
            .saturating_add(1)
            .max(1);
    let previous = CLMM_EXACT_QUOTE_REQUEST_ID_CURSOR
        .fetch_update(Ordering::AcqRel, Ordering::Acquire, |current| {
            let next = current.max(1).max(observed_floor);
            Some(next.saturating_add(1).max(1))
        })
        .unwrap_or_else(|current| current);
    previous.max(1).max(observed_floor)
}

#[inline(always)]
fn prime_clmm_exact_quote_request(
    request_arena: Option<&MappedClmmExactQuoteRequestArena>,
    ready_ring: Option<&MappedSpscRing<ClmmExactQuoteReadyIndex64B>>,
    quote_arena: Option<&MappedClmmExactQuoteArena>,
    intent: &WorkerIntent,
    wait_budget_ms: u64,
) -> ClmmExactQuotePrimeResult {
    if intent.venue_id != ingest_venue::RAYDIUM_CLMM {
        return ClmmExactQuotePrimeResult {
            outcome: ClmmExactQuotePrimeOutcome::NotClmm,
            request_amount_in: 0,
            request_id: 0,
            publish_ok_unix_ns: 0,
            timeout_diag: None,
        };
    }
    let Some(request_arena) = request_arena else {
        return ClmmExactQuotePrimeResult {
            outcome: ClmmExactQuotePrimeOutcome::RequestArenaMissing,
            request_amount_in: 0,
            request_id: 0,
            publish_ok_unix_ns: 0,
            timeout_diag: None,
        };
    };
    let Ok(amount_in) = preview_trade_size_for_intent(intent) else {
        return ClmmExactQuotePrimeResult {
            outcome: ClmmExactQuotePrimeOutcome::AmountPreviewFailed,
            request_amount_in: 0,
            request_id: 0,
            publish_ok_unix_ns: 0,
            timeout_diag: None,
        };
    };

    let (previous_sequence, previous_request_id) = request_arena
        .read_active_with_sequence_at(intent.pool_index)
        .map(|(sequence, payload)| (sequence, payload.request_id()))
        .unwrap_or((0, 0));
    let request_capacity = request_arena.capacity();
    if let Some(slot) = clmm_exact_quote_outstanding_slot(request_capacity, intent.pool_index) {
        let outstanding_request_id = slot.load(Ordering::Acquire);
        if outstanding_request_id != 0 {
            record_clmm_exact_quote_request_outstanding_same_pool_hit();
            record_clmm_exact_quote_request_suppressed_outstanding_same_pool();
            set_last_clmm_exact_quote_request_slot(
                previous_request_id,
                previous_sequence,
                intent.pool_index,
            );
            trace_clmm_exact_quote_request_slot_publish(
                intent,
                outstanding_request_id,
                amount_in,
                previous_request_id,
                previous_sequence,
                false,
                "suppressed_outstanding_same_pool",
            );
            return ClmmExactQuotePrimeResult {
                outcome: ClmmExactQuotePrimeOutcome::OutstandingSamePool,
                request_amount_in: amount_in,
                request_id: outstanding_request_id,
                publish_ok_unix_ns: 0,
                timeout_diag: None,
            };
        }
    }
    let request_id =
        allocate_clmm_exact_quote_request_id(request_arena, quote_arena, intent.pool_index);
    if let Err(outstanding_request_id) = try_claim_clmm_exact_quote_outstanding_request(
        request_capacity,
        intent.pool_index,
        request_id,
    ) {
        record_clmm_exact_quote_request_outstanding_same_pool_hit();
        record_clmm_exact_quote_request_suppressed_outstanding_same_pool();
        set_last_clmm_exact_quote_request_slot(
            previous_request_id,
            previous_sequence,
            intent.pool_index,
        );
        trace_clmm_exact_quote_request_slot_publish(
            intent,
            if outstanding_request_id == 0 {
                request_id
            } else {
                outstanding_request_id
            },
            amount_in,
            previous_request_id,
            previous_sequence,
            false,
            "suppressed_outstanding_same_pool",
        );
        return ClmmExactQuotePrimeResult {
            outcome: ClmmExactQuotePrimeOutcome::OutstandingSamePool,
            request_amount_in: amount_in,
            request_id: if outstanding_request_id == 0 {
                request_id
            } else {
                outstanding_request_id
            },
            publish_ok_unix_ns: 0,
            timeout_diag: None,
        };
    }
    let mut request = ClmmExactQuoteRequestPayload128B {
        pool_pubkey: intent.expected_pool_pubkey,
        mint_in_pubkey: intent.expected_mint_in_pubkey,
        mint_out_pubkey: intent.expected_mint_out_pubkey,
        target_amount_in: intent.target_gross_amount_in,
        amount_in,
        request_unix_ns: intent.ingress_unix_ns,
        slip_bps: intent.slip_bps,
        direction: intent.direction,
        validity_flags: CLMM_EXACT_QUOTE_REQUEST_FLAG_VALID,
        reserved: [0; 4],
    };
    request.set_request_id(request_id);
    set_last_clmm_exact_quote_request_slot(
        previous_request_id,
        previous_sequence,
        intent.pool_index,
    );
    record_clmm_exact_quote_request_publish_attempt();
    if request_arena
        .publish_at(intent.pool_index, request)
        .is_err()
    {
        clear_clmm_exact_quote_outstanding_request(request_capacity, intent.pool_index, request_id);
        record_clmm_exact_quote_request_publish_full();
        trace_clmm_exact_quote_request_slot_publish(
            intent,
            request_id,
            amount_in,
            previous_request_id,
            previous_sequence,
            false,
            "publish_failed",
        );
        return ClmmExactQuotePrimeResult {
            outcome: ClmmExactQuotePrimeOutcome::PublishFailed,
            request_amount_in: amount_in,
            request_id,
            publish_ok_unix_ns: 0,
            timeout_diag: None,
        };
    }
    record_clmm_exact_quote_request_publish_ok();
    let publish_ok_unix_ns = unix_timestamp_now_ns_u64();
    if let Some(ready_ring) = ready_ring {
        let ready =
            ClmmExactQuoteReadyIndex64B::new(intent.pool_index, request_id, publish_ok_unix_ns);
        let _ = ready_ring.push(&ready);
    }
    trace_clmm_exact_quote_request_slot_publish(
        intent,
        request_id,
        amount_in,
        previous_request_id,
        previous_sequence,
        false,
        "published",
    );

    let Some(quote_arena) = quote_arena else {
        clear_clmm_exact_quote_outstanding_request(request_capacity, intent.pool_index, request_id);
        return ClmmExactQuotePrimeResult {
            outcome: ClmmExactQuotePrimeOutcome::QuoteArenaMissing,
            request_amount_in: amount_in,
            request_id,
            publish_ok_unix_ns,
            timeout_diag: None,
        };
    };

    let deadline = Instant::now() + Duration::from_millis(wait_budget_ms);
    loop {
        for (_, snapshot) in quote_arena
            .read_stable_with_sequences_at(intent.pool_index)
            .into_iter()
            .flatten()
        {
            if clmm_exact_quote_matches_request(snapshot, &request, intent) {
                clear_clmm_exact_quote_outstanding_request(
                    request_capacity,
                    intent.pool_index,
                    request_id,
                );
                if (snapshot.validity_flags & CLMM_EXACT_QUOTE_FLAG_NO_QUOTE) != 0 {
                    record_clmm_exact_quote_request_outstanding_cleared_no_quote();
                } else {
                    record_clmm_exact_quote_request_outstanding_cleared_matched();
                }
                record_clmm_exact_quote_response_matched();
                return ClmmExactQuotePrimeResult {
                    outcome: ClmmExactQuotePrimeOutcome::QuoteMatched,
                    request_amount_in: amount_in,
                    request_id,
                    publish_ok_unix_ns,
                    timeout_diag: None,
                };
            }
        }
        if Instant::now() >= deadline {
            let timeout_diag = build_clmm_exact_quote_timeout_diag(
                quote_arena.read_stable_with_sequences_at(intent.pool_index),
                &request,
                intent,
            );
            clear_clmm_exact_quote_outstanding_request(
                request_capacity,
                intent.pool_index,
                request_id,
            );
            record_clmm_exact_quote_request_outstanding_cleared_timeout();
            record_clmm_exact_quote_response_timeout(timeout_diag);
            return ClmmExactQuotePrimeResult {
                outcome: ClmmExactQuotePrimeOutcome::QuoteWaitTimeout,
                request_amount_in: amount_in,
                request_id,
                publish_ok_unix_ns,
                timeout_diag: Some(timeout_diag),
            };
        }
        std::thread::sleep(Duration::from_millis(1));
    }
}

#[inline(always)]
fn route_family_code(route: RouteDecision, public_rpc_scout_explicit: bool) -> u8 {
    route_family_telemetry_code(route, public_rpc_scout_explicit)
}

#[inline(always)]
fn tactic_family_code(kind: IntentKind) -> u8 {
    match kind {
        IntentKind::Atba => 0,
        IntentKind::ApexPartial => 1,
        _ => 2,
    }
}

#[inline(always)]
fn rollout_base_event(record: &IngressRecord, resolved: &ResolvedRecord) -> RolloutShadowEvent {
    let primary_signer = if record.flat_accounts_len > 0 {
        record.flat_accounts[0]
    } else {
        [0u8; 32]
    };
    RolloutShadowEvent {
        unix_ns: record.unix_ns,
        slot: record.slot,
        pool_index: resolved.pool_index,
        mint_index: resolved.mint_out_index,
        venue_id: record.venue_id,
        signal_source: record.signal_source,
        rollout_mode: shadow_core::assembly::ROLLOUT_MODE_OBSERVE_ONLY,
        cap_rung: shadow_core::assembly::ROLLOUT_CAP_R0_OBSERVE_ONLY,
        signature: record.signature,
        primary_signer,
        pool_pubkey: record.pool_pubkey,
        mint_in: record.mint_in,
        mint_out: record.mint_out,
        ingress_unix_ns: record.unix_ns,
        target_entity_id: record.entity_id,
        ..Default::default()
    }
}

#[inline(always)]
fn apply_rollout_opso_metadata(event: &mut RolloutShadowEvent, intent: &WorkerIntent) {
    event.episode_id_mod = intent.opso_episode_id_mod;
    event.opso_owner_mode = intent.opso_owner_mode;
    event.opso_fallback_mode = intent.opso_fallback_mode;
    event.opso_reason_code = intent.opso_reason_code;
}

#[inline(always)]
fn emit_rollout_shadow(shared: &SharedRefs<'_>, event: RolloutShadowEvent) {
    if let Some(sink) = shared.rollout_shadow_sink {
        if sink.try_push_shadow(&event) {
            record_rollout_shadow_publish_diag(&event);
        }
    }
}

#[inline(always)]
pub(crate) fn record_rollout_shadow_publish_diag(event: &RolloutShadowEvent) {
    WORKER_SHADOW_EVENTS_PUBLISHED.fetch_add(1, Ordering::Relaxed);
    record_dpdk_worker_counter(event.signal_source, &DPDK_WORKER_ROLLOUT_SHADOW_PUBLISHED);
    if event.would_send {
        WORKER_ROLLOUT_WOULD_SEND_EVENTS_PUBLISHED.fetch_add(1, Ordering::Relaxed);
    }
    if event.live_send_suppressed {
        WORKER_ROLLOUT_LIVE_SEND_SUPPRESSED_EVENTS_PUBLISHED.fetch_add(1, Ordering::Relaxed);
    }
}

#[inline(always)]
pub(crate) fn record_final_no_send_event_constructed_diag(event: &RolloutShadowEvent) {
    WORKER_FINAL_NO_SEND_EVENT_CONSTRUCTED.fetch_add(1, Ordering::Relaxed);
    WORKER_FINAL_NO_SEND_DROP_REASON_LAST.store(event.drop_reason as u64, Ordering::Relaxed);
}

#[inline(always)]
pub(crate) fn record_final_no_send_event_publish_result_diag(
    event: &RolloutShadowEvent,
    published: bool,
) {
    if published {
        WORKER_FINAL_NO_SEND_EVENT_PUBLISHED.fetch_add(1, Ordering::Relaxed);
        record_dpdk_worker_counter(event.signal_source, &DPDK_WORKER_FINAL_NO_SEND_PUBLISHED);
        crate::tail_latency::record_final_no_send_publish(event);
        record_rollout_shadow_publish_diag(event);
    } else {
        WORKER_FINAL_NO_SEND_EVENT_PUBLISH_ERR.fetch_add(1, Ordering::Relaxed);
        WORKER_FINAL_NO_SEND_DROP_REASON_LAST.store(event.drop_reason as u64, Ordering::Relaxed);
    }
}

#[inline(always)]
fn g12_drop_reason_from_route_reason(reason: RouteReason) -> G12DropReason {
    match reason {
        RouteReason::PublicTarget => G12DropReason::DroppedPublicTarget,
        RouteReason::PublicRpcScoutDirect => G12DropReason::None,
        RouteReason::StaleHarmonicNoJito => G12DropReason::DroppedHarmonicStaleState,
        RouteReason::QuarantinedHarmonicNoJito => G12DropReason::DroppedHarmonicStaleState,
        RouteReason::TacticMaskNoJito => G12DropReason::DroppedHarmonicTacticMask,
        RouteReason::HarmonicEgressGateNoJito => G12DropReason::DroppedEgressGateHarmonic,
        RouteReason::OverCap => G12DropReason::DroppedRolloutCap,
        RouteReason::NoViableRoute | RouteReason::AtbaNoJito | RouteReason::ApexPartialNoJito => {
            G12DropReason::DroppedEgressGateJito
        }
        RouteReason::JitoEgressGateFallback => G12DropReason::ReroutedPreSignEgressGate,
        RouteReason::JitoStaleHarmonicReroute | RouteReason::JitoQuarantinedFallback => {
            G12DropReason::DroppedHarmonicStaleState
        }
        RouteReason::JitoTacticMaskFallback => G12DropReason::DroppedHarmonicTacticMask,
        RouteReason::JitoAtba
        | RouteReason::JitoApexPartial
        | RouteReason::HarmonicFreshPlain
        | RouteReason::JitoDirect => G12DropReason::None,
    }
}

#[inline(always)]
fn emit_route_drop_event(
    shared: &SharedRefs<'_>,
    record: &IngressRecord,
    resolved: &ResolvedRecord,
    route: &HydratedRoute,
) {
    let drop_reason = g12_drop_reason_from_route_reason(route.outcome.reason);
    let mut event = rollout_base_event(record, resolved);
    event.route_family = route_family_code(
        route.outcome.decision,
        shared.routing_cfg.public_rpc_scout_explicit,
    );
    event.drop_reason = drop_reason.as_u16();
    event.egress_gate_drop = u8::from(matches!(
        drop_reason,
        G12DropReason::DroppedEgressGateJito | G12DropReason::DroppedEgressGateHarmonic
    ));
    emit_rollout_shadow(shared, event);
}

#[inline(always)]
fn emit_route_opportunity_event(
    shared: &SharedRefs<'_>,
    record: &IngressRecord,
    resolved: &ResolvedRecord,
    route: &HydratedRoute,
    intent: &WorkerIntent,
) {
    let mut event = rollout_base_event(record, resolved);
    apply_rollout_opso_metadata(&mut event, intent);
    event.route_family = route_family_code(
        route.outcome.decision,
        shared.routing_cfg.public_rpc_scout_explicit,
    );
    event.tactic_family = tactic_family_code(intent.kind);
    event.private_lane_admissible =
        u8::from(!is_observe_shadow_geyser_signal(record.signal_source));
    event.stale_state_reroute =
        u8::from(route.outcome.reason == RouteReason::JitoStaleHarmonicReroute);
    event.egress_gate_reroute =
        u8::from(route.outcome.reason == RouteReason::JitoEgressGateFallback);
    event.clamped_apex_candidate = u8::from(intent.kind == IntentKind::ApexPartial);
    emit_rollout_shadow(shared, event);
}

#[inline(always)]
fn g12_drop_reason_from_pipeline_error(
    error: &PipelineError,
) -> Option<(G12DropReason, bool, bool)> {
    match error {
        PipelineError::RoutingDropped(reason) => Some((
            g12_drop_reason_from_route_reason(*reason),
            matches!(
                *reason,
                RouteReason::HarmonicEgressGateNoJito
                    | RouteReason::NoViableRoute
                    | RouteReason::AtbaNoJito
                    | RouteReason::ApexPartialNoJito
            ),
            false,
        )),
        PipelineError::PolicyRejected(policy_reason) => match policy_reason {
            PolicyDropReason::ApexPartialNotPositive => {
                Some((G12DropReason::DroppedApexNotPositive, false, false))
            }
            PolicyDropReason::AtbaMissingOrStaleDistToTick => {
                Some((G12DropReason::DroppedAtbaNoDistToTick, false, true))
            }
            PolicyDropReason::DominanceGateLiveSuppressed => {
                Some((G12DropReason::DroppedDominanceGate, false, false))
            }
            PolicyDropReason::NoUsableLutBank => {
                Some((G12DropReason::DroppedNoUsableLutBank, false, false))
            }
            PolicyDropReason::NetAfterFeeFloor => None,
            _ => None,
        },
        PipelineError::EmitFailed(EmitError::BuildFailed(BuildError::InvalidGuardPubkey)) => {
            Some((G12DropReason::DroppedNoShadowGuard, false, false))
        }
        _ => None,
    }
}

#[inline(always)]
fn emit_pipeline_drop_event(
    shared: &SharedRefs<'_>,
    record: &IngressRecord,
    resolved: &ResolvedRecord,
    route: &HydratedRoute,
    intent: &WorkerIntent,
    error: &PipelineError,
) {
    let Some((drop_reason, egress_gate_drop, atba_missing_dist_candidate)) =
        g12_drop_reason_from_pipeline_error(error)
    else {
        return;
    };
    let mut event = rollout_base_event(record, resolved);
    apply_rollout_opso_metadata(&mut event, intent);
    event.route_family = route_family_code(
        route.outcome.decision,
        shared.routing_cfg.public_rpc_scout_explicit,
    );
    event.tactic_family = tactic_family_code(intent.kind);
    event.drop_reason = drop_reason.as_u16();
    event.egress_gate_drop = u8::from(egress_gate_drop);
    event.dominance_live_drop = u8::from(drop_reason == G12DropReason::DroppedDominanceGate);
    event.atba_missing_dist_candidate = u8::from(atba_missing_dist_candidate);
    emit_rollout_shadow(shared, event);
}

/// Worker hot loop.  Polls feed rings round-robin.
///
/// **Gate order** (G4-G1b/G1c/G1d/G1e):
/// 1. SigDedupe — drop duplicate sig_tag64 before any lookup.
/// 2. Early-drop gates — health, staleness, pool/mint resolution.
/// 3. Route hydration — `derive_route_inputs_guerrila` → drop on None/Drop.
/// 4. `process_intent` → quote → policy → template → sign → egress enqueue.
///
/// Both Jito and Harmonic egress rings are live.  Routing decides the lane;
/// the pipeline pushes to the appropriate ring via `PipelineInputs`.
///
/// Dominance gate fires inside `process_intent` → `resolve_execution_policy`
/// → `evaluate_and_update_dominance` (thread_local!, no explicit wiring).
fn money_worker_loop(
    worker_id: u32,
    feed_rings: &[MappedSpscRing<IngressRecord>],
    jito_ring: &MappedSpscRing<SignedTxEnvelope>,
    tpu_ring: &MappedSpscRing<SignedTxEnvelope>,
    harmonic_ring: &MappedSpscRing<SignedTxEnvelope>,
    shared_nonces: &SharedNonceRing,
    local: &mut WorkerLocalState,
    shared: &SharedRefs<'_>,
    clmm_exact_quote_request_arena: Option<&MappedClmmExactQuoteRequestArena>,
    clmm_exact_quote_ready_ring: Option<&MappedSpscRing<ClmmExactQuoteReadyIndex64B>>,
    opso_sidecar: Option<&MappedSegment<OpsShockSidecarSnapshot>>,
    opso_stale_action: shadow_core::config::OpsoStaleAction,
    opso_max_staleness_ns: u64,
) {
    let n = feed_rings.len();
    if n == 0 {
        eprintln!("money-worker-{worker_id}: no feed rings, parking");
        loop {
            thread::park();
        }
    }

    let mut cursor: usize = 0;
    let mut idle_streak: u32 = 0;

    loop {
        // Refill local nonce ring from the shared SPSC ring (background producer).
        drain_shared_into_local(shared_nonces, &mut local.nonce_ring);

        // Round-robin poll across all feed rings for this worker.
        match feed_rings[cursor].pop() {
            Some(record) => {
                idle_streak = 0;

                // Gate 1: signature dedupe.  Extract sig_tag64 from the first
                // 8 bytes of the Ed25519 signature and check the thread-local
                // ring.  Duplicate → drop immediately, no pool/mint lookup.
                let replay_exact_target = is_run40_scorecard_replay_exact_target(&record);
                if replay_exact_target {
                    trace_run40_scorecard_replay_gate(&record, "worker_dequeue", "before_dedupe");
                }
                let tag = SigDedupe::tag64(&record.signature);
                let dedupe_hit = local.dedupe.check_and_insert(tag);
                if replay_exact_target {
                    if dedupe_hit {
                        trace_run40_scorecard_replay_gate(
                            &record,
                            "dedupe_bypass",
                            "sig_tag_already_present",
                        );
                    }
                } else if dedupe_hit {
                    cursor = (cursor + 1) % n;
                    continue;
                }

                WORKER_RECORDS_SEEN.fetch_add(1, Ordering::Relaxed);
                record_dpdk_worker_counter(record.signal_source, &DPDK_WORKER_RECORDS_SEEN);
                record_signal_source_diag(record.signal_source);
                crate::tail_latency::record_worker_dequeue(&record);
                if source_probe_drop_recorded(&record) {
                    crate::tail_latency::record_processing_complete(&record);
                    cursor = (cursor + 1) % n;
                    continue;
                }

                // Gates 2–7: health, staleness, pool/mint resolution.
                let resolved = match run_early_drop_gates(worker_id, &record, shared) {
                    Some(r) => r,
                    None => {
                        crate::tail_latency::record_processing_complete(&record);
                        cursor = (cursor + 1) % n;
                        continue;
                    }
                };

                // Gate 8: route hydration (G4-G1d).
                // First pass: resolve engine + leader_class_id. Tactic class
                // not yet known → Harmonic gated closed.  process_intent
                // re-hydrates with the resolved class for authoritative gating.
                WORKER_ROUTE_ATTEMPTS.fetch_add(1, Ordering::Relaxed);
                let route = match hydrate_route_observed(
                    &record,
                    IntentKind::PlainWithinCap,
                    None, // harmonic_tactic_class
                    true, // jito_compatible_now
                    true, // timing_margin_ok
                    shared,
                ) {
                    HydratedRouteOutcome::Actionable(mut route) => {
                        let private_bundle_overridden =
                            apply_private_bundle_route_override(&mut route, shared.routing_cfg);
                        let run40_tpu_quic_overridden = apply_run40_tpu_quic_route_override(
                            &record,
                            &mut route,
                            shared.rollout_no_send_backend,
                        );
                        let replay_route_overridden = apply_run40_scorecard_replay_route_override(
                            shared, &record, &mut route,
                        );
                        if private_bundle_overridden
                            || run40_tpu_quic_overridden
                            || replay_route_overridden
                        {
                            WORKER_TPU_QUIC_CANDIDATE_SEEN.fetch_add(1, Ordering::Relaxed);
                        }
                        match apply_target_public_scout_route_override(&record, &mut route) {
                            TargetPublicScoutRouteAction::Forced {
                                previous_decision,
                                previous_reason,
                            } => {
                                trace_target_public_scout_route_override(
                                    &record,
                                    previous_decision,
                                    previous_reason,
                                );
                            }
                            TargetPublicScoutRouteAction::Blocked(reason) => {
                                trace_target_public_scout_blocked(
                                    &record, &route, "route", reason, "",
                                );
                            }
                            TargetPublicScoutRouteAction::NotApplicable => {}
                        }
                        WORKER_ROUTE_ACTIONABLE.fetch_add(1, Ordering::Relaxed);
                        record_dpdk_worker_counter(
                            record.signal_source,
                            &DPDK_WORKER_ROUTE_ACTIONABLE,
                        );
                        if record.signal_source == SIGNAL_SOURCE_AFXDP {
                            WORKER_R1_AFXDP_PRIVATE_GRADE_ROUTE_ACTIONABLE
                                .fetch_add(1, Ordering::Relaxed);
                        }
                        record_route_reason_diag(route.outcome.reason);
                        record_route_decision_diag(route.outcome.decision);
                        record_run38_target_route_resolved(&record, route.outcome.decision);
                        route
                    }
                    HydratedRouteOutcome::Dropped(mut route) => {
                        let run40_tpu_quic_overridden = apply_run40_tpu_quic_route_override(
                            &record,
                            &mut route,
                            shared.rollout_no_send_backend,
                        );
                        let replay_route_overridden = apply_run40_scorecard_replay_route_override(
                            shared, &record, &mut route,
                        );
                        if run40_tpu_quic_overridden || replay_route_overridden {
                            WORKER_TPU_QUIC_CANDIDATE_SEEN.fetch_add(1, Ordering::Relaxed);
                        }
                        match apply_target_public_scout_route_override(&record, &mut route) {
                            TargetPublicScoutRouteAction::Forced {
                                previous_decision,
                                previous_reason,
                            } => {
                                trace_target_public_scout_route_override(
                                    &record,
                                    previous_decision,
                                    previous_reason,
                                );
                            }
                            TargetPublicScoutRouteAction::Blocked(reason) => {
                                trace_target_public_scout_blocked(
                                    &record, &route, "route", reason, "",
                                );
                            }
                            TargetPublicScoutRouteAction::NotApplicable => {}
                        }
                        if run40_tpu_quic_overridden || replay_route_overridden {
                            WORKER_ROUTE_ACTIONABLE.fetch_add(1, Ordering::Relaxed);
                            record_dpdk_worker_counter(
                                record.signal_source,
                                &DPDK_WORKER_ROUTE_ACTIONABLE,
                            );
                            if record.signal_source == SIGNAL_SOURCE_AFXDP {
                                WORKER_R1_AFXDP_PRIVATE_GRADE_ROUTE_ACTIONABLE
                                    .fetch_add(1, Ordering::Relaxed);
                            }
                            record_route_reason_diag(route.outcome.reason);
                            record_route_decision_diag(route.outcome.decision);
                            record_run38_target_route_resolved(&record, route.outcome.decision);
                            route
                        } else if geyser_shadow_no_send_allowed(shared, &record, &route) {
                            WORKER_GEYSER_SHADOW_NO_SEND_ADMITTED.fetch_add(1, Ordering::Relaxed);
                            record_geyser_shadow_no_send_source_diag(record.signal_source);
                            WORKER_ROUTE_ACTIONABLE.fetch_add(1, Ordering::Relaxed);
                            record_dpdk_worker_counter(
                                record.signal_source,
                                &DPDK_WORKER_ROUTE_ACTIONABLE,
                            );
                            if record.signal_source == SIGNAL_SOURCE_AFXDP {
                                WORKER_R1_AFXDP_PRIVATE_GRADE_ROUTE_ACTIONABLE
                                    .fetch_add(1, Ordering::Relaxed);
                            }
                            let shadow_route = shadow_no_send_route_from_public_drop(&route);
                            record_route_reason_diag(shadow_route.outcome.reason);
                            record_route_decision_diag(shadow_route.outcome.decision);
                            shadow_route
                        } else {
                            if is_observe_shadow_geyser_signal(record.signal_source)
                                && route.outcome.reason == RouteReason::PublicTarget
                            {
                                WORKER_GEYSER_SHADOW_NO_SEND_REJECTED
                                    .fetch_add(1, Ordering::Relaxed);
                            }
                            WORKER_ROUTE_DROPPED.fetch_add(1, Ordering::Relaxed);
                            record_dpdk_worker_counter(
                                record.signal_source,
                                &DPDK_WORKER_ROUTE_DROPPED,
                            );
                            WORKER_CANDIDATES_DROPPED_BEFORE_PROCESS_INTENT
                                .fetch_add(1, Ordering::Relaxed);
                            trace_public_rpc_scout_clmm_census_route(&record, &route, false);
                            record_route_reason_diag(route.outcome.reason);
                            record_route_decision_diag(route.outcome.decision);
                            if route.outcome.reason == RouteReason::HarmonicEgressGateNoJito {
                                WORKER_PRESIGN_GATE_REJECT.fetch_add(1, Ordering::Relaxed);
                            }
                            emit_route_drop_event(shared, &record, &resolved, &route);
                            crate::tail_latency::record_processing_complete(&record);
                            cursor = (cursor + 1) % n;
                            continue;
                        }
                    }
                    HydratedRouteOutcome::UnavailableUnknownSignal => {
                        WORKER_ROUTE_UNAVAILABLE.fetch_add(1, Ordering::Relaxed);
                        record_dpdk_worker_counter(
                            record.signal_source,
                            &DPDK_WORKER_ROUTE_UNAVAILABLE,
                        );
                        WORKER_ROUTE_UNAVAILABLE_UNKNOWN_SIGNAL.fetch_add(1, Ordering::Relaxed);
                        record_dpdk_worker_counter(
                            record.signal_source,
                            &DPDK_WORKER_ROUTE_UNAVAILABLE_UNKNOWN_SIGNAL,
                        );
                        crate::tail_latency::record_processing_complete(&record);
                        cursor = (cursor + 1) % n;
                        continue;
                    }
                    HydratedRouteOutcome::UnavailableHydrationNone => {
                        WORKER_ROUTE_UNAVAILABLE.fetch_add(1, Ordering::Relaxed);
                        record_dpdk_worker_counter(
                            record.signal_source,
                            &DPDK_WORKER_ROUTE_UNAVAILABLE,
                        );
                        WORKER_ROUTE_UNAVAILABLE_HYDRATION_NONE.fetch_add(1, Ordering::Relaxed);
                        record_dpdk_worker_counter(
                            record.signal_source,
                            &DPDK_WORKER_ROUTE_UNAVAILABLE_HYDRATION_NONE,
                        );
                        if record.signal_source == SIGNAL_SOURCE_AFXDP {
                            WORKER_ROUTE_UNAVAILABLE_HYDRATION_NONE_AFXDP
                                .fetch_add(1, Ordering::Relaxed);
                        }
                        crate::tail_latency::record_processing_complete(&record);
                        cursor = (cursor + 1) % n;
                        continue;
                    }
                };
                trace_public_rpc_scout_clmm_census_route(&record, &route, true);

                // G4-G1e: build intent → process_intent → egress enqueue.
                // Routing decides Jito vs Harmonic; pipeline pushes to the
                // correct ring via PipelineInputs.
                let opso_metadata = read_opso_metadata(
                    record.unix_ns,
                    resolved.pool_index,
                    opso_sidecar,
                    opso_stale_action,
                    opso_max_staleness_ns,
                );
                let mut intent = build_worker_intent(
                    &record,
                    &resolved,
                    &route,
                    shared.route_base_cu_limit,
                    &shared.intent_shape,
                    shared.r1_live_admission,
                    opso_metadata,
                );
                apply_route_intent_overrides(
                    &mut intent,
                    &record,
                    &route,
                    shared.rollout_no_send_backend,
                );
                emit_route_opportunity_event(shared, &record, &resolved, &route, &intent);
                let fencer = InventoryFencer {
                    current_allocation: shared.inventory_alloc,
                    absolute_ceiling: shared.inventory_ceiling,
                };
                // Read active LUT banks from shm (O(1) Acquire load per iteration).
                // Returns None if oracle hasn't published yet → policy drops.
                let jito_lut = shared.tip_lut_jito.payload().inner.active_bank();
                let base_lut = shared.tip_lut_base.payload().inner.active_bank();
                let r1_admits = r1_auto_admission_admits(
                    shared, &record, &resolved, &route, &intent, jito_lut, base_lut,
                );
                if r1_auto_admission_blocks_process_intent(
                    shared.rollout_no_send_backend,
                    r1_admits,
                ) {
                    let reason = match r1_admits {
                        R1AutoAdmissionOutcome::Admitted => "admitted",
                        R1AutoAdmissionOutcome::Dropped(reason_code) => {
                            encode_r1_drop_reason(reason_code)
                        }
                        R1AutoAdmissionOutcome::ProofFilterDrop => "proof_filter",
                        R1AutoAdmissionOutcome::TemplateExecutabilityDrop => {
                            "template_executability"
                        }
                        R1AutoAdmissionOutcome::AttemptLatchDrop => "attempt_latch",
                    };
                    trace_public_rpc_scout_clmm_census_pre_process_drop(&record, &route, reason);
                    if exact_target_public_scout_record(&record)
                        && route.outcome.decision == RouteDecision::PublicRpcScout
                    {
                        trace_target_public_scout_blocked(
                            &record,
                            &route,
                            "pre_process_drop",
                            TargetPublicScoutBlockedReason::GuardFailed,
                            reason,
                        );
                    }
                    WORKER_CANDIDATES_DROPPED_BEFORE_PROCESS_INTENT.fetch_add(1, Ordering::Relaxed);
                    record_dpdk_worker_counter(
                        record.signal_source,
                        &DPDK_WORKER_R1_ADMISSION_DROP,
                    );
                    crate::tail_latency::record_processing_complete(&record);
                    cursor = (cursor + 1) % n;
                    continue;
                }
                if r1_auto_admission_admitted(r1_admits) {
                    record_r1_admit_to_process_intent_attempt();
                }
                let (swap_accounts, swap_ix_data) = match runtime_swap_template_for_record(
                    shared,
                    &record,
                    &resolved,
                    &intent,
                    route.outcome.decision,
                ) {
                    Ok(template) => template,
                    Err(template_drop) => {
                        record_template_drop(template_drop);
                        let template_drop_reason =
                            encode_template_drop_reason(template_drop.reason);
                        if trace_public_rpc_scout_emit_enabled()
                            && route.outcome.decision == RouteDecision::PublicRpcScout
                        {
                            println!(
                                "TRACE public_rpc_scout_template_drop venue_id={} pool={} template_variant={} reason={} signature={}",
                                record.venue_id,
                                bs58::encode(record.pool_pubkey).into_string(),
                                record.template_variant,
                                template_drop_reason,
                                bs58::encode(record.signature).into_string(),
                            );
                        }
                        trace_public_rpc_scout_clmm_census_pre_process_drop(
                            &record,
                            &route,
                            template_drop_reason,
                        );
                        if exact_target_public_scout_record(&record)
                            && route.outcome.decision == RouteDecision::PublicRpcScout
                        {
                            trace_target_public_scout_blocked(
                                &record,
                                &route,
                                template_drop_reason,
                                TargetPublicScoutBlockedReason::TemplateInvalid,
                                template_drop_reason,
                            );
                        }
                        if r1_auto_admission_admitted(r1_admits) {
                            record_r1_admit_to_process_intent_drop(
                                &record,
                                &route,
                                R1AdmitToProcessIntentDropReason::TemplateDrop,
                                Some(classify_public_scout_shape_reject_from_template_drop(
                                    &record,
                                    &route,
                                    template_drop.reason,
                                )),
                            );
                        }
                        WORKER_CANDIDATES_DROPPED_BEFORE_PROCESS_INTENT
                            .fetch_add(1, Ordering::Relaxed);
                        crate::tail_latency::record_processing_complete(&record);
                        cursor = (cursor + 1) % n;
                        continue;
                    }
                };
                let quote_wait_budget_ms = clmm_exact_quote_request_wait_ms(&record);
                let quote_request_outcome = prime_clmm_exact_quote_request(
                    clmm_exact_quote_request_arena.as_deref(),
                    clmm_exact_quote_ready_ring,
                    shared.clmm_exact_quote_arena,
                    &intent,
                    quote_wait_budget_ms,
                );
                trace_public_rpc_scout_clmm_quote_request(&record, &intent, quote_request_outcome);
                trace_run40_scorecard_replay_quote_result(
                    &record,
                    &intent,
                    quote_request_outcome,
                    quote_wait_budget_ms,
                );
                if intent.venue_id == ingest_venue::RAYDIUM_CLMM
                    && quote_request_outcome.outcome != ClmmExactQuotePrimeOutcome::QuoteMatched
                {
                    if route.outcome.decision == RouteDecision::PublicRpcScout {
                        trace_public_rpc_scout_clmm_census_pre_process_drop(
                            &record,
                            &route,
                            encode_clmm_exact_quote_prime_outcome(quote_request_outcome.outcome),
                        );
                    }
                    if r1_auto_admission_admitted(r1_admits) {
                        let drop_reason = match quote_request_outcome.outcome {
                            ClmmExactQuotePrimeOutcome::RequestArenaMissing => {
                                R1AdmitToProcessIntentDropReason::RequestArenaMissing
                            }
                            ClmmExactQuotePrimeOutcome::AmountPreviewFailed => {
                                R1AdmitToProcessIntentDropReason::AmountPreviewFailed
                            }
                            ClmmExactQuotePrimeOutcome::PublishFailed => {
                                R1AdmitToProcessIntentDropReason::PublishFailed
                            }
                            ClmmExactQuotePrimeOutcome::QuoteArenaMissing => {
                                R1AdmitToProcessIntentDropReason::QuoteArenaMissing
                            }
                            ClmmExactQuotePrimeOutcome::OutstandingSamePool => {
                                R1AdmitToProcessIntentDropReason::OutstandingSamePool
                            }
                            ClmmExactQuotePrimeOutcome::QuoteWaitTimeout => {
                                R1AdmitToProcessIntentDropReason::QuoteWaitTimeout
                            }
                            ClmmExactQuotePrimeOutcome::NotClmm
                            | ClmmExactQuotePrimeOutcome::QuoteMatched => {
                                R1AdmitToProcessIntentDropReason::None
                            }
                        };
                        if drop_reason != R1AdmitToProcessIntentDropReason::None {
                            record_r1_admit_to_process_intent_drop(
                                &record,
                                &route,
                                drop_reason,
                                None,
                            );
                        }
                    }
                    WORKER_CANDIDATES_DROPPED_BEFORE_PROCESS_INTENT.fetch_add(1, Ordering::Relaxed);
                    crate::tail_latency::record_processing_complete(&record);
                    cursor = (cursor + 1) % n;
                    continue;
                }
                if r1_auto_admission_admitted(r1_admits) {
                    record_r1_admit_to_process_intent_ok();
                    trace_run40_scorecard_replay_gate(
                        &record,
                        "admit_to_process_intent_ok",
                        encode_route_decision(route.outcome.decision),
                    );
                }
                let mut inputs = PipelineInputs {
                    ingress_slot: record.slot,
                    intent: &intent,
                    blockhash: shared.blockhash.payload(),
                    leader_schedule: shared.leader_schedule.payload(),
                    risk_flags: shared.risk_flags.payload(),
                    health: shared.health.payload(),
                    egress_health: shared.egress_health.payload(),
                    pool_map: shared.pool_tag_map,
                    pool_arena: shared.pool_arena,
                    clmm_exact_quote_arena: shared.clmm_exact_quote_arena,
                    clmm_exact_quote_request_id: quote_request_outcome.request_id,
                    mint_map: shared.mint_tag_map,
                    mint_arena: shared.mint_arena,
                    cfg: shared.routing_cfg,
                    hydrated_route_override: Some(&route),
                    jito_lut_bank: jito_lut,
                    harmonic_lut_bank: base_lut,
                    inventory_fencer: &fencer,
                    nonce_ring: &mut local.nonce_ring,
                    jito_ring,
                    tpu_ring,
                    harmonic_ring,
                    overlay: &mut local.overlay,
                    rollout_shadow_sink: shared.rollout_shadow_sink,
                    rollout_no_send_backend: shared.rollout_no_send_backend,
                    force_live_inventory_reservation: run40_replay_force_live_inventory_reservation(
                        &record,
                        &route,
                        shared.rollout_no_send_backend,
                    ),
                    swap_accounts,
                    swap_ix_data,
                    jito_tip_rotation: shared.jito_tip_rotation,
                    route_base_cu_limit: shared.route_base_cu_limit,
                    signer: shared.signer,
                    shadow_guard_program_id: shared.shadow_guard_program_id,
                    guard_vault_in_pubkey: shared.guard_vault_in_pubkey,
                    guard_vault_out_pubkey: shared.guard_vault_out_pubkey,
                    worker_id: worker_id as u8,
                    quant_tactics: shared.quant_tactics.as_ref(),
                };
                // process_intent handles all rollback internally on failure.
                let _result = process_intent_with_diagnostics(
                    shared,
                    &record,
                    &resolved,
                    &route,
                    &intent,
                    &mut inputs,
                );
                // Release nonce_ring and overlay borrows so the exhaust-scavenging
                // backrun path can reborrow them for the follow-on process_intent call.
                drop(inputs);

                // G9A: tactic attribution counters — observe-only, thread-local, zero alloc.
                if let Some(qt) = shared.quant_tactics.as_ref() {
                    // 1. CU density
                    let density_enabled = qt
                        .cu_density_optimization
                        .as_ref()
                        .map(|c| c.enabled)
                        .unwrap_or(false);
                    if intent.jito_compatible_now {
                        let tip = intent.pre_tip_retained_lcb_lamports;
                        let cu = shared.route_base_cu_limit;
                        if density_enabled {
                            local.tac.record_density_intent(tip, cu);
                        } else {
                            local.tac.record_baseline_jito(tip, cu);
                        }
                    }

                    // 2. Exhaust scavenging — compute convexity from competitor size relative
                    //    to config-supplied pool reserve estimate, then build a deterministic
                    //    Jito backrun (capped at 15 SOL) when the tactic is eligible.
                    let scav = {
                        let convexity_bps =
                            qt.post_trade_exhaust_scavenging.as_ref().map_or(0, |cfg| {
                                let pool_reserve =
                                    (cfg.estimated_pool_reserve_sol * 1_000_000_000.0) as u64;
                                estimate_convexity_bps(intent.target_gross_amount_in, pool_reserve)
                            });
                        evaluate_exhaust_scavenging(
                            intent.target_gross_amount_in,
                            convexity_bps,
                            false,
                            qt.post_trade_exhaust_scavenging.as_ref(),
                        )
                    };
                    let mut scav_event = rollout_base_event(&record, &resolved);
                    apply_rollout_opso_metadata(&mut scav_event, &intent);
                    scav_event.tactic_family = tactic_family_code(IntentKind::PlainWithinCap);
                    scav_event.exhaust_candidate = 1;
                    scav_event.exhaust_win =
                        u8::from(matches!(scav, ExhaustScavengingDecision::Eligible { .. }));
                    emit_rollout_shadow(shared, scav_event);
                    if route.outcome.decision != RouteDecision::PublicRpcScout {
                        if let ExhaustScavengingDecision::Eligible {
                            max_deploy_lamports,
                        } = scav
                        {
                            let deploy_lamports =
                                max_deploy_lamports.min(EXHAUST_SCAVENGING_DEPLOY_CAP_LAMPORTS);
                            // Build deterministic Jito backrun: same pool + direction as the
                            // competitor's trade, deploy_lamports capped at 15 SOL, forced Jito
                            // routing, not observe-only.
                            let backrun_intent = WorkerIntent {
                                kind: IntentKind::PlainWithinCap,
                                amount: deploy_lamports,
                                source: intent.source,
                                signal_source: intent.signal_source,
                                expected_pool_pubkey: intent.expected_pool_pubkey,
                                expected_mint_in_pubkey: intent.expected_mint_in_pubkey,
                                expected_mint_out_pubkey: intent.expected_mint_out_pubkey,
                                target_gross_amount_in: intent.target_gross_amount_in,
                                dist_to_tick_lamports: None,
                                obscurity_score: intent.obscurity_score,
                                tactic_class: Some(TacticReasonCode::ExhaustScavenging as u8),
                                direction: intent.direction,
                                pool_index: intent.pool_index,
                                observe_only: shared.rollout_no_send_backend || intent.observe_only,
                                alpha_bucket: intent.alpha_bucket,
                                venue_id: intent.venue_id,
                                pre_tip_retained_lcb_lamports: intent.pre_tip_retained_lcb_lamports,
                                min_net_after_fee_lamports: intent.min_net_after_fee_lamports,
                                min_incremental_retained_lcb_lamports: intent
                                    .min_incremental_retained_lcb_lamports,
                                cu_price_reciprocal_q32: intent.cu_price_reciprocal_q32,
                                jito_compatible_now: true,
                                timing_margin_ok: true,
                                published_apex_partial_lamports: 0,
                                slip_bps: intent.slip_bps,
                                alpha_lcb_lamports: intent.alpha_lcb_lamports,
                                deadline_unix_ns: intent.deadline_unix_ns,
                                ingress_unix_ns: intent.ingress_unix_ns,
                                max_pool_staleness_ns: intent.max_pool_staleness_ns,
                                max_mint_staleness_ns: intent.max_mint_staleness_ns,
                                max_alt_staleness_ns: intent.max_alt_staleness_ns,
                                trade_fee_num: intent.trade_fee_num,
                                trade_fee_denom: intent.trade_fee_denom,
                                opso_episode_id_mod: intent.opso_episode_id_mod,
                                opso_owner_mode: intent.opso_owner_mode,
                                opso_fallback_mode: intent.opso_fallback_mode,
                                opso_reason_code: intent.opso_reason_code,
                                opso_bid_ceiling_bucket: intent.opso_bid_ceiling_bucket,
                                opso_fallback_value_bucket: intent.opso_fallback_value_bucket,
                                opso_backrun_value_bucket: intent.opso_backrun_value_bucket,
                            };
                            let (guard_vault_in_pubkey, guard_vault_out_pubkey) =
                                guard_vaults_for_live_intent(shared, &record);
                            trace_public_rpc_scout_guard_context(
                                &route,
                                &record,
                                guard_vault_in_pubkey,
                                guard_vault_out_pubkey,
                                "exhaust",
                            );
                            if let Ok((swap_accounts, swap_ix_data)) =
                                runtime_swap_template_for_record(
                                    shared,
                                    &record,
                                    &resolved,
                                    &backrun_intent,
                                    route.outcome.decision,
                                )
                            {
                                prime_clmm_exact_quote_request(
                                    clmm_exact_quote_request_arena.as_deref(),
                                    clmm_exact_quote_ready_ring,
                                    shared.clmm_exact_quote_arena,
                                    &backrun_intent,
                                    clmm_exact_quote_request_wait_ms(&record),
                                );
                                let mut br_inputs = PipelineInputs {
                                    ingress_slot: record.slot,
                                    intent: &backrun_intent,
                                    blockhash: shared.blockhash.payload(),
                                    leader_schedule: shared.leader_schedule.payload(),
                                    risk_flags: shared.risk_flags.payload(),
                                    health: shared.health.payload(),
                                    egress_health: shared.egress_health.payload(),
                                    pool_map: shared.pool_tag_map,
                                    pool_arena: shared.pool_arena,
                                    clmm_exact_quote_arena: shared.clmm_exact_quote_arena,
                                    clmm_exact_quote_request_id: 0,
                                    mint_map: shared.mint_tag_map,
                                    mint_arena: shared.mint_arena,
                                    cfg: shared.routing_cfg,
                                    hydrated_route_override: None,
                                    jito_lut_bank: jito_lut,
                                    harmonic_lut_bank: base_lut,
                                    inventory_fencer: &fencer,
                                    nonce_ring: &mut local.nonce_ring,
                                    jito_ring,
                                    tpu_ring,
                                    harmonic_ring,
                                    overlay: &mut local.overlay,
                                    rollout_shadow_sink: shared.rollout_shadow_sink,
                                    rollout_no_send_backend: shared.rollout_no_send_backend,
                                    force_live_inventory_reservation: false,
                                    swap_accounts,
                                    swap_ix_data,
                                    jito_tip_rotation: shared.jito_tip_rotation,
                                    route_base_cu_limit: shared.route_base_cu_limit,
                                    signer: shared.signer,
                                    shadow_guard_program_id: shared.shadow_guard_program_id,
                                    guard_vault_in_pubkey,
                                    guard_vault_out_pubkey,
                                    worker_id: worker_id as u8,
                                    quant_tactics: shared.quant_tactics.as_ref(),
                                };
                                let _ = shadow_core::pipeline::process_intent(&mut br_inputs);
                            }
                        }
                    }
                    local.tac.record_exhaust_evaluation(scav);

                    // 3. Tick-boundary shadow telemetry
                    if let Some(event) = evaluate_tick_boundary_shadow(
                        intent.target_gross_amount_in,
                        intent.dist_to_tick_lamports,
                        qt.tick_boundary_sabotage.as_ref(),
                    ) {
                        // Emit TickBoundaryCorrelation for observe-only Rosetta sink.
                        // Pure telemetry — never modifies live sizing or routing.
                        if let TickBoundaryShadowEvent::WouldPushTickBoundary {
                            trade_size_lamports,
                            dist_to_tick_lamports,
                        } = event
                        {
                            let corr = TickBoundaryCorrelation {
                                pool_index: intent.pool_index,
                                trade_size_lamports,
                                dist_to_tick_lamports,
                                proximity_threshold_lamports: qt
                                    .tick_boundary_sabotage
                                    .as_ref()
                                    .map(|c| c.proximity_threshold_lamports)
                                    .unwrap_or(0),
                                ingress_unix_ns: intent.ingress_unix_ns,
                                slot: record.slot,
                            };
                            println!(
                                "[g9a_tick_boundary] pool={} size_lam={} dist_lam={} \
                                 thresh_lam={} slot={} ns={}",
                                corr.pool_index,
                                corr.trade_size_lamports,
                                corr.dist_to_tick_lamports,
                                corr.proximity_threshold_lamports,
                                corr.slot,
                                corr.ingress_unix_ns,
                            );
                        }
                        local.tac.record_tick_boundary(event);
                    }

                    // Periodic telemetry export (per Jito decision count)
                    let jito_total = local.tac.cu_density_intents + local.tac.baseline_jito_intents;
                    if jito_total > 0 && jito_total % TACTIC_TELEMETRY_INTERVAL == 0 {
                        log_tactic_telemetry(worker_id, &local.tac);
                    }
                }

                crate::tail_latency::record_processing_complete(&record);
            }
            None => {
                idle_streak += 1;
            }
        }

        cursor = (cursor + 1) % n;

        // Backoff: after a full empty sweep, yield to avoid burning CPU.
        if idle_streak >= n as u32 {
            idle_streak = 0;
            std::hint::spin_loop();
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SupportedPathLatencyProbeSource {
    Dpdk,
    Afxdp,
}

impl SupportedPathLatencyProbeSource {
    fn signal_source(self) -> u8 {
        match self {
            Self::Dpdk => SIGNAL_SOURCE_DPDK,
            Self::Afxdp => SIGNAL_SOURCE_AFXDP,
        }
    }

    fn as_str(self) -> &'static str {
        match self {
            Self::Dpdk => "dpdk",
            Self::Afxdp => "afxdp",
        }
    }
}

