fn probe_r1_manual_allowlist_config() -> R1LiveAdmissionRuntimeConfig {
    R1LiveAdmissionRuntimeConfig {
        mode: shadow_core::config::R1LiveAdmissionMode::ManualAllowlist,
        ..R1LiveAdmissionRuntimeConfig::default()
    }
}

fn probe_monotonic_ns() -> u64 {
    static MONO_EPOCH: OnceLock<Instant> = OnceLock::new();
    MONO_EPOCH.get_or_init(Instant::now).elapsed().as_nanos() as u64
}

fn probe_now_ns(signal_source: u8) -> u64 {
    if signal_source == SIGNAL_SOURCE_AFXDP || signal_source == SIGNAL_SOURCE_DPDK {
        probe_monotonic_ns()
    } else {
        crate::tail_latency::current_unix_ns()
    }
}

fn probe_temp_root() -> Result<std::path::PathBuf, String> {
    let nonce = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_nanos())
        .unwrap_or(0);
    let root = std::env::temp_dir().join(format!(
        "shadow-tier0-latency-probe-{}-{}",
        std::process::id(),
        nonce
    ));
    fs::create_dir_all(&root)
        .map_err(|err| format!("failed to create probe temp dir {}: {err}", root.display()))?;
    Ok(root)
}

fn probe_quantiles(samples: &[u64]) -> SupportedPathLatencyProbeQuantiles {
    if samples.is_empty() {
        return SupportedPathLatencyProbeQuantiles::default();
    }
    let mut sorted = samples.to_vec();
    sorted.sort_unstable();
    let last = sorted.len() - 1;
    let pick = |num: usize, den: usize| -> u64 { sorted[(last * num) / den] };
    SupportedPathLatencyProbeQuantiles {
        count: sorted.len() as u64,
        p50_ns: pick(500, 1000),
        p90_ns: pick(900, 1000),
        p95_ns: pick(950, 1000),
        p99_ns: pick(990, 1000),
        p999_ns: pick(999, 1000),
        max_ns: sorted[last],
    }
}

