    #[test]
    fn clmm_quote_request_id_advances_above_stale_pool_snapshot_after_restart() {
        let _lock = lock_worker_diagnostics_for_test();
        clear_clmm_exact_quote_outstanding_requests();

        let fx = G1cFixture::build();
        let record = build_raydium_clmm_pipeline_record(SIGNAL_SOURCE_DPDK);
        let shared = fx.shared_refs();
        let resolved = run_early_drop_gates(0, &record, &shared).expect("resolved");
        let route = match hydrate_route_observed(
            &record,
            IntentKind::PlainWithinCap,
            None,
            true,
            true,
            &shared,
        ) {
            HydratedRouteOutcome::Actionable(route) => route,
            _ => panic!("unexpected route outcome"),
        };
        let intent = build_worker_intent(
            &record,
            &resolved,
            &route,
            300_000,
            &DEFAULT_INTENT_SHAPE,
            test_r1_manual_allowlist_config(),
            OpsoObserveOnlyMetadata::baseline(OpsoObserveOnlyReasonCode::SidecarMissing),
        );

        let dir = tempfile::tempdir().unwrap();
        let request_path = dir.path().join("clmm_exact_quote_request");
        let quote_path = dir.path().join("clmm_exact_quote");
        let request_arena = MappedClmmExactQuoteRequestArena::create_rw(&request_path, 4).unwrap();
        let mut quote_arena = MappedClmmExactQuoteArena::create_rw(&quote_path, 4).unwrap();
        let amount_in = preview_trade_size_for_intent(&intent).expect("preview");

        let mut stale_request = ClmmExactQuoteRequestPayload128B {
            pool_pubkey: intent.expected_pool_pubkey,
            mint_in_pubkey: intent.expected_mint_in_pubkey,
            mint_out_pubkey: intent.expected_mint_out_pubkey,
            target_amount_in: intent.target_gross_amount_in,
            amount_in,
            request_unix_ns: intent.ingress_unix_ns.saturating_sub(10),
            slip_bps: intent.slip_bps,
            direction: intent.direction,
            validity_flags: CLMM_EXACT_QUOTE_REQUEST_FLAG_VALID,
            reserved: [0; 4],
        };
        stale_request.set_request_id(4);
        request_arena
            .publish_at(intent.pool_index, stale_request)
            .unwrap();

        let mut stale_quote = ClmmExactQuotePayload192B {
            pool_pubkey: intent.expected_pool_pubkey,
            mint_in_pubkey: intent.expected_mint_in_pubkey,
            mint_out_pubkey: intent.expected_mint_out_pubkey,
            amount_in,
            expected_out: 1,
            min_out: 1,
            projected_reserve_in: 1,
            projected_reserve_out: 1,
            quote_epoch: 7,
            last_update_unix_ns: intent.ingress_unix_ns.saturating_add(1),
            post_sqrt_price_x64: 1,
            post_tick: 0,
            crossed_tick_count: 0,
            direction: intent.direction,
            validity_flags: shadow_ipc::clmm_exact_quote_sidecar::CLMM_EXACT_QUOTE_FLAG_VALID,
            status: shadow_ipc::clmm_exact_quote_sidecar::CLMM_EXACT_QUOTE_STATUS_UNSPECIFIED,
            reserved: [0; 7],
        };
        stale_quote.set_request_id(5);
        quote_arena
            .publish_at(intent.pool_index, stale_quote)
            .unwrap();

        let cursor_before = CLMM_EXACT_QUOTE_REQUEST_ID_CURSOR
            .load(Ordering::Acquire)
            .max(1);
        let result = prime_clmm_exact_quote_request(
            Some(&request_arena),
            None,
            Some(&quote_arena),
            &intent,
            CLMM_EXACT_QUOTE_REQUEST_WAIT_MS,
        );

        assert_eq!(result.outcome, ClmmExactQuotePrimeOutcome::QuoteWaitTimeout);
        assert!(
            result.request_id >= cursor_before.max(6),
            "request_id must advance above stale per-pool request/snapshot ids"
        );
        let active_request = request_arena
            .read_active_at(intent.pool_index)
            .expect("published request");
        assert_eq!(active_request.request_id(), result.request_id);
    }

