        assert_eq!(
            diag.last_public_scout_shape_reject_route,
            "public_rpc_scout"
        );
        assert_eq!(diag.last_public_scout_shape_reject_source, "afxdp");
        assert_eq!(diag.last_public_scout_shape_reject_venue, "raydium_clmm");
        assert_eq!(
            diag.last_public_scout_shape_reject_pool_pubkey,
            record.pool_pubkey
        );
