    #[test]
    fn strict_target_public_scout_override_forces_exact_target_route() {
        let _guard = lock_worker_diagnostics_for_test();
        reset_worker_diagnostics_for_test();
        set_require_target_public_scout_for_test(Some(true));

        let mut fx = G1cFixture::build();
        let mut record = G1cFixture::passing_record();
        record.signal_source = SIGNAL_SOURCE_AFXDP;
        *PUBLIC_SCOUT_PROOF_FILTER_OVERRIDE
            .get_or_init(|| Mutex::new(None))
            .lock()
            .expect("public scout proof filter override mutex poisoned") =
            Some(PublicScoutProofFilter {
                allow_only_venue_id: Some(record.venue_id),
                allow_only_pool_pubkey: Some(record.pool_pubkey),
                allow_only_mint_in_pubkey: Some(record.mint_in),
                allow_only_mint_out_pubkey: Some(record.mint_out),
            });

        fx.routing_cfg.public_rpc_scout_route_enabled = true;
        let shared = fx.shared_refs();
        let mut route = hydrate_route(
            &record,
            IntentKind::PlainWithinCap,
            None,
            true,
            true,
            &shared,
        )
        .expect("route must hydrate");
        assert_eq!(route.outcome.decision, RouteDecision::JitoBundle);

        let action = apply_target_public_scout_route_override(&record, &mut route);
        assert_eq!(
            action,
            TargetPublicScoutRouteAction::Forced {
                previous_decision: RouteDecision::JitoBundle,
                previous_reason: RouteReason::JitoDirect,
            }
        );
        assert_eq!(route.outcome.decision, RouteDecision::PublicRpcScout);
        assert_eq!(route.outcome.reason, RouteReason::PublicRpcScoutDirect);

        set_require_target_public_scout_for_test(None);
        *PUBLIC_SCOUT_PROOF_FILTER_OVERRIDE
            .get_or_init(|| Mutex::new(None))
            .lock()
            .expect("public scout proof filter override mutex poisoned") = None;
    }

