    #[test]
    fn scorecard_replay_route_override_converts_exact_public_target_drop() {
        let _guard = lock_worker_diagnostics_for_test();
        reset_worker_diagnostics_for_test();

        let fx = G1cFixture::build();
        let mut shared = fx.shared_refs();
        shared.rollout_no_send_backend = true;

        let mut record = G1cFixture::passing_record();
        record.signal_source = SIGNAL_SOURCE_EXTERNAL_GEYSER;
        record.signature = [0x77; 64];
        set_run40_scorecard_replay_source_override_for_test(Some(
            Run40ScorecardReplaySourceOverride {
                enabled: true,
                selected_signature: record.signature,
                selected_pool_pubkey: record.pool_pubkey,
            },
        ));

        let mut route = match hydrate_route_observed(
            &record,
            IntentKind::PlainWithinCap,
            None,
            true,
            true,
            &shared,
        ) {
            HydratedRouteOutcome::Dropped(route) => route,
            _ => panic!("expected dropped public target route"),
        };
        assert_eq!(route.outcome.decision, RouteDecision::Drop);
        assert_eq!(route.outcome.reason, RouteReason::PublicTarget);

        assert!(apply_run40_scorecard_replay_route_override(
            &shared, &record, &mut route
        ));
        assert_eq!(route.outcome.decision, RouteDecision::TpuQuicPublic);
        assert_eq!(route.outcome.reason, RouteReason::PublicRpcScoutDirect);

        let diag = snapshot_worker_diagnostics();
        assert_eq!(diag.scorecard_replay_route_override_seen, 1);
        assert_eq!(diag.scorecard_replay_route_override_applied, 1);
        assert_eq!(diag.scorecard_replay_route_override_signature_match, 1);
        assert_eq!(diag.scorecard_replay_route_override_pool_match, 1);
        assert_eq!(diag.scorecard_replay_route_override_from_public_target, 1);
        assert_eq!(diag.scorecard_replay_route_override_to_tpu_quic_public, 1);

        set_run40_scorecard_replay_source_override_for_test(None);
    }

