    #[test]
    fn clmm_runtime_swap_template_uses_decoded_instruction_shape() {
        let fx = G1cFixture::build();
        let record = build_raydium_clmm_pipeline_record(SIGNAL_SOURCE_DPDK);
        let shared = fx.shared_refs();
        let resolved = run_early_drop_gates(0, &record, &shared).expect("resolved");
        let route = match hydrate_route_observed(
            &record,
            IntentKind::PlainWithinCap,
            None,
            true,
            true,
            &shared,
        ) {
            HydratedRouteOutcome::Actionable(route) => route,
            _ => panic!("unexpected route outcome"),
        };
        let intent = build_worker_intent(
            &record,
            &resolved,
            &route,
            300_000,
            &DEFAULT_INTENT_SHAPE,
            test_r1_manual_allowlist_config(),
            OpsoObserveOnlyMetadata::baseline(OpsoObserveOnlyReasonCode::SidecarMissing),
        );

        let (swap_accounts, swap_ix_data) = runtime_swap_template_for_record(
            &shared,
            &record,
            &resolved,
            &intent,
            RouteDecision::JitoBundle,
        )
        .expect("CLMM record must produce runtime swap template");

        assert_eq!(swap_accounts.program_id, RAYDIUM_CLMM_PROGRAM_ID);
        assert_eq!(
            swap_accounts.num_accounts as usize,
            record.ix_account_count as usize
        );
        assert!(swap_accounts.num_accounts >= 13);
        assert!(matches!(
            swap_accounts.metas[0].source,
            SwapAccountSource::FeePayerSigner
        ));
        assert_eq!(swap_ix_data.len, 41);
        assert_eq!(swap_ix_data.amount_in_offset, 8);
        assert_eq!(swap_ix_data.min_out_offset, 16);
    }

    #[test]
    fn clmm_swap_builder_rewrites_user_token_accounts_when_signer_atas_are_supplied() {
        let record = build_raydium_clmm_pipeline_record(SIGNAL_SOURCE_DPDK);
        let signer_pubkey = [0x44; 32];
        let input_ata = shadow_core::pda::derive_ata_for_token_program(
            &signer_pubkey,
            &shadow_core::pda::TOKEN_PROGRAM_ID,
            &TEST_MINT_IN_PUBKEY,
        )
        .expect("fixture input ata");
        let output_ata = shadow_core::pda::derive_ata_for_token_program(
            &signer_pubkey,
            &shadow_core::pda::TOKEN_PROGRAM_ID,
            &TEST_MINT_OUT_PUBKEY,
        )
        .expect("fixture output ata");
        let victim_input_ata = record.flat_accounts[record.pattern_acct_indices[2] as usize];
        let victim_output_ata = record.flat_accounts[record.pattern_acct_indices[3] as usize];

        let swap_accounts =
            build_clmm_swap_accounts_from_record(&record, Some((input_ata, output_ata)))
                .expect("clmm swap accounts");

        let input_meta_pos = record.ix_account_indices[..record.ix_account_count as usize]
            .iter()
            .position(|idx| *idx == record.pattern_acct_indices[2])
            .expect("input token account index");
        let output_meta_pos = record.ix_account_indices[..record.ix_account_count as usize]
            .iter()
            .position(|idx| *idx == record.pattern_acct_indices[3])
            .expect("output token account index");
        assert_ne!(input_ata, victim_input_ata);
        assert_ne!(output_ata, victim_output_ata);
        assert_eq!(
            swap_accounts.metas[input_meta_pos].source,
            SwapAccountSource::ExplicitPubkey(input_ata)
        );
        assert_eq!(
            swap_accounts.metas[output_meta_pos].source,
            SwapAccountSource::ExplicitPubkey(output_ata)
        );
    }

