    #[test]
    fn afxdp_pool_state_miss_is_explicitly_accounted() {
        let _lock = lock_worker_diagnostics_for_test();
        reset_worker_diagnostics_for_test();
        let hydration_flags = ensure_test_hydration_flags();

        let fx = G1cFixture::build();
        let shared = fx.shared_refs();
        let mut record = G1cFixture::passing_record();
        record.signal_source = SIGNAL_SOURCE_AFXDP;
        record.pool_pubkey = [0xDD; 32];
        let expected_snapshot_slot = shared
            .health
            .payload()
            .read_active()
            .expect("health snapshot")
            .snapshot_slot;

        let resolved = run_early_drop_gates(0, &record, &shared);
        assert!(resolved.is_none());

        let diag = snapshot_worker_diagnostics();
        assert_eq!(diag.pool_state_miss, 1);
        assert_eq!(diag.worker_pool_state_miss_tag_map_absent, 1);
        assert_eq!(diag.worker_pool_state_miss_arena_oob, 0);
        assert_eq!(diag.worker_pool_state_miss_arena_torn, 0);
        assert_eq!(diag.worker_pool_state_miss_pubkey_mismatch, 0);
        assert_eq!(
            diag.last_worker_pool_state_miss_pool_pubkey,
            record.pool_pubkey
        );
        assert_eq!(diag.last_worker_pool_state_miss_venue_id, record.venue_id);
        assert_eq!(
            diag.last_worker_pool_state_miss_signal_source,
            SIGNAL_SOURCE_AFXDP
        );
        assert_eq!(
            diag.last_worker_pool_state_miss_reason_code,
            DPDK_POOL_STATE_MISS_REASON_TAG_MAP_ABSENT
        );
        let hint = hydration_flags
            .payload()
            .snapshot_hot_pool_hint_slot(0)
            .expect("expected AF_XDP hydration hint");
        assert_eq!(hint.signal_source, SIGNAL_SOURCE_AFXDP);
        assert_eq!(hint.pool_pubkey, record.pool_pubkey);
        assert_eq!(diag.worker_pool_state_miss_recent_ring.len(), 1);
        let recent = diag.worker_pool_state_miss_recent_ring[0];
        assert_eq!(recent.pool_pubkey, record.pool_pubkey);
        assert_eq!(recent.timestamp_ns, record.unix_ns);
        assert_eq!(recent.record_slot, record.slot);
        assert_eq!(recent.health_snapshot_slot, expected_snapshot_slot);
        assert_eq!(
            diag.worker_pool_state_miss_top_recent,
            vec![WorkerPoolStateMissTopRecentEntry {
                pool_pubkey: record.pool_pubkey,
                count: 1,
                first_seen_ns: record.unix_ns,
                last_seen_ns: record.unix_ns,
                reason_code: DPDK_POOL_STATE_MISS_REASON_TAG_MAP_ABSENT,
            }]
        );
    }

