    #[test]
    fn hydration_hints_use_distinct_slots_for_back_to_back_misses() {
        let _lock = lock_worker_diagnostics_for_test();
        reset_worker_diagnostics_for_test();
        let hydration_flags = ensure_test_hydration_flags();

        let fx = G1cFixture::build();
        let shared = fx.shared_refs();
        let mut record_a = G1cFixture::passing_record();
        record_a.signal_source = SIGNAL_SOURCE_AFXDP;
        record_a.pool_pubkey = [0xA1; 32];

        let mut record_b = G1cFixture::passing_record();
        record_b.signal_source = SIGNAL_SOURCE_AFXDP;
        record_b.pool_pubkey = [0xB2; 32];

        assert!(run_early_drop_gates(0, &record_a, &shared).is_none());
        assert!(run_early_drop_gates(0, &record_b, &shared).is_none());

        let hint_a = hydration_flags
            .payload()
            .snapshot_hot_pool_hint_slot(0)
            .expect("first hint should occupy slot 0 after reset");
        let hint_b = hydration_flags
            .payload()
            .snapshot_hot_pool_hint_slot(1)
            .expect("second hint should occupy slot 1 after reset");

        assert_eq!(hint_a.pool_pubkey, record_a.pool_pubkey);
        assert_eq!(hint_b.pool_pubkey, record_b.pool_pubkey);
    }

